        local ok,err
        if source=='inventory' then
            local name=tostring(it.name or '')
            local ench=tonumber(it.ench) or tonumber(name:match('%(%+(%d+)%)%s*$')) or 0
            local base=name:gsub('%s+%(%+%d+%)%s*$','')
            local row=DSP.market.row_for(base,ench)
            if row then ok,err=DSP.presets.add(row,kind)
            else ok,err=DSP.presets.add_manual(kind,{name=base,ench=ench,price=0,
                qty=math.max(1,tonumber(it.count or it.qty) or 1),enabled=false,needs_price=true}) end
        else
            ok,err=DSP.presets.add(it,kind)
            if not ok and err=='нет цены для расчёта' then
                ok,err=DSP.presets.add_manual(kind,{name=it.name or it.display,ench=it.ench or 0,
                    price=0,qty=1,enabled=false,needs_price=true})
            end
        end
        report(ok,err)
        if ok then U.trade_preset_page=math.max(1,math.ceil(#DSP.presets.items(kind)/5)) end
    end
end
function U.trade_tab()
    U.preset_kind=U.preset_kind or 'buy'
    U.trade_section=U.trade_section or 'items'
    local kind=U.preset_kind
    local running=DSP.auto.buy_running or DSP.auto.sell_running
    -- Keep advanced management accessible without occupying the everyday workspace.
    if U.trade_section=='library' then
        if M.button('< Назад к торговле','mh_back_library',250) then U.trade_section='items' end
        preset_library(kind)
        return
    elseif U.trade_section=='manual' then
        if M.button('< Назад к торговле','mh_back_manual',250) then U.trade_section='items' end
        manual_entry(kind)
        return
    end
    if M.button('СКУПКА','kind_buy',210,kind=='buy','segment') then
        U.preset_kind='buy';kind='buy';U.trade_preset_page=1
    end
    M.inline()
    if M.button('ПРОДАЖА','kind_sell',210,kind=='sell','segment') then
        U.preset_kind='sell';kind='sell';U.trade_preset_page=1
    end
    local p=kind=='buy' and DSP.settings.buy_preset or DSP.settings.sell_preset
    local list=DSP.presets.list(kind)
    local selected=DSP.presets.selected(kind)
    M.text('Набор: '..tostring(p.name or 'Основной'))
    if M.button('<','preset_prev',68) and not running then
        DSP.presets.select(kind,selected>1 and selected-1 or #list)
    end
    M.inline()
    if M.button('>','preset_next',68) and not running then
        DSP.presets.select(kind,selected<#list and selected+1 or 1)
    end
    M.inline()
    if M.button('Пресеты','trade_library',160) then U.trade_section='library';return end
    M.inline()
    if M.button('Добавить вручную','trade_manual',230) then U.trade_section='manual';return end
    -- Shared availability: on smaller windows switch between the two panels
    -- instead of crushing numeric controls into unreadable columns.
    local available=imgui.GetContentRegionAvail and imgui.GetContentRegionAvail() or {x=900,y=600}
    local total_width=available and available.x or 900
    local height=available and available.y or 540
    local per=math.max(2,math.min(5,math.floor((height-125)/130)))
    local picker=U.trade_picker or 'inventory'
    local two=total_width>=980 and M.child~=nil
    local panel_h=math.max(160,height-102)
    if not two then
        if M.button('Добавить товар','mh_switch_picker',190,U.trade_narrow_picker) then U.trade_narrow_picker=true end
        M.inline()
        if M.button('Мой набор','mh_switch_preset',180,not U.trade_narrow_picker) then U.trade_narrow_picker=false end
    end
    local function draw_picker()
        if M.button('Инвентарь','mh_source_inv',182,picker=='inventory') then picker='inventory';U.trade_picker=picker;U.trade_picker_page=1 end
        M.inline()
        if M.button('Поиск','mh_source_catalog',144,picker=='catalog') then picker='catalog';U.trade_picker=picker;U.trade_picker_page=1 end
        local entries={}
        if picker=='inventory' then
            if M.button('Сканировать','scan_inventory',180) then DSP.auto.scan_inventory() end
            M.text('Инвентарь: '..tostring(DSP.auto.inv_status or 'не сканирован'))
            entries=DSP.auto.inv or {}
        else
            U.catalog_search=U.catalog_search or imgui.new.char[128]()
            imgui.SetNextItemWidth(math.min(430,imgui.GetContentRegionAvail().x))
            if imgui.InputTextWithHint('##catalog_quick_search',DSP.utf8('Название предмета...'),U.catalog_search,128) then
                U.trade_picker_page=1
            end
            entries=catalog_rows(DSP.to_cp(ffi.string(U.catalog_search)))
            if #entries==0 then M.text('Введите название предмета.') end
        end
        M.text('Найдено: '..tostring(#entries))
        local start,finish=page_buttons('trade_picker_page',#entries,per)
        for i=start,finish do picker_row(kind,entries[i],i,picker) end
    end
    local function draw_preset()
        local current=kind=='buy' and DSP.settings.buy_preset or DSP.settings.sell_preset
        local positions,subtotal=0,0
        for _,it in ipairs(current.items or {}) do
            if it.enabled~=false and (tonumber(it.price) or 0)>0 and (tonumber(it.qty) or 0)>0 then
                positions=positions+1;subtotal=subtotal+it.price*it.qty
            end
        end
        M.text('В наборе: '..#current.items..' | Активных: '..positions..' | '..DSP.money(subtotal))
        local start,finish=page_buttons('trade_preset_page',#current.items,per)
        for i=start,finish do if item_card(kind,current.items[i],i) then break end end
        if #current.items==0 then M.text('Добавьте предмет слева: он сразу появится в наборе.') end
        U.trade_active_positions=positions
    end
    if two then
        local left=math.max(340,math.floor(total_width*.39))
        pane('mh_inventory',left,panel_h,draw_picker)
        M.inline()
        pane('mh_preset',0,panel_h,draw_preset)
    elseif U.trade_narrow_picker then
        pane('mh_picker_single',0,panel_h,draw_picker)
    else
        pane('mh_preset_single',0,panel_h,draw_preset)
    end
    -- Always-visible controls, independent of either list's scrolling position.
    if running then M.text(DSP.auto.status_text())
    else M.toggle('Тест без выставления',DSP.settings,'dry_run',true) end
    local label=running and 'ОСТАНОВИТЬ' or (DSP.settings.dry_run and 'ПРОВЕРИТЬ НАБОР' or 'ВЫСТАВИТЬ '..(kind=='buy' and 'СКУПКУ' or 'ПРОДАЖУ'))
    if M.button(label,'run_'..kind,500,true,'primary') then
        if DSP.auto.buy_running then DSP.auto.stop_buy()
        elseif DSP.auto.sell_running then DSP.auto.stop_sell()
        elseif DSP.presets.active_count(kind)==0 then DSP.notify('Включите товары с ценой и количеством')
        elseif kind=='buy' then DSP.auto.safe_start('buy') else DSP.auto.safe_start('sell') end
    end
end
U.palatka_tab=U.trade_tab
function U.auto_tab()
    M.title('АВТОМАТИЗАЦИЯ')
    M.text(DSP.auto.status_text())
    M.text('Автоматизация выставляет товары. Счётчик показывает подтверждённые позиции, а не завершённые сделки.')
    if DSP.auto.progress then
        local p=DSP.auto.progress
        M.text('Обработано '..tostring(p.done or 0)..' из '..tostring(p.total or 0)..' | Ошибок '..tostring(p.failed or 0))
    end
    for _,kind in ipairs({'buy','sell'}) do
        local running=kind=='buy' and DSP.auto.buy_running or kind=='sell' and DSP.auto.sell_running
        local label=kind=='buy' and 'СКУПКИ' or 'ПРОДАЖИ'
        M.title(label)
        M.text('Позиций: '..DSP.presets.active_count(kind))
        if M.button((running and 'СТОП ' or 'СТАРТ ')..label,'auto_'..kind,400,running) then
            if kind=='buy' then
                if running then DSP.auto.stop_buy() else DSP.auto.safe_start('buy') end
            else
                if running then DSP.auto.stop_sell() else DSP.auto.safe_start('sell') end
            end
        end
    end
    M.toggle('Тест без отправки',DSP.settings,'dry_run',true)
    M.text('Последние события')
    for i=1,math.min(15,#DSP.log) do M.text((DSP.log[i].t or '')..' '..tostring(DSP.log[i].text)) end
end

end
__mod_37_mobile_trade()

local function __mod_37_trade_v16()
-- Palatka 1.6: single-column Market Helper workflow, touch-first.
-- Trading engine remains in 40_auto, 41_trade_listing and 42_trade_buy.
local ffi=require('ffi')
local U,M=DSP.ui,DSP.mobile
local T={}
DSP.trade_v16=T
U.v16_side=U.v16_side or 'sell'
U.v16_tab=U.v16_tab or 'items'
U.v16_source=U.v16_source or 'inventory'
U.v16_page=U.v16_page or 1

local function busy() return DSP.auto.buy_running or DSP.auto.sell_running end
local function current(kind) return kind=='sell' and DSP.settings.sell_preset or DSP.settings.buy_preset end
local max_integer=9007199254740991
local function quantity(v)
    local n=tonumber(v)
    if n and n==n and n>0 and n<=max_integer and n%1==0 then return n end
end
-- Planning arithmetic is independent of inventory availability and execution.
function T.calculate_totals(kind,items,tax_bp,edits)
    local out={positions=0,qty=0,enabled=0,invalid=0,unknown_cost=0,overflow=false,
        gross=0,commission=0,net=0,cost=0,complete=true}
    local tax=tonumber(tax_bp)
    if tax==nil then tax=200 end
    if kind=='sell' and (tax~=tax or tax<0 or tax>10000 or tax%1~=0) then
        out.invalid_tax=true;tax=0
    end
    for _,it in ipairs(type(items)=='table' and items or {}) do
        if type(it)~='table' then
            out.invalid=out.invalid+1
        elseif it.enabled~=false then
            out.enabled=out.enabled+1
            local price,qty=quantity(it.price),quantity(it.qty)
            local bad=edits and edits[it]
            if not price or not qty or (bad and (bad.price or bad.qty)) then out.invalid=out.invalid+1
            elseif price>max_integer/qty or out.gross>max_integer-price*qty then
                out.overflow=true
            else
                local amount=price*qty
                out.positions,out.qty=out.positions+1,out.qty+qty
                out.gross=out.gross+amount
                if kind=='sell' then
                    local factor=10000-tax
                    local net=math.floor(amount/10000)*factor+math.floor((amount%10000)*factor/10000)
                    out.net=out.net+net;out.commission=out.commission+amount-net
                    local cost=tonumber(it.cost_price)
                    if not cost or cost~=cost or cost<0 or cost>max_integer or cost%1~=0 or (bad and bad.cost_price) then
                        out.unknown_cost=out.unknown_cost+1
                    elseif cost>max_integer/qty or out.cost>max_integer-cost*qty then
                        out.cost_overflow=true
                    else out.cost=out.cost+cost*qty end
                end
            end
        end
    end
    out.complete=out.invalid==0 and not out.overflow and not out.invalid_tax
    if not out.complete then
        out.gross,out.net,out.commission,out.cost=nil,nil,nil,nil
    elseif kind=='buy' then
        out.required_funds=out.gross;out.net,out.cost=nil,nil
    elseif out.unknown_cost>0 or out.cost_overflow then out.cost=nil
    else out.profit=out.net-out.cost end
    return out
end
function T.totals(kind)
    local p=current(kind)
    return T.calculate_totals(kind,type(p)=='table' and p.items or {},DSP.settings.tax_bp,M.invalid_edits)
end
local function safe_key(it)
    local name=tostring(it.name or it.display or '')
    local ench=tonumber(it.ench) or tonumber(name:match('%(%+(%d+)%)%s*$')) or 0
    local base=name:gsub('%s+%(%+%d+%)%s*$','')
    return base,ench,DSP.item_key(base,ench)
end
local function inventory_counts()
    local counts,slots={},{}
    for _,it in ipairs(DSP.auto.inv or {}) do
        local _,_,key=safe_key(it)
        local count=0
        if type(it.stacks)=='table' and #it.stacks>0 then
            for _,st in ipairs(it.stacks) do
                local n=quantity(st.count)
                if n and st.slot~=nil and not slots[st.slot] then
                    count=count+n;slots[st.slot]=true
                end
            end
        else count=quantity(it.count or it.qty) or 0 end
        counts[key]=(counts[key] or 0)+count
    end
    return counts
end
function T.add_from_inventory(kind,it)
    if busy() then return false,'остановите выставление' end
    if type(it)~='table' then return false,'нет предмета' end
    local base,ench,key=safe_key(it)
    local count=quantity(it.count or it.qty)
    if not count then return false,'нет доступного количества' end
    if kind=='sell' then
        for _,owned in ipairs(DSP.auto.inv or {}) do
            if owned==it then count=inventory_counts()[key] or count;break end
        end
    end
    if not quantity(count) then return false,'некорректное количество' end
    local index,exists=DSP.presets.find(kind,key)
    if exists then
        -- Re-tapping updates quantity; it MUST NOT overwrite the user's price.
        if kind=='sell' then exists.qty=count end
        M.refresh_buffer(exists,'qty')
        M.defer_save()
        return true,'количество обновлено'
    end
    local ok,err=DSP.presets.add_manual(kind,{name=base,ench=ench,qty=kind=='sell' and count or 1,
        price=0,enabled=false,needs_price=true})
    return ok,err
end
function T.add_from_catalog(kind,it)
    if busy() then return false,'остановите выставление' end
    local base,ench,key=safe_key(it)
    if DSP.presets.find(kind,key) then return true,'уже в пресете' end
    return DSP.presets.add_manual(kind,{name=base,ench=ench,qty=1,price=0,
        enabled=false,needs_price=true})
end
function T.validate(kind)
    -- A malformed imported/old preset must never throw from an ImGui callback.
    local p=current(kind)
    if type(p)~='table' or type(p.items)~='table' then
        return false,{'preset data unavailable'},0
    end
    local problems,items,total={},p.items,0
    local inventory={}
    if kind=='sell' then
        for _,entry in ipairs(DSP.auto.inv or {}) do
            if type(entry)~='table' or type(entry.stacks)~='table' or #entry.stacks==0 then
                return false,{'inventory slot data missing; rescan inventory'},0
            end
            for _,slot in ipairs(entry.stacks) do
                if type(slot)~='table' or type(slot.slot)~='number' or slot.slot<0 or
                    slot.slot>1000 or slot.slot%1~=0 then
                    return false,{'inventory slot invalid; rescan inventory'},0
                end
            end
        end
        local ok,counts=pcall(inventory_counts)
        if not ok then return false,{'inventory scan data damaged: '..tostring(counts)},0 end
        inventory=counts
    end
    local enabled=0
    for i,it in ipairs(items) do
        if type(it)~='table' then
            problems[#problems+1]='invalid preset row # '..i
        elseif it.enabled~=false then
            enabled=enabled+1
            local name=tostring(it.name or it.display or ('item # '..i))
            if type(it.name)~='string' or it.name=='' then
                problems[#problems+1]='invalid item name # '..i
            else
                local price,qty=quantity(it.price),quantity(it.qty)
                local edits=M.invalid_edits and M.invalid_edits[it]
                if not price or not qty or (edits and (edits.price or edits.qty)) then
                    problems[#problems+1]=name..': invalid price or amount'
                elseif price>max_integer/qty or total>max_integer-price*qty then
                    problems[#problems+1]=name..': amount exceeds numeric range'
                else
                    if kind=='sell' then
                        local _,_,key=safe_key(it)
                        local avail=inventory[key] or 0
                        if qty>avail then problems[#problems+1]=name..': inventory has '..math.floor(avail) end
                        inventory[key]=math.max(0,avail-qty)
                    end
                    total=total+price*qty
                end
            end
        end
    end
    if kind=='sell' and #(DSP.auto.inv or {})==0 then
        problems[#problems+1]='scan inventory before listing'
    end
    if enabled==0 then problems[#problems+1]='no enabled preset positions' end
    return #problems==0,problems,total
end

local function start(kind)
    local ok,issues=T.validate(kind)
    if not ok then DSP.notify(table.concat(issues,'; '));return false end
    return DSP.auto.safe_start(kind)
end
local function control(label,id,width,active,role)
    return M.button(label,'v16_'..id,width,active,role)
end
local function pager(count,per)
    local pages=math.max(1,math.ceil(count/per))
    U.v16_page=math.min(pages,math.max(1,U.v16_page or 1))
    local w=math.max(80,math.min(142,(imgui.GetContentRegionAvail().x-24)/3))
    if control('<','previous',w) then U.v16_page=math.max(1,U.v16_page-1) end
    M.inline()
    if control(U.v16_page..' / '..pages,'counter',w) then U.v16_page=1 end
    M.inline()
    if control('>','next',w) then U.v16_page=math.min(pages,U.v16_page+1) end
    return (U.v16_page-1)*per+1,math.min(U.v16_page*per,count)
end
local function inventory_list(kind)
    if control('Инвентарь','source_inventory',200,U.v16_source=='inventory') then U.v16_source='inventory';U.v16_page=1 end
    M.inline()
    if control('Каталог','source_catalog',160,U.v16_source=='catalog') then U.v16_source='catalog';U.v16_page=1 end
    local entries={}
    if U.v16_source=='inventory' then
        if control('Сканировать','scan',220) then DSP.auto.scan_inventory() end
        M.inline();M.text(tostring(DSP.auto.inv_status or 'Нет данных'))
        entries=DSP.auto.inv or {}
    else
        U.catalog_search=U.catalog_search or imgui.new.char[128]()
        imgui.SetNextItemWidth(math.min(500,imgui.GetContentRegionAvail().x))
        if imgui.InputTextWithHint('##v16_search',DSP.utf8('Поиск предмета'),U.catalog_search,128) then U.v16_page=1 end
        local query=DSP.to_cp(ffi.string(U.catalog_search))
        if query~='' then
            local revision=tostring(DSP.market.state.version or 0)..':'..DSP.lower(query)
            if U.v16_catalog_revision~=revision then
                U.v16_catalog_revision=revision
                U.v16_catalog_rows=DSP.market.find_item(query) or {}
            end
            entries=U.v16_catalog_rows or {}
        end
    end
    M.text('Предметов: '..#entries)
    local from,to=pager(#entries,7)
    for i=from,to do
        local it=entries[i]
        if it then
            imgui.Separator()
            M.thumbnail(it,26);M.inline()
            local name=tostring(it.display or it.name or '?')
            local amount=U.v16_source=='inventory' and (' x'..tostring(it.count or it.qty or 1)) or ''
            M.text(name..amount)
            if control('+','add_'..i,125) then
                local ok,msg
                if U.v16_source=='inventory' then ok,msg=T.add_from_inventory(kind,it)
                else ok,msg=T.add_from_catalog(kind,it) end
                DSP.notify(ok and 'В пресете: '..name or tostring(msg))
            end
        end
    end
    if #entries==0 then M.text('Нет предметов. Откройте инвентарь или используйте поиск.') end
    if control(U.v16_manual and 'Скрыть ручной ввод' or '+ Ввести название вручную','manual_toggle',300) then
        U.v16_manual=not U.v16_manual
    end
    if U.v16_manual then
        U.v16_manual_name=U.v16_manual_name or imgui.new.char[256]()
        imgui.SetNextItemWidth(math.min(450,imgui.GetContentRegionAvail().x))
        imgui.InputTextWithHint('##v16_manual_name',DSP.utf8('Название предмета как в игре'),U.v16_manual_name,256)
        if control('Добавить без цены','manual_add',220) then
            local name=DSP.to_cp(ffi.string(U.v16_manual_name))
            local ok,msg=T.add_from_catalog(kind,{name=name})
            DSP.notify(ok and 'Добавлено. Цена вводится в пресете.' or tostring(msg))
        end
    end
    M.text('Цена вводится в «Мой пресет»; рыночная не подставляется.')
end
local function preset_row(kind,it,i)
    local width=imgui.GetContentRegionAvail().x
    imgui.Separator()
    local v=imgui.new.bool(it.enabled~=false)
    if imgui.Checkbox('##v16_enabled_'..i,v) then
        it.enabled=v[0] and (tonumber(it.price) or 0)>0 or false; M.defer_save()
    end
    M.inline();M.thumbnail(it,24);M.inline()
    M.text(tostring(it.name or '?'))
    local n=math.max(90,math.min(180,math.floor(width*.27)))
    imgui.TextDisabled(DSP.utf8('Цена'))
    imgui.SetNextItemWidth(n)
    if M.compact_number(it,'price','v16_price_'..kind..i,n,0) then
        it.needs_price=(it.price==0) or nil
        it.enabled=it.price>0
    end
    M.inline()
    imgui.TextDisabled(DSP.utf8('Штук'))
    imgui.SetNextItemWidth(n)
    M.compact_number(it,'qty','v16_qty_'..kind..i,n,1)
    if kind=='buy' then
        for _,nqty in ipairs({1,10,100}) do
            if control(tostring(nqty),'qty_'..i..'_'..nqty,76) then
                it.qty=nqty;M.refresh_buffer(it,'qty');M.defer_save()
            end
            M.inline()
        end
        if control('Макс','qty_max_'..i,95) then
            -- Server-specific max cannot be guessed. Use an explicit per-item cap.
            U.v16_max_item=it
            if imgui.OpenPopup then imgui.OpenPopup(DSP.utf8('Макс. количество')..'##v16_max') end
        end
    end
    if control('Удалить','remove_'..i,150) then
        U.v16_remove_pending={kind=kind,index=i,name=it.name}
        if imgui.OpenPopup then imgui.OpenPopup(DSP.utf8('Удалить позицию')..'##v16_remove') end
    end
end
local function dialogs()
    if not imgui.BeginPopupModal then return end
    local max_popup=DSP.utf8('Макс. количество')..'##v16_max'
    if imgui.BeginPopupModal(max_popup,nil,imgui.WindowFlags.AlwaysAutoResize) then
        local it=U.v16_max_item
        if it then
            it._v16_max=it._v16_max or {count=it.max_qty or it.qty or 1}
            M.text('Укажите точный лимит для этого предмета.')
            M.number('Максимум, шт.','max_amount',it._v16_max,'count',1,190)
            if control('Применить','max_apply',160) then
                it.max_qty=it._v16_max.count
                it.qty=it.max_qty
                M.refresh_buffer(it,'qty')
                M.defer_save()
                imgui.CloseCurrentPopup()
            end
        end
        M.inline()
        if control('Отмена','max_cancel',145) then imgui.CloseCurrentPopup() end
        imgui.EndPopup()
    end
    local id=DSP.utf8('Удалить позицию')..'##v16_remove'
    if imgui.BeginPopupModal(id,nil,imgui.WindowFlags.AlwaysAutoResize) then
        M.text('Убрать '..tostring(U.v16_remove_pending and U.v16_remove_pending.name or 'предмет')..' из пресета?')
        if control('Отмена','remove_cancel',140) then imgui.CloseCurrentPopup() end
        M.inline()
        if control('Удалить','remove_confirm',160) then
            local p=U.v16_remove_pending
            if p then DSP.presets.remove(p.kind,p.index) end
            U.v16_remove_pending=nil
            imgui.CloseCurrentPopup()
        end
        imgui.EndPopup()
    end
end
local function library_controls(kind)
    local list=DSP.presets.list(kind)
    local i=DSP.presets.selected(kind)
    local p=current(kind)
    M.text('Пресет: '..tostring(p.name))
    if control('<','preset_prev',70) and not busy() then DSP.presets.select(kind,i>1 and i-1 or #list) end
    M.inline()
    if control('>','preset_next',70) and not busy() then DSP.presets.select(kind,i<#list and i+1 or 1) end
    M.inline()
    if control('Пресеты','preset_manage',160) then U.v16_library=not U.v16_library end
    if not U.v16_library then return end
    U.v16_name=U.v16_name or imgui.new.char[128]()
    imgui.SetNextItemWidth(math.min(320,imgui.GetContentRegionAvail().x))
    imgui.InputTextWithHint('##v16_preset_name',DSP.utf8('Название пресета'),U.v16_name,128)
    local name=DSP.to_cp(ffi.string(U.v16_name))
    if control('Создать','preset_create',146) then DSP.presets.create(kind,name) end
    M.inline()
    if control('Переименовать','preset_rename',200) then DSP.presets.rename(kind,DSP.presets.selected(kind),name) end
    M.inline()
    if control('Экспорт','preset_export',130) then local ok,msg=DSP.presets.export_file(kind);DSP.notify(tostring(msg or ok)) end
    if control('Импорт Market Helper','preset_import_mh',270) then
        local ok,msg=DSP.presets.import_mh();DSP.notify(ok and 'Импортировано' or tostring(msg))
    end
    U.v16_import=U.v16_import or imgui.new.char[384]()
    imgui.SetNextItemWidth(math.min(420,imgui.GetContentRegionAvail().x))
    imgui.InputTextWithHint('##v16_import_path',DSP.utf8('Путь к JSON пресета'),U.v16_import,384)
    if control('Импорт JSON','preset_import_json',195) then
        local ok,msg=DSP.presets.import_file(DSP.to_cp(ffi.string(U.v16_import)),kind)
        DSP.notify(ok and 'Импортировано' or tostring(msg))
    end
    if control('Удалить пресет','preset_remove',220) then
        if imgui.OpenPopup then imgui.OpenPopup(DSP.utf8('Удалить пресет')..'##v16_preset') end
    end
    local popup=DSP.utf8('Удалить пресет')..'##v16_preset'
    if imgui.BeginPopupModal and imgui.BeginPopupModal(popup,nil,imgui.WindowFlags.AlwaysAutoResize) then
        M.text('Безвозвратно удалить выбранный пресет?')
        if control('Отмена','preset_cancel',150) then imgui.CloseCurrentPopup() end
        M.inline()
        if control('Удалить','preset_confirm',160) then
            local ok,err=DSP.presets.delete(kind,DSP.presets.selected(kind))
            if not ok then DSP.notify(err) end
            imgui.CloseCurrentPopup()
        end
        imgui.EndPopup()
    end
end
local function review(kind)
    local popup=DSP.utf8('Проверка выставления')..'##v16_review'
    if imgui.BeginPopupModal and imgui.BeginPopupModal(popup,nil,imgui.WindowFlags.AlwaysAutoResize) then
        M.title('Проверить список')
        local ok,issues,total=T.validate(kind)
        local shown=0
        for _,it in ipairs(current(kind).items or {}) do
            if it.enabled~=false then
                M.text(tostring(it.name)..'  x'..tostring(it.qty)..'  '..DSP.money(it.price))
                shown=shown+1
                if shown>=12 then M.text('Остальные позиции: '..(DSP.presets.active_count(kind)-shown));break end
            end
        end
        M.text('Итого: '..DSP.money(total))
        for _,problem in ipairs(issues) do
            imgui.TextColored(DSP.theme.col('bad',1),DSP.utf8(problem))
        end
        if control('Отмена','review_cancel',160) then imgui.CloseCurrentPopup() end
        M.inline()
        if control('Выставить','review_confirm',200,ok,'primary') then
            if ok then start(kind);imgui.CloseCurrentPopup() else DSP.notify('Исправьте ошибки выше') end
        end
        imgui.EndPopup()
    end
end
local function my_preset(kind)
    library_controls(kind)
    local items=current(kind).items or {}
    M.text('Позиций: '..#items..'  |  Включено: '..DSP.presets.active_count(kind))
    local from,to=pager(#items,5)
    for i=from,to do preset_row(kind,items[i],i) end
    if #items==0 then M.text('Пресет пуст. Добавьте предметы во вкладке «Предметы».') end
end
function U.trade_tab()
    local kind=U.v16_side
    if control('ПРОДАЖА','sell',210,kind=='sell') then U.v16_side='sell';kind='sell';U.v16_page=1 end
    M.inline()
    if control('СКУПКА','buy',200,kind=='buy') then U.v16_side='buy';kind='buy';U.v16_page=1 end
    local tab=U.v16_tab
    if control('Предметы','items',200,tab=='items') then U.v16_tab='items';tab='items';U.v16_page=1 end
    M.inline()
    if control('Мой пресет','preset',200,tab=='preset') then U.v16_tab='preset';tab='preset';U.v16_page=1 end
    imgui.Separator()
    local h=math.max(150,(imgui.GetContentRegionAvail().y or 450)-145)
    M.child('v16_trade_'..tab,0,h,function()
        if tab=='items' then inventory_list(kind) else my_preset(kind) end
    end)
    if busy() then
        M.text(DSP.auto.status_text())
        if control('ОСТАНОВИТЬ','stop',240,true,'primary') then
            if DSP.auto.buy_running then DSP.auto.stop_buy() else DSP.auto.stop_sell() end
        end
    else
        M.text('Выставление: '..(DSP.settings.dry_run and 'тест' or 'реальное'))
        if control('Тест / Реально','dry_toggle',205) then
            DSP.settings.dry_run=not DSP.settings.dry_run;M.defer_save()
        end
        M.inline()
        if control('Быстро выставить','fast',250,true,'primary') then start(kind) end
        M.inline()
        if control('Проверить список','review',245) then
            if imgui.OpenPopup then imgui.OpenPopup(DSP.utf8('Проверка выставления')..'##v16_review') end
        end
    end
    dialogs()
    review(kind)
end
U.palatka_tab=U.trade_tab

end
__mod_37_trade_v16()

local function __mod_38_mobile_market()
-- Market search and item-centric arbitrage; labels are from the player's point of view.
local ffi=require('ffi')
local M=DSP.mobile
local U=DSP.ui
local function add(row,kind)
    local ok,err=DSP.presets.add(row,kind)
    DSP.notify(ok and 'Добавлено в набор' or tostring(err))
end
local function mark(offer,id)
    if M.button('Отметить #'..tostring(offer.shop),'mark_'..id,210) then
        DSP.market.mark_shop(offer.shop)
    end
end
local function offer_list(row,kind)
    local side=kind=='sell' and row.sell or row.buy
    M.title(kind=='sell' and 'ПРОДАЮТ ВАМ' or 'СКУПАЮТ У ВАС')
    if #(side.offers or {})==0 then M.text('Нет предложений') end
    for i,o in ipairs(side.offers or {}) do
        M.text('#'..tostring(o.shop)..'  '..tostring(o.owner or '?')..'    '..DSP.money(o.price)..' / шт.')
        local status=DSP.market.offer_freshness(o.ts)
        M.text('Количество по снимку: '..tostring(o.qty)..' шт.  |  '..tostring(status))
        mark(o,row.key..kind..i)
        imgui.Separator()
    end
end
function U.detail(row)
    M.title('ПРЕДМЕТ')
    M.thumbnail({name=row.display,id=row.id},48)
    M.text(row.display)
    M.text(DSP.market.market_label_for(row) or '')
    if M.button('+ В скупку','detail_add_buy',200) then add(row,'buy') end
    M.inline()
    if M.button('+ В продажу','detail_add_sell',230) then add(row,'sell') end
    offer_list(row,'sell')
    offer_list(row,'buy')
end
function U.finder_tab()
    U.header()
    imgui.SetNextItemWidth(math.min(740,imgui.GetContentRegionAvail().x))
    if imgui.InputTextWithHint('##mobile_search',DSP.utf8('Найти предмет...'),U.finder_search_buf,128) then
        U.finder_query=DSP.to_cp(ffi.string(U.finder_search_buf))
        DSP.screens.set_page('search',1)
    end
    if U.selected then
        if M.button('< К списку','back_search',210) then U.selected=nil end
        local row=DSP.market.state.by_key[U.selected]
        if row then U.detail(row) end
        return
    end
    local matches=DSP.market.find_item(U.finder_query)
    M.text('Предметов: '..#matches)
    local first,last=DSP.screens.pager(#matches,7,'search')
    if #matches==0 then M.text('Нет предложений. Проверьте название или обновите рынок.') end
    for i=first,last do
        local row=matches[i]
        imgui.Separator()
        M.thumbnail({name=row.display,id=row.id},44)
        M.text(row.display)
        M.text('Купить: '..(row.sell.count>0 and DSP.money(row.sell.best) or 'нет')..
            '   |   Продать: '..(row.buy.count>0 and DSP.money(row.buy.best) or 'нет'))
        if M.button('Смотреть лавки','open_item'..i,215) then U.selected=row.key end
        M.inline()
        if M.button('+ В скупку','search_buy'..i,180) then add(row,'buy') end
        M.inline()
        if M.button('+ В продажу','search_sell'..i,210) then add(row,'sell') end
    end
end

local function route_key(group,e)
    -- Same-price slots in the same shop are merged in the market model.
    return tostring(DSP.market.state.sid)..'|'..tostring(group.key)..'|'
        ..tostring(e.sell_offer.shop)..':'..tostring(e.p_buy)..'>'
        ..tostring(e.buy_offer.shop)..':'..tostring(e.p_sell)
end
local function summarize_selection(groups)
    local s={qty=0,cost=0,profit=0,count=0}
    for _,g in ipairs(groups) do
        for _,e in ipairs(g.routes) do
            if U.arb_selected[route_key(g,e)] then
                s.qty=s.qty+(e.tradable_qty or 0)
                s.cost=s.cost+(e.total_cost or 0)
                s.profit=s.profit+(e.net_profit or 0)
                s.count=s.count+1
            end
        end
    end
    return s
end
local function offer_card(g,o,kind,i)
    local shop=tostring(o.shop or '?')
    local age=DSP.market.offer_freshness(o.ts)
    M.text('#'..shop..'  '..tostring(o.owner or '?')..'    '..DSP.money(o.price)..' / шт.')
    if o.snapshot_qty~=nil then
        M.text('Снимок API: '..tostring(o.snapshot_qty)..' шт. | Проверено вами: '..tostring(o.qty)..' шт.')
    else
        M.text('По снимку: '..tostring(o.qty or 0)..' шт. | '..tostring(age))
    end
    mark(o,'group'..g.key..kind..i)
    if kind=='buy' then
        local id='verify_'..tostring(g.key)..'_'..tostring(o.shop)..'_'..i
        if M.button('Проверил в игре: исправить число','verify_open_'..id,365) then
            U.arb_qty_editor_key=id
            U.arb_qty_buf=imgui.new.char[32]()
            local value=tostring(o.qty or 0)
            ffi.copy(U.arb_qty_buf,value,math.min(#value,31))
        end
        if U.arb_qty_editor_key==id and U.arb_qty_buf then
            imgui.SetNextItemWidth(math.min(250,imgui.GetContentRegionAvail().x))
            imgui.InputTextWithHint('##verify_qty_'..id,DSP.utf8('Сколько скупает в игре?'),U.arb_qty_buf,32)
            if M.button('Подтвердить шт.','verify_save_'..id,230) then
                local raw=ffi.string(U.arb_qty_buf)
                local ok,err=DSP.market.confirm_offer_quantity(g.row,'buy',o,raw:match('^%d+$') and tonumber(raw) or -1)
                if ok then U.arb_qty_editor_key=nil; DSP.notify('Количество уточнено. План пересчитан.')
                else DSP.notify(tostring(err)) end
            end
            M.inline()
            if M.button('Отмена','verify_cancel_'..id,150) then U.arb_qty_editor_key=nil end
        end
    end
end
local function route_card(g,e,i)
    local key=route_key(g,e)
    local v=imgui.new.bool(U.arb_selected[key] and true or false)
    if imgui.Checkbox(DSP.utf8('В мой план##route_'..key),v) then
        U.arb_selected[key]=v[0] or nil
    end
    M.text('КУПИТЬ   #'..tostring(e.sell_offer.shop)..'  ->  ПРОДАТЬ   #'..tostring(e.buy_offer.shop))
    M.text('Эта связка: '..tostring(e.tradable_qty)..' шт. | Цена: '..DSP.money(e.p_buy)..' -> '..DSP.money(e.p_sell))
    local gross=(e.tradable_qty or 0)*(e.p_sell or 0)
    M.text('Расход: '..DSP.money(e.total_cost or 0)..' | Выручка после комиссии: '..DSP.money(e.net_revenue or 0))
    M.text('Комиссия: '..DSP.money(gross-(e.net_revenue or 0)))
    imgui.TextColored(DSP.theme.col('good',1),DSP.utf8('Прибыль: +'..DSP.money(e.net_profit)))
    M.text('Продавец: '..tostring(e.qty_seller)..' шт. | Скупщик: '..tostring(e.qty_buyer)..' шт.')
    if (e.tradable_qty or 0)<(e.available_qty or 0) then
        M.text('Меньше максимума: бюджет или объём уже распределён в другие сделки.')
    end
    if M.button('К продавцу #'..tostring(e.sell_offer.shop),'route_sell'..key,220) then
        DSP.market.mark_shop(e.sell_offer.shop)
    end
    M.inline()
    if M.button('К скупщику #'..tostring(e.buy_offer.shop),'route_buy'..key,220) then
        DSP.market.mark_shop(e.buy_offer.shop)
    end
end
local function render_group(g,idx)
    imgui.Separator()
    M.thumbnail({name=g.name,id=g.row.id},46)
    M.title(tostring(idx)..'. '..g.name)
    M.text('ПРОДАЮТ  '..g.supply..' шт. / '..g.seller_count..' предлож.   |   СКУПАЮТ  '..g.demand..' шт. / '..g.buyer_count..' предлож.')
    imgui.TextColored(DSP.theme.col('good',1),
        DSP.utf8('План: '..g.planned..' шт.     Прибыль: +'..DSP.money(g.profit)))
    local expanded=U.arb_expanded[g.key]
    if M.button(expanded and 'Скрыть подробности' or 'Все продавцы, скупщики и маршруты',
        'expand_group'..g.key,440,expanded) then
        U.arb_expanded[g.key]=not expanded
        expanded=not expanded
    end
    if not expanded then return end
    M.text('Источник: снимок рынка. Объёмы в игре могли измениться.')
    M.title('КТО ПРОДАЁТ — '..g.supply..' ШТ. ВСЕГО')
    for i,o in ipairs(g.sellers) do offer_card(g,o,'sell',i); imgui.Separator() end
    M.title('КТО СКУПАЕТ — '..g.demand..' ШТ. ВСЕГО')
    for i,o in ipairs(g.buyers) do offer_card(g,o,'buy',i); imgui.Separator() end
    M.title('РЕАЛЬНЫЙ ПЛАН / '..#g.routes..' СВЯЗОК')
    M.text('Только выгодные пары, без повторного расходования остатков.')
    for i,e in ipairs(g.routes) do route_card(g,e,i); imgui.Separator() end
    if M.button('Выбрать все связки предмета','select_item'..g.key,310) then
        for _,e in ipairs(g.routes) do U.arb_selected[route_key(g,e)]=true end
    end
    M.inline()
    if M.button('Снять выбор','unselect_item'..g.key,175) then
        for _,e in ipairs(g.routes) do U.arb_selected[route_key(g,e)]=nil end
    end
end
function U.arbitrage_tab()
    U.header()
    local f=DSP.settings.arb_filters or {}
    DSP.settings.arb_filters=f
    U.arb_selected=U.arb_selected or {}
    U.arb_expanded=U.arb_expanded or {}
    local st=DSP.market.state
    local signature=tostring(st.sid)..'/'..tostring(st.version)..'/'..tostring(f.budget)..'/'..tostring(f.max_qty)..'/'..tostring(f.min_profit)..'/'..tostring(f.min_roi)
    if signature~=U.arb_selection_signature then
        U.arb_selected={}; U.arb_selection_signature=signature
    end
    M.title('АРБИТРАЖ')
    M.text('По предметам — несколько продавцов объединены в одну карточку.')
    if st.status~='live' then
        imgui.TextColored(DSP.theme.col('warn',1),DSP.utf8(
            'Внимание: источник не подтверждён как LIVE. Проверьте актуальность лавок.'))
    end
    imgui.SetNextItemWidth(math.min(610,imgui.GetContentRegionAvail().x))
    U.arb_search_buf=U.arb_search_buf or imgui.new.char[128]()
    if imgui.InputTextWithHint('##arb_search',DSP.utf8('Поиск предмета...'),U.arb_search_buf,128) then
        DSP.screens.set_page('arbitrage',1)
    end
    if M.button(U.arb_controls and 'Скрыть фильтры' or 'Фильтры',
        'arb_controls',180,U.arb_controls) then U.arb_controls=not U.arb_controls end
    if U.arb_controls then
        local changed=false
        changed=M.number('Бюджет на ВСЕ сделки ($). 0 = без лимита','arb_budget',f,'budget',0,290) or changed
        changed=M.number('Лимит на маршрут (шт.). 0 = без лимита','arb_maxqty',f,'max_qty',0,290) or changed
        changed=M.number('Мин. прибыль за маршрут ($)','arb_profit',f,'min_profit',0,290) or changed
        changed=M.number('Мин. ROI (%)','arb_roi',f,'min_roi',0,290) or changed
        changed=M.number('Макс. возраст снимка (сек.)','arb_age',f,'max_age',0,290) or changed
        changed=M.toggle('Разрешить частичные сделки',f,'allow_partial',true) or changed
        changed=M.toggle('Включать записи без времени',f,'include_unknown',true) or changed
        if changed then DSP.market.invalidate_arbitrage(); DSP.save_settings(); DSP.screens.set_page('arbitrage',1) end
    end
    local groups=DSP.market.arbitrage_grouped()
    local totals=DSP.market.arbitrage_group_totals(groups)
    M.text(tostring(totals.items)..' предметов | '..tostring(totals.routes)..' маршрутов | '..tostring(totals.planned)..' шт. в плане')
    imgui.TextColored(DSP.theme.col('good',1),DSP.utf8('Ожидаемая прибыль: +'..DSP.money(totals.profit)))
    M.text('Важно: «Скупают» = спрос по снимку, «План» = сколько рассчитано для сделок.')
    M.text('Фактическое количество проверяйте в игре: рынок может устареть.')
    local query=DSP.lower(DSP.trim(DSP.to_cp(ffi.string(U.arb_search_buf))))
    local visible={}
    for _,g in ipairs(groups) do
        if query=='' or DSP.lower(g.name):find(query,1,true) then visible[#visible+1]=g end
    end
    if #visible==0 then M.text('Совпадений нет. Обновите рынок или ослабьте фильтры.') end
    local first,last=DSP.screens.pager(#visible,4,'arbitrage')
    for i=first,last do render_group(visible[i],i) end
    imgui.Separator()
    local chosen=summarize_selection(groups)
    M.title('МОЙ ПЛАН  /  '..chosen.count..' СВЯЗОК')
    M.text('Выбрано: '..chosen.qty..' шт. | Нужно денег: '..DSP.money(chosen.cost))
    imgui.TextColored(DSP.theme.col('good',1),DSP.utf8('Прибыль: +'..DSP.money(chosen.profit)))
    M.text('Выбор — чеклист для похода по лавкам; покупки не выполняются автоматически.')
end
U.market_tab=U.arbitrage_tab
function U.lavki_tab()
    U.header()
    local shops=DSP.market.shops_list()
    local first,last=DSP.screens.pager(#shops,7,'lavki')
    if #shops==0 then M.text('Лавки не загружены. Обновите рынок.') end
    for i=first,last do
        local shop=shops[i]
        local number=shop.num or '?'
        imgui.Separator()
        M.title('ЛАВКА #'..tostring(number)..'  |  '..tostring(shop.owner or '?'))
        local fresh=DSP.market.offer_freshness(shop.ts or shop.updated_at)
        M.text('Данные: '..tostring(fresh)..'  |  Продаёт: '..tostring(shop.sell_count or 0)..'  |  Скупает: '..tostring(shop.buy_count or 0))
        if M.button('Отметить на карте','shop_mark'..i,225) then DSP.market.mark_shop(number) end
        M.inline()
        if M.button(U.lavki_expanded[number] and 'Свернуть' or 'Товары','expand_shop'..i,195) then
            U.lavki_expanded[number]=not U.lavki_expanded[number]
        end
        if (shop.buy_count or 0)>0 and M.button('Копировать скупку +1$','copy_shop'..i,320) then
            local n,err=DSP.market.copy_shop_skupka(number,nil,1)
            DSP.notify(n and ('Скопировано позиций: '..n) or tostring(err))
        end
        if U.lavki_expanded[number] then
            for _,side in ipairs({'sell','buy'}) do
                M.title(side=='sell' and 'Продаёт вам:' or 'Скупает у вас:')
                for _,entry in ipairs(shop[side..'_offers'] or {}) do
                    local it=entry.offer
                    M.text(entry.row.display..'  |  '..DSP.money(it.price or 0)..' за шт. | '..tostring(it.qty or 0)..' шт.')
                end
            end
        end
    end
end

end
__mod_38_mobile_market()

local function __mod_38_arbitrage_v16()
-- Compact item-centric arbitrage. No manual alteration of API quantities.
local M,U=DSP.mobile,DSP.ui
local function b(label,id,w,active) return M.button(label,'arb16_'..id,w,active) end
local function title(g) return tostring(g.name or '?') end
local function offer_id(o) return tostring(o.shop)..':'..tostring(o.price)..':'..tostring(o.owner) end
local function route_id(g,r) return tostring(g.key)..'|'..offer_id(r.sell_offer)..'>'..offer_id(r.buy_offer) end
DSP.arb_v16=DSP.arb_v16 or {}
local function safe_integer(value)
    local n=tonumber(value)
    if not n or n~=n or n<0 or n>9007199254740991 then return nil end
    return math.floor(n)
end
function DSP.arb_v16.manual_pair(seller,buyer,budget,tax_bp)
    if not seller or not buyer then return nil end
    if seller.shop~=nil and buyer.shop~=nil and tostring(seller.shop)==tostring(buyer.shop) then return nil end
    if (seller.ench or 0)~=(buyer.ench or 0) then return nil end
    local p1,p2=safe_integer(seller.price),safe_integer(buyer.price)
    local q1,q2=safe_integer(seller.qty),safe_integer(buyer.qty)
    if not p1 or not p2 or p1<=0 or p2<=0 or not q1 or not q2 then return nil end
    local count=math.min(q1,q2,math.floor(9007199254740991/math.max(p1,p2)))
    budget=safe_integer(budget) or 0
    if budget>0 then count=math.min(count,math.floor(budget/p1)) end
    local cost=p1*count
    local tax=tonumber(tax_bp) or 200
    if tax~=tax or tax==math.huge or tax==-math.huge then tax=200 end
    local factor=10000-math.max(0,math.min(10000,math.floor(tax)))
    local gross=p2*count
    local revenue=math.floor(gross/10000)*factor+math.floor((gross%10000)*factor/10000)
    return {qty=count,cost=cost,revenue=revenue,profit=revenue-cost}
end
local function selected_plan(g)
    local plan={qty=0,cost=0,revenue=0,profit=0,routes={}}
    for _,r in ipairs(g.routes or {}) do
        if U.v16_arb_selected and U.v16_arb_selected[route_id(g,r)] then
            plan.qty=plan.qty+(tonumber(r.tradable_qty) or 0)
            plan.cost=plan.cost+(tonumber(r.total_cost) or 0)
            plan.revenue=plan.revenue+(tonumber(r.net_revenue) or 0)
            plan.profit=plan.profit+(tonumber(r.net_profit) or 0)
            plan.routes[#plan.routes+1]=r
        end
    end
    if U.v16_arb_use_extra and #plan.routes>0 then
        plan.profit=plan.profit-(tonumber(U.v16_arb_expenses and U.v16_arb_expenses.extra) or 0)
    end
    return plan
end
local function auto_select(g)
    U.v16_arb_selected=U.v16_arb_selected or {}
    for _,r in ipairs(g.routes or {}) do
        U.v16_arb_selected[route_id(g,r)]=true
    end
end
local function render_offer(g,offer,side,index)
    local v=side=='sell' and U.v16_arb_seller or U.v16_arb_buyer
    local id=offer_id(offer)
    local label='#'..tostring(offer.shop)..'  '..tostring(offer.owner or '?')..'  '
        ..DSP.money(offer.price)..' x'..tostring(offer.qty or 0)
    if b(label,'offer_'..side..index,-1,id==v) then
        if side=='sell' then U.v16_arb_seller=v==id and nil or id
        else U.v16_arb_buyer=v==id and nil or id end
    end
    if b('Метка','pin_'..side..index,115) then DSP.market.mark_shop(offer.shop) end
    M.inline();M.text('API: '..DSP.market.offer_freshness(offer.ts))
end
local function detail(g)
    if b('< К списку','back',205) then U.v16_arb_detail=nil;return end
    M.inline();M.title(title(g))
    M.text('Продают '..g.supply..' шт. / Скупают '..g.demand..' шт.')
    M.text('План '..g.planned..' шт.  |  +'..DSP.money(g.profit))
    if b('Продают','sellers',165,U.v16_arb_tab~='buy') then U.v16_arb_tab='sell' end
    M.inline()
    if b('Скупают','buyers',165,U.v16_arb_tab=='buy') then U.v16_arb_tab='buy' end
    local side=U.v16_arb_tab=='buy' and 'buy' or 'sell'
    local offers=(side=='sell' and g.sellers or g.buyers) or {}
    local pages=math.max(1,math.ceil(#offers/5))
    U.v16_arb_offer_page=math.min(pages,math.max(1,U.v16_arb_offer_page or 1))
    for i=(U.v16_arb_offer_page-1)*5+1,math.min(#offers,U.v16_arb_offer_page*5) do
        render_offer(g,offers[i],side,i)
    end
    if b('<','offer_prev',100) then U.v16_arb_offer_page=math.max(1,U.v16_arb_offer_page-1) end
    M.inline()
    M.text(U.v16_arb_offer_page..' / '..pages)
    M.inline()
    if b('>','offer_next',100) then U.v16_arb_offer_page=math.min(pages,U.v16_arb_offer_page+1) end
    -- Exact selected pair or a selection of allocated routes. Existing allocator
    -- guarantees routes use disjoint stock and demand; no new duplicate consumption.
    if U.v16_arb_seller and U.v16_arb_buyer then
        local seller,buyer
        for _,o in ipairs(g.sellers or {}) do
            if offer_id(o)==U.v16_arb_seller then seller=o;break end
        end
        for _,o in ipairs(g.buyers or {}) do
            if offer_id(o)==U.v16_arb_buyer then buyer=o;break end
        end
        local f=DSP.settings.arb_filters or {}
        local estimate=DSP.arb_v16.manual_pair(seller,buyer,f.budget,DSP.settings.tax_bp)
        if estimate then
            M.title('Выбранная пара: '..estimate.qty..' шт.')
            M.text('Затраты: '..DSP.money(estimate.cost)..' | Выручка: '..DSP.money(estimate.revenue))
            M.text('Прибыль: '..DSP.money(estimate.profit)..' (отдельный сценарий)')
            M.text('Не прибавляется к общему плану, чтобы не учитывать один лот дважды.')
        end
    end
    if b('Лучший план','auto',198) then auto_select(g);U.v16_arb_seller=nil;U.v16_arb_buyer=nil end
    M.inline()
    if b('Очистить','clear',155) then
        U.v16_arb_selected={};U.v16_arb_seller=nil;U.v16_arb_buyer=nil
    end
    M.title('Подходящие сделки')
    local displayed=0
    for i,r in ipairs(g.routes or {}) do
        local seller=offer_id(r.sell_offer)
        local buyer=offer_id(r.buy_offer)
        if (not U.v16_arb_seller or seller==U.v16_arb_seller)
            and (not U.v16_arb_buyer or buyer==U.v16_arb_buyer) then
            local key=route_id(g,r)
            local marked=U.v16_arb_selected and U.v16_arb_selected[key]
            local label=(marked and '[x] ' or '[ ] ')..'#'..r.sell_offer.shop..' -> #'..r.buy_offer.shop
                ..' | '..r.tradable_qty..' шт. | +'..DSP.money(r.net_profit)
            if b(label,'route_'..i,-1,marked) then
                U.v16_arb_selected=U.v16_arb_selected or {}
                U.v16_arb_selected[key]=not marked or nil
            end
            displayed=displayed+1
            if displayed>=6 then break end
        end
    end
    if displayed==0 then M.text('Подходящей связки нет. Уберите фильтр продавца/скупщика.') end
    U.v16_arb_expenses=U.v16_arb_expenses or {extra=0}
    if b(U.v16_arb_use_extra and 'Доп. расходы: да' or 'Доп. расходы: нет','extra',250) then
        U.v16_arb_use_extra=not U.v16_arb_use_extra
    end
    if U.v16_arb_use_extra then M.number('Расход на план ($)','additional_expense',U.v16_arb_expenses,'extra',0,180) end
    local plan=selected_plan(g)
    M.text('Купить: '..plan.qty..' шт.  |  Расход: '..DSP.money(plan.cost))
    M.text('Выручка после комиссии: '..DSP.money(plan.revenue))
    imgui.TextColored(DSP.theme.col(plan.profit>=0 and 'good' or 'bad',1),
        DSP.utf8('Чистая прибыль: '..DSP.money(plan.profit)))
    if b(U.v16_arb_route and 'Скрыть маршрут' or 'Маршрут','route_view',210) then
        U.v16_arb_route=not U.v16_arb_route
    end
    if U.v16_arb_route then
        for i,r in ipairs(plan.routes) do
            M.text(i..'. Купить '..r.tradable_qty..' шт. в #'..r.sell_offer.shop)
            if b('Метка продавца','sell_route_'..i,200) then DSP.market.mark_shop(r.sell_offer.shop) end
            M.text('   Продать '..r.tradable_qty..' шт. в #'..r.buy_offer.shop)
            if b('Метка скупщика','buy_route_'..i,200) then DSP.market.mark_shop(r.buy_offer.shop) end
        end
    end
end
function U.arbitrage_tab()
    local state=DSP.market.state or {}
    U.v16_arb_selected=U.v16_arb_selected or {}
    local sig=tostring(state.sid)..':'..tostring(state.version or 0)
    if U.v16_arb_signature~=sig then
        U.v16_arb_selected={};U.v16_arb_detail=nil;U.v16_arb_signature=sig
    end
    if U.v16_arb_detail then
        for _,g in ipairs(DSP.market.arbitrage_grouped()) do
            if g.key==U.v16_arb_detail then detail(g);return end
        end
        U.v16_arb_detail=nil
    end
    M.text('Рынок: '..DSP.market.freshness()..' | '..tostring(state.status or '?'))
    if b('Обновить','refresh',170) then DSP.market.pull(state.sid) end
    M.inline()
    if b(U.v16_arb_filters and 'Скрыть фильтры' or 'Фильтры','filters',170) then
        U.v16_arb_filters=not U.v16_arb_filters
    end
    if U.v16_arb_filters then
        local f=DSP.settings.arb_filters or {};DSP.settings.arb_filters=f
        if M.number('Бюджет','arb_budget',f,'budget',0,190) then DSP.market.invalidate_arbitrage() end
        if M.number('Минимум прибыли','arb_profit',f,'min_profit',0,190) then DSP.market.invalidate_arbitrage() end
    end
    local groups=DSP.market.arbitrage_grouped()
    U.v16_arb_search=U.v16_arb_search or imgui.new.char[128]()
    imgui.SetNextItemWidth(math.min(500,imgui.GetContentRegionAvail().x))
    imgui.InputTextWithHint('##arb16_search',DSP.utf8('Поиск предмета'),U.v16_arb_search,128)
    local query=DSP.lower(DSP.trim(DSP.to_cp(require('ffi').string(U.v16_arb_search))))
    local shown={}
    for _,g in ipairs(groups) do
        if query=='' or DSP.lower(g.name):find(query,1,true) then shown[#shown+1]=g end
    end
    M.text('Предметов: '..#shown)
    local from,to=DSP.screens.pager(#shown,7,'arbitrage')
    for i=from,to do
        local g=shown[i]
        M.thumbnail({name=g.name,id=g.row and g.row.id},26);M.inline()
        local label=g.name..'  '..g.planned..' шт.  +'..DSP.money(g.profit)
        if b(label,'item_'..i,-1) then
            U.v16_arb_detail=g.key;U.v16_arb_tab='sell';U.v16_arb_offer_page=1
            U.v16_arb_seller=nil;U.v16_arb_buyer=nil
            U.v16_arb_selected={}
        end
    end
    if #shown==0 then M.text('Связок нет — проверьте фильтры и свежесть данных.') end
end

end
__mod_38_arbitrage_v16()

local function __mod_39_mobile_history()
local ffi=require('ffi')
local M=DSP.mobile
local U=DSP.ui
local function date(ts) return os.date('%d.%m.%Y %H:%M:%S',tonumber(ts) or 0) end
M.history_revision={trades=0,stalls=0}
local history_cache={}
function M.history_rows(kind)
    local source=DSP.settings[kind] or {}
    local revision=M.history_revision[kind]
    local cached=history_cache[kind]
    if cached and cached.source==source and cached.revision==revision then return cached.rows end
    local rows={}
    for _,entry in pairs(source) do rows[#rows+1]=entry end
    table.sort(rows,function(a,b) return (a.ts or 0)>(b.ts or 0) end)
    history_cache[kind]={source=source,revision=revision,rows=rows}
    return rows
end
-- Invalidate only when events mutate logs; unchanged frames reuse sorted rows.
for name,kinds in pairs({record_trade={'trades'},stall_dropped={'stalls'},clear_trades={'trades','stalls'},load={'trades','stalls'}}) do
    local original=DSP.logs[name]
    if original then
        DSP.logs[name]=function(...)
            for _,kind in ipairs(kinds) do M.history_revision[kind]=M.history_revision[kind]+1 end
            return original(...)
        end
    end
end
function U.crate_log()
    if not DSP.rewards then M.text('История наград недоступна'); return end
    U.reward_filter=U.reward_filter or {search=''}
    U.reward_search=U.reward_search or imgui.new.char[256]()
    local filter=U.reward_filter
    imgui.SetNextItemWidth(math.min(700,imgui.GetContentRegionAvail().x))
    if imgui.InputTextWithHint('##reward_search',DSP.utf8('Найти предмет или источник'),U.reward_search,256) then
        filter.search=DSP.to_cp(ffi.string(U.reward_search)); DSP.screens.set_page('rewards',1)
    end
    U.reward_source=U.reward_source or imgui.new.char[256]()
    imgui.SetNextItemWidth(math.min(700,imgui.GetContentRegionAvail().x))
    if imgui.InputTextWithHint('##reward_source',DSP.utf8('Источник содержит (например: Vice City)'),U.reward_source,256) then
        filter.source_contains=DSP.to_cp(ffi.string(U.reward_source)); DSP.screens.set_page('rewards',1)
    end
    for _,period in ipairs({{0,'Все даты'},{86400,'24 часа'},{604800,'7 дней'}}) do
        if M.button(period[2],'reward_period'..period[1],260,(U.reward_period or 0)==period[1]) then
            U.reward_period=period[1]
            filter.from_ts=period[1]>0 and os.time()-period[1] or nil
            DSP.screens.set_page('rewards',1)
        end
        if period[1]~=604800 then M.inline() end
    end
    for _,pair in ipairs({{'all','Все'},{'item','Предметы'},{'cash','Деньги'},{'opening','Открытия'}}) do
        if M.button(pair[2],'reward_kind'..pair[1],220,(filter.kind or 'all')==pair[1]) then
            filter.kind=pair[1]~='all' and pair[1] or nil; DSP.screens.set_page('rewards',1)
        end
        if pair[1]~='opening' then M.inline() end
    end
    local summary=DSP.rewards.summary(filter)
    M.text('Открытий: '..tostring(summary.openings)..' | Предметов: '..tostring(summary.items)
        ..' | Деньги: '..DSP.money(summary.cash or 0))
    M.text('Рыночная оценка: '..DSP.money(summary.estimated_value or 0)
        ..' | Без цены: '..tostring(summary.unknown_items)..' записей')
    filter.page=DSP.screens.page_of('rewards'); filter.page_size=10
    local result=DSP.rewards.query(filter)
    local first=DSP.screens.pager(result.total or 0,10,'rewards')
    local current=math.floor((first-1)/10)+1
    if current~=filter.page then filter.page=current; result=DSP.rewards.query(filter) end
    if result.error then M.text('Ошибка истории: '..tostring(result.error)) end
    if (result.corrupt_lines or 0)>0 then M.text('Повреждённых строк: '..result.corrupt_lines) end
    if (result.total or 0)==0 then M.text('Наград пока нет. История пополняется из сообщений игрового чата.') end
    for _,e in ipairs(result.entries or {}) do
        M.title(date(e.ts)..' / '..tostring(e.source or 'Источник неизвестен'))
        if e.kind=='opening' then M.text('Открыт тайник / ларец')
        elseif e.kind=='cash' then M.text('Получено денег: '..DSP.money(e.cash or 0))
        else
            M.text(tostring(e.item_name or '?')..' x'..tostring(e.qty or 1)..((e.ench or 0)>0 and (' (+'..e.ench..')') or ''))
            if e.price_known and not (DSP.rewards and DSP.rewards.is_temporary and DSP.rewards.is_temporary(e)) then
                M.text('Оценка: '..DSP.money(e.estimated_value or 0)..' | За шт.: '..DSP.money(e.unit_price or 0))
                M.text('База: '..tostring(e.price_source or '?')..' | Метка цены: '..(e.price_ts and date(e.price_ts) or 'время неизвестно'))
            else M.text('Цена неизвестна. Оценка не включена в сумму.') end
        end
        if e.association=='inferred' then M.text('Источник определён по соседнему сообщению чата') end
        if e.association=='unknown' then M.text('Источник награды не определён') end
        M.text(e.raw or '')
        imgui.Separator()
    end
end
function U.log_tab()
    M.title('ИСТОРИЯ')
    for _,v in ipairs({{'crates','Награды / тайники'},{'trades','Сделки'},{'chat','Чат'}}) do
        if M.button(v[2],'history_'..v[1],330,U.tab_detail==v[1]) then U.tab_detail=v[1] end
        if v[1]~='chat' then M.inline() end
    end
    imgui.Separator()
    if U.tab_detail=='crates' then U.crate_log()
    elseif U.tab_detail=='chat' then
        local chat=DSP.settings.chat_logs or {}
        local first,last=DSP.screens.pager(#chat,12,'chat_history')
        for i=first,last do
            local e=chat[#chat-i+1]
            M.text(date(e.ts)..' | '..tostring(e.text or '')); imgui.Separator()
        end
    else
        local trades=M.history_rows('trades')
        M.title('СДЕЛКИ / '..#trades)
        local first,last=DSP.screens.pager(#trades,8,'trade_history')
        for i=first,last do
            local e=trades[i]
            M.title(date(e.ts)..' | '..tostring(e.partner or '?'))
            M.text(e.item_summary or '')
            M.text('Получено '..DSP.money(e.total_get or 0)..' | Отдано '..DSP.money(e.total_give or 0)
                ..' | Прибыль '..DSP.money(e.profit or 0)); imgui.Separator()
        end
        local stalls=M.history_rows('stalls')
        M.title('ЛАВКИ / '..#stalls)
        first,last=DSP.screens.pager(#stalls,8,'stall_history')
        for i=first,last do
            local e=stalls[i]
            M.text(date(e.ts)..' | Лавка #'..tostring(e.shop_num or '?')..' '..tostring(e.owner or '')..' '..tostring(e.action or ''))
        end
    end
end
-- v1.4 unified event timeline, with independent event/payday/income filters.
function U.log_tab()
    local C=DSP.craglog
    M.title('ЖУРНАЛ СОБЫТИЙ')
    M.text('Сделки, деньги, открытия и PayDay в одном месте.')
    U.journal_filter=U.journal_filter or 'all'
    local tabs={{'all','Все'},{'loot','Тайники'},{'payday','PayDay'},
                {'sales','Продажи'},{'buys','Скупка'},{'income','Доходы'}}
    for i,pair in ipairs(tabs) do
        if M.button(pair[2],'journal_'..pair[1],190,U.journal_filter==pair[1]) then
            U.journal_filter=pair[1]
            DSP.screens.set_page('journal_events',1)
        end
        if i%3~=0 then M.inline() end
    end
    imgui.Separator()
    if not C then M.text('Журнал ещё не загружен'); return end
    local all=C.filtered('all')
    local since=os.time()-86400
    local sales,buys,paydays,crates,income,profit=0,0,0,0,0,0
    for _,e in ipairs(all) do
        if (tonumber(e.ts) or 0)>=since then
            if e.type=='payday' then paydays=paydays+1
            elseif e.type=='income' then income=income+(tonumber(e.amount) or 0)
            elseif e.kind=='cash' then income=income+(tonumber(e.cash) or 0)
            elseif e.kind=='opening' then crates=crates+1
            elseif e.type=='market' then
                if e.direction=='sell' then sales=sales+1 else buys=buys+1 end
            elseif e.type=='trade' then
                profit=profit+(tonumber(e.profit) or 0)
                if (tonumber(e.money_get) or 0)>0 then sales=sales+1 end
                if (tonumber(e.money_give) or 0)>0 then buys=buys+1 end
            end
        end
    end
    M.text('За 24 ч | Продажи: '..sales..' | Скупки: '..buys..' | Тайники: '..crates..' | PayDay: '..paydays)
    M.text('Торговый итог (оценка): '..DSP.money(profit)..' | Полученные деньги: '..DSP.money(income))
    M.text('Торговый итог может включать рыночную стоимость вещей, а не наличные.')
    imgui.Separator()
    local events=C.filtered(U.journal_filter)
    table.sort(events,function(a,b) return (tonumber(a.ts) or 0)>(tonumber(b.ts) or 0) end)
    local first,last=DSP.screens.pager(#events,7,'journal_events')
    if #events==0 then M.text('Пока нет записей этого типа. Новые события появятся после сообщений сервера.') end
    for i=first,last do
        local e=events[i]
        if e then
            local kind=e.kind or e.type
            local heading=e.type=='payday' and 'PAYDAY' or e.type=='income' and 'ДОХОД'
                or kind=='opening' and 'ТАЙНИК' or kind=='item' and 'ПРЕДМЕТ'
                or kind=='cash' and 'ДЕНЬГИ' or e.type=='market' and (e.direction=='sell' and 'ПРОДАЖА' or 'СКУПКА') or 'СДЕЛКА'
            M.title(date(e.ts)..'    '..heading)
            M.text(C.describe(e))
            if e.source and e.source~='' then M.text('Источник: '..tostring(e.source)) end
            imgui.Separator()
        end
    end
    if M.button('Подробно: тайники и награды','journal_details',430) then
        U.journal_details=not U.journal_details
    end
    if U.journal_details then U.crate_log() end
    if M.button(U.legacy_trade_open and 'Скрыть старые сделки' or 'История старых сделок',
            'journal_legacy',340,U.legacy_trade_open) then
        U.legacy_trade_open=not U.legacy_trade_open
    end
    if M.button(U.journal_chat_open and 'Скрыть сообщения чата' or 'Сообщения чата (диагностика)',
            'journal_raw_chat',400,U.journal_chat_open) then
        U.journal_chat_open=not U.journal_chat_open
    end
    if U.journal_chat_open then
        local chat=DSP.settings.chat_logs or {}
        local first,last=DSP.screens.pager(#chat,12,'chat_history')
        for i=first,last do
            local e=chat[#chat-i+1]
            if e then M.text(date(e.ts)..' | '..tostring(e.text or '')) end
        end
    end
    if U.legacy_trade_open then
        local trades=M.history_rows('trades')
        M.title('СТАРЫЕ СДЕЛКИ / '..#trades)
        local left,right=DSP.screens.pager(#trades,7,'legacy_trade_history')
        for i=left,right do
            local trade=trades[i]
            M.text(date(trade.ts)..' | '..tostring(trade.partner or '?'))
            M.text(trade.item_summary or '')
            M.text('Получено: '..DSP.money(trade.total_get or 0)..'  |  Отдано: '..DSP.money(trade.total_give or 0))
            imgui.Separator()
        end
    end
    if C.last_error then M.text('Ошибка файла журнала: '..tostring(C.last_error)) end
end
local function save_notes()
    local f,err=io.open(DSP.notes_path,'w')
    if not f then DSP.notify('Не удалось сохранить заметки: '..tostring(err)); return false end
    local ok,write_err=f:write(ffi.string(U.notes_buf))
    local closed,close_err=f:close()
    if not ok or not closed then DSP.notify('Ошибка сохранения заметок: '..tostring(write_err or close_err)); return false end
    U._notes_dirty=false
    return true
end
M.save_notes=save_notes
function U.notes_tab()
    M.title('ЗАМЕТКИ')
    M.text(U._notes_dirty and 'Есть несохранённые изменения' or 'Сохранено')
    if M.button('Сохранить заметку','save_notes',340) then save_notes() end
    M.text('Ваш список закупок, планы и цены. Автосохранение после паузы во вводе.')
    local avail=imgui.GetContentRegionAvail()
    if imgui.InputTextMultiline('##mobile_notes',U.notes_buf,8192,imgui.ImVec2(avail.x,math.max(160,avail.y-20)),0) then
        U._notes_dirty=true; U._notes_last_edit=os.clock()
    end
end
-- Save before closing, including when an Android keyboard temporarily changes the viewport.
local set_open=U.set_open
function U.set_open(value)
    if not value and U._notes_dirty and U.notes_buf then M.save_notes() end
    set_open(value)
end
function U.settings_tab()
    M.title('НАСТРОЙКИ')
    U.settings_section=U.settings_section or 'appearance'
    for _,v in ipairs({{'appearance','Вид'},{'trade','Торговля'},{'data','Данные'},{'tools','Инструменты'}}) do
        if M.button(v[2],'settings_'..v[1],270,U.settings_section==v[1]) then U.settings_section=v[1] end
        if v[1]~='tools' then M.inline() end
    end
    imgui.Separator()
    local section=U.settings_section
    if section=='appearance' then
