local function __mod_40_mobile_notes()
-- Separate notes remain searchable and retain optional market references.
local ffi=require('ffi')
local M=DSP.mobile
local U=DSP.ui
DSP.notes={}
local N=DSP.notes
local function save()
    if not DSP.save_settings() then
        U._notes_dirty=true
        DSP.notify('Не удалось сохранить заметки. Повторите сохранение.')
        return false
    end
    U._notes_dirty=false
    if DSP.notes then DSP.notes.revision=(DSP.notes.revision or 0)+1 end
    return true
end
function N.all()
    if type(DSP.settings.notes)~='table' then
        DSP.settings.notes={}
        local legacy=U.notes_buf and DSP.to_cp(ffi.string(U.notes_buf)) or ''
        if legacy~='' then
            DSP.settings.notes[1]={id='legacy',title='Мои заметки',text=legacy,pinned=false,updated_at=os.time()}
        end
        save()
    end
    return DSP.settings.notes
end
function N.filtered(query)
    local rows={}
    local q=DSP.lower(DSP.trim(query or ''))
    for _,note in ipairs(N.all()) do
        local text=table.concat({note.title or '',note.text or '',note.item or '',note.shop or ''},' ')
        if q=='' or DSP.lower(text):find(q,1,true) then rows[#rows+1]=note end
    end
    table.sort(rows,function(a,b)
        if (a.pinned and true or false)~=(b.pinned and true or false) then return a.pinned and true or false end
        if (a.updated_at or 0)~=(b.updated_at or 0) then return (a.updated_at or 0)>(b.updated_at or 0) end
        return tostring(a.id)<tostring(b.id)
    end)
    return rows
end
function N.create(title)
    local notes=N.all()
    local note={id=tostring(os.time())..'_'..tostring(#notes+1),title=title or 'Новая заметка',text='',updated_at=os.time()}
    notes[#notes+1]=note
    if not save() then table.remove(notes,#notes);return nil end
    return note
end
local function buffer(value,size)
    local b=imgui.new.char[size]()
    local text=DSP.to_u8(value or '')
    ffi.copy(b,text,math.min(#text,size-1))
    return b
end
function N.open(note)
    if U._notes_dirty and not M.save_notes() then return false end
    U.note_current=note
    U.note_title=buffer(note.title,256)
    U.note_item=buffer(note.item,256)
    U.note_shop=buffer(note.shop,64)
    U.notes_buf=buffer(note.text,8192)
    U.note_delete=false
    U.note_delete_pending=false
    return true
end
function M.save_notes()
    local note=U.note_current
    if note then
        note.title=DSP.to_cp(ffi.string(U.note_title))
        note.text=DSP.to_cp(ffi.string(U.notes_buf))
        note.item=DSP.to_cp(ffi.string(U.note_item))
        note.shop=DSP.to_cp(ffi.string(U.note_shop))
        note.updated_at=os.time()
    end
    return save()
end
local function changed()
    U._notes_dirty=true; U._notes_last_edit=os.time()
end
function U.notes_tab()
    M.title('ЗАМЕТКИ')
    N.all()
    U.note_search=U.note_search or buffer('',256)
    if U.note_current then
        local note=U.note_current
        if M.button('< Все заметки','notes_back',300) then
            if M.save_notes() then U.note_current=nil end
        end
        M.inline()
        if M.button('Сохранить','notes_save',300) then M.save_notes() end
        M.text(U._notes_dirty and 'Есть несохранённые изменения' or 'Сохранено')
        M.text('Название')
        imgui.SetNextItemWidth(math.min(900,imgui.GetContentRegionAvail().x))
        if imgui.InputText('##note_title',U.note_title,256) then changed() end
        if M.toggle('Закрепить в начале списка',note,'pinned',false) then changed() end
        M.text('Предмет (необязательно)')
        imgui.SetNextItemWidth(600)
        if imgui.InputText('##note_item',U.note_item,256) then changed() end
        M.text('Номер лавки (необязательно)')
        imgui.SetNextItemWidth(300)
        if imgui.InputText('##note_shop',U.note_shop,64) then changed() end
        if note.shop and note.shop:match('^%d+$') and M.button('Найти лавку #'..note.shop,'note_mark',380) then DSP.market.mark_shop(note.shop) end
        M.text('Текст заметки')
        if imgui.InputTextMultiline('##mobile_note_text',U.notes_buf,8192,imgui.ImVec2(-1,280),0) then changed() end
        local popup_id=DSP.utf8('Удалить заметку?')..'##note_delete_modal'
        if M.button('Удалить заметку','note_delete',350) then
            U.note_delete_pending=true
            if imgui.OpenPopup then imgui.OpenPopup(popup_id) end
        end
        -- Proper modal, not a red confirmation block hidden below the form.
        if imgui.GetIO and imgui.SetNextWindowPos and imgui.Cond and imgui.ImVec2 then
            local io=imgui.GetIO()
            if io and io.DisplaySize then
                imgui.SetNextWindowPos(imgui.ImVec2(io.DisplaySize.x*.5,io.DisplaySize.y*.5),
                    imgui.Cond.Appearing,imgui.ImVec2(.5,.5))
            end
        end
        if imgui.BeginPopupModal and imgui.BeginPopupModal(popup_id,nil,
            imgui.WindowFlags and imgui.WindowFlags.AlwaysAutoResize or 0) then
            M.title('Удалить заметку?')
            M.text('"'..tostring(note.title or '')..'" будет удалена безвозвратно.')
            if M.button('Отмена','note_cancel_modal',190) then
                U.note_delete_pending=false
                if imgui.CloseCurrentPopup then imgui.CloseCurrentPopup() end
            end
            M.inline()
            if M.button('Да, удалить','note_delete_confirm',220) then
                local old_index
                for i,v in ipairs(N.all()) do if v==note then old_index=i;table.remove(DSP.settings.notes,i);break end end
                if save() then
                    U.note_current=nil;U.note_delete_pending=false
                elseif old_index then
                    table.insert(DSP.settings.notes,old_index,note)
                end
                if imgui.CloseCurrentPopup then imgui.CloseCurrentPopup() end
            end
            imgui.EndPopup()
        end
        return
    end
    imgui.SetNextItemWidth(math.min(850,imgui.GetContentRegionAvail().x))
    imgui.InputTextWithHint('##notes_search',DSP.utf8('Поиск по названию, тексту, предмету и лавке'),U.note_search,256)
    if M.button('+ Новая заметка','notes_create',400) then N.open(N.create()) end
    local notes=N.filtered(DSP.to_cp(ffi.string(U.note_search)))
    M.text('Заметок: '..#notes)
    for i,note in ipairs(notes) do
        M.text((note.pinned and '[*] ' or '')..tostring(note.title))
        if note.item and note.item~='' then M.text('Предмет: '..note.item) end
        if note.shop and note.shop~='' then M.text('Лавка #'..note.shop) end
        if M.button('Открыть','note_open'..i,300) then N.open(note) end
        imgui.Separator()
    end
end

end
__mod_40_mobile_notes()

local function __mod_39_trade_runtime()
-- Cooperative waits use elapsed scheduler time, not CPU time (os.clock).
DSP.trade_runtime = {}
local R = DSP.trade_runtime
local owners = setmetatable({}, {__mode = 'k'})
R.generation = 0
R.state = R.state or {kind='idle',phase='idle',detail='',at=0,generation=0}
function R.transition(kind,phase,detail)
    R.state={kind=tostring(kind or R.state.kind or 'idle'),phase=tostring(phase or 'idle'),
        detail=tostring(detail or ''),at=os.time(),generation=R.generation}
    if DSP.auto then DSP.auto.trade_state=R.state end
    if DSP.flog then DSP.flog('TRADE STATE '..R.state.kind..'/'..R.state.phase..(R.state.detail~='' and (' '..R.state.detail) or '')) end
    return R.state
end
function R.snapshot() return R.state end
local main = {}
local function owner() return coroutine.running() or main end
function R.pause(ms)
    local generation = owners[owner()]
    wait(ms)
    if generation and generation ~= R.generation then error('trade_cancelled', 0) end
end
function R.cancel() R.generation = R.generation + 1;R.transition(R.state.kind,'cancelled','user/runtime cancel') end
function R.spawn(kind, fn)
    R.generation = R.generation + 1
    local generation = R.generation
    DSP.auto.progress = {kind = kind, done = 0, total = 0, failed = 0, dry = 0}
    R.transition(kind,'start','generation='..tostring(generation))
    lua_thread.create(function()
        if generation ~= R.generation then return end
        owners[owner()] = generation
        local ok, err = pcall(fn)
        owners[owner()] = nil
        if generation == R.generation then
            DSP.auto[kind .. '_running'] = false
            if not ok then
                R.transition(kind,'failed',tostring(err))
                DSP.auto.progress.failed = DSP.auto.progress.failed + 1
                DSP.auto.status = 'ошибка: ' .. tostring(err)
                if sampIsDialogActive() then
                    local closed, close_err = pcall(sampSendDialogResponse, sampGetCurrentDialogId(), 0, 0, '')
                    if not closed then DSP.add_log(tostring(close_err), 'error') end
                end
                DSP.add_log(DSP.auto.status, 'error')
            else
                R.transition(kind,'done','completed')
            end
        end
    end)
end
function R.positive(n)
    n = tonumber(n)
    return n and n == n and n > 0 and n % 1 == 0 and n <= 9007199254740991
end
function R.matches(text, name)
    -- Require the entire item name; matching just the first word can list another item.
    local want = tostring(name)
    local start = 1
    while true do
        local a, b = tostring(text):find(want, start, true)
        if not a then return false end
        local before, after = text:sub(a - 1, a - 1), text:sub(b + 1, b + 1)
        local tail = text:sub(b + 1):match('^%s*(.-)%s*$')
        local field = tail == '' or tail:find('^Количество') or tail:find('^количество')
            or tail:find('^Цена') or tail:find('^цена') or tail:find('^quantity') or tail:find('^price')
        local suffix = after == '' or after:match('[:»".,\t\r\n]') or (after:match('%s') and field)
        if (a == 1 or before:match('[%s:«"\t]')) and
            suffix then return true end
        start = b + 1
    end
end

end
__mod_39_trade_runtime()

local function __mod_40_auto()
-- Auto-buy / auto-sell engines: inventory scan + server dialogs.
DSP.auto = DSP.auto or {}
DSP.auto.buy_running = false
DSP.auto.sell_running = false
DSP.auto.scanning = false
DSP.auto.inv = {}
DSP.auto.inv_status = 'не сканирован'
DSP.auto.sell_confirmed = false
DSP.auto.sell_forbidden = false
DSP.auto.sell_no_slots = false
DSP.auto.stall_inventory_ready = false
DSP.auto.stall_inventory_seen_at = 0
DSP.auto.status = 'готов'
DSP.auto._prev_dialog = nil

local runtime = DSP.trade_runtime
local function trade_wait(ms) runtime.pause(ms) end
local function log(s, kind) DSP.add_log(s, kind) end

function DSP.auto.status_text()
    return DSP.auto.status .. '  |  инвентарь: ' .. DSP.auto.inv_status
end

local function clean(s)
    return (tostring(s or ''):gsub('{%x+}', ''))
end

function DSP.dialog_clean(s)
    s = tostring(s or '')
    local ok, cp = pcall(function() return require('encoding').CP1251:encode(s) end)
    if ok and cp and cp ~= '' and not s:find('[\192-\255]') then s = cp end
    return clean(s)
end

local function base_name(name)
    return (tostring(name or ''):gsub('%s*%(%+%d+%)%s*$', ''))
end

local function has_qty(text)
    local t = DSP.lower and DSP.lower(text) or tostring(text or ''):lower()
    if t == '' then return false end
    local has_qty_word = t:find('\xea\xee\xeb\xe8\xf7', 1, true) ~= nil
        or t:find('\xea\xee\xeb-\xe2\xee', 1, true) ~= nil
        or t:find('\xea\xee\xeb \xe2\xee', 1, true) ~= nil
        or t:find('quantity', 1, true) ~= nil
        or t:find('amount', 1, true) ~= nil
    local has_price_word = t:find('\xf6\xe5\xed', 1, true) ~= nil
        or t:find('price', 1, true) ~= nil
        or t:find('cost', 1, true) ~= nil
    if has_qty_word and has_price_word then return true end
    return t:find('%d+%s*,%s*%d+') ~= nil
end

local function close_dialog()
    if sampIsDialogActive() then
        sampSendDialogResponse(sampGetCurrentDialogId(), 0, 0, '')
        for _ = 1, 14 do
            if not sampIsDialogActive() then break end
            trade_wait(25)
        end
    end
end

local function wait_dialog(ids, ms)
    for _ = 1, math.ceil((ms or 2000) / 30) do
        trade_wait(30)
        if sampIsDialogActive() then
            local id = sampGetCurrentDialogId()
            if not ids then return id end
            for _, want in ipairs(ids) do
                if id == want then return id end
            end
        end
    end
    return nil
end

local function wait_text(id, ms)
    local prev, stable = '', 0
    for _ = 1, math.ceil((ms or 800) / 30) do
        trade_wait(30)
        if not sampIsDialogActive() or sampGetCurrentDialogId() ~= id then
            return prev
        end
        local cur = sampGetDialogText() or ''
        if cur ~= '' then
            if cur == prev then
                stable = stable + 1
                if stable >= 2 then return cur end
            else
                stable = 0
            end
            prev = cur
        end
    end
    return prev
end

-- Open the player's stall and load its slot map before real listing.
-- Arizona expects this context before interface 60/-1/2 listing clicks.
function DSP.auto.prepare_stall_inventory()
    runtime.transition('sell','open_shop','request native stall menu')
    DSP.auto.stall_inventory_ready=false
    DSP.auto.stall_inventory_seen_at=0
    close_dialog()
    if type(_G.dsp_click_slot)~='function' then return false,'нет RakNet click helper' end
    _G.dsp_click_slot(8,7,-1,'')
    runtime.transition('sell','wait_shop','dialogs 3040/15072')
    local menu=wait_dialog({3040,15072},3000)
    if not menu then return false,'меню лавки не открылось' end
    wait_text(menu,450)
    if not sampIsDialogActive() or sampGetCurrentDialogId()~=menu then
        return false,'меню лавки закрылось'
    end
    -- The first row opens the stall inventory; the server then sends iface52/type1.
    runtime.transition('sell','open_inventory','menu='..tostring(menu))
    sampSendDialogResponse(menu,1,0,'')
    runtime.transition('sell','wait_inventory','iface52/type1')
    local elapsed=0
    while elapsed<5000 do
        trade_wait(50);elapsed=elapsed+50
        if DSP.auto.stall_inventory_ready then runtime.transition('sell','inventory_ready','iface52/type1');return true end
    end
    return false,'инвентарь лавки не загрузился'
end

function _G.dsp_click_slot(interfaceid, id, subid, json_str)
    local bs = raknetNewBitStream()
    raknetBitStreamWriteInt8(bs, 220)
    raknetBitStreamWriteInt8(bs, 63)
    raknetBitStreamWriteInt8(bs, interfaceid)
    raknetBitStreamWriteInt32(bs, id)
    raknetBitStreamWriteInt32(bs, subid)
    raknetBitStreamWriteInt16(bs, #json_str)
    raknetBitStreamWriteString(bs, json_str)
    raknetSendBitStreamEx(bs, 1, 7, 1)
    raknetDeleteBitStream(bs)
end

-- A matching ID alone is not enough: MonetLoader may expose a previous dialog's
-- text while the server is replacing it. Confirm both the active ID and the
-- stabilized title/body before submitting any values.
local function current_dialog_title(id)
    local title = ''
    if sampGetDialogTitle then
        local ok, v = pcall(sampGetDialogTitle)
        if ok and v then title = DSP.dialog_clean(v) end
    end
    local meta = DSP.auto.dialog_meta
    if title == '' and meta and tonumber(meta.id) == tonumber(id) then
        title = tostring(meta.title or '')
    end
    return title
end

local function trade_input_semantics(text)
    local t = DSP.lower and DSP.lower(text) or tostring(text or ''):lower()
    return t:find('\xea\xee\xeb\xe8\xf7',1,true) ~= nil
        or t:find('quantity',1,true) ~= nil
        or t:find('amount',1,true) ~= nil
        or t:find('\xf6\xe5\xed',1,true) ~= nil
        or t:find('price',1,true) ~= nil
        or t:find('cost',1,true) ~= nil
        or t:find('\xe2\xe2\xe5\xe4',1,true) ~= nil
        or t:find('%d+%s*,%s*%d+') ~= nil
end

local function trade_dialog_matches(id, item_name, kind, body_override)
    if not sampIsDialogActive() or sampGetCurrentDialogId() ~= id then return false, '', '' end
    local body = DSP.dialog_clean(body_override or sampGetDialogText() or '')
    local title = current_dialog_title(id)
    local joined = title .. '\n' .. body
    local wanted = base_name(item_name)
    if wanted ~= '' and runtime.matches(joined, wanted) then return true, body, title end
    -- The selected item is already bound by the immediately preceding slot/search
    -- action. Some Arizona Mobile builds show a generic final input whose body has
    -- only quantity/price instructions. Accept that recognized trade input instead
    -- of refusing to type anything.
    if trade_input_semantics(joined) then return true, body, title end
    return false, body, title
end

local function wait_trade_item_dialog(ids, item_name, timeout, kind)
    local elapsed=0
    local observed=''
    while elapsed<(timeout or 3200) do
        trade_wait(40); elapsed=elapsed+40
        if sampIsDialogActive() then
            local id=sampGetCurrentDialogId()
            local allowed=false
            for _,x in ipairs(ids) do if x==id then allowed=true;break end end
            if allowed then
                local ok,body,title=trade_dialog_matches(id,item_name,kind)
                observed=(title or '')..'\n'..(body or '')
                if ok then
                    local stable=wait_text(id,360)
                    if sampIsDialogActive() and sampGetCurrentDialogId()==id then
                        local ok2,sbody,stitle=trade_dialog_matches(id,item_name,kind,stable)
                        if ok2 then return id,sbody,stitle end
                    end
                end
            end
        end
    end
    return nil,observed,''
end

local function parse_inventory(text)
    local raw = {}
    for line in tostring(text or ''):gmatch('[^\r\n]+') do
        local clean_line = clean(line)
        local slot_s, name, cnt_s
        slot_s, name, cnt_s = clean_line:match('%[(%d+)%]%s+(.-)%s+%{[^}]*%}%[(%d+)%s+')
        if not slot_s then
            slot_s, name, cnt_s = clean_line:match('%[(%d+)%]%s+(.-)%s+%[(%d+)%s+')
        end
        if not slot_s then
            slot_s, name, cnt_s = clean_line:match('%[(%d+)%]%s+(.-)%s+%[(%d+)%]')
        end
        if slot_s and name and cnt_s then
            name = name:match('^%s*(.-)%s*$') or name
            if name ~= '' and name ~= 'Пусто' then
                table.insert(raw, { slot = tonumber(slot_s), name = name, count = tonumber(cnt_s) or 1 })
            end
        end
    end
    local grouped, by_name = {}, {}
    for _, it in ipairs(raw) do
        local g = by_name[it.name]
        if not g then
            g = { name = it.name, count = 0, stacks = {} }
            by_name[it.name] = g
            table.insert(grouped, g)
        end
        g.count = g.count + it.count
        table.insert(g.stacks, { slot = it.slot, count = it.count })
    end
    return grouped
end

function DSP.auto.scan_inventory()
    if DSP.auto.scanning or DSP.auto.buy_running or DSP.auto.sell_running then return false end
    DSP.auto.scanning = true
    DSP.auto.scan_generation = (DSP.auto.scan_generation or 0) + 1
    local generation = DSP.auto.scan_generation
    DSP.auto.inv = {}
    DSP.auto.inv_status = 'сканирование...'
    log('Инвентарь: открываю /mm...')
    sampSendChat('/mm')
    lua_thread.create(function()
        for _ = 1, 500 do
            if not DSP.auto.scanning or generation ~= DSP.auto.scan_generation then return end
            trade_wait(50)
        end
        if DSP.auto.scanning and generation == DSP.auto.scan_generation then
            DSP.auto.scanning = false
            DSP.auto.inv_status = 'таймаут'
            log('Инвентарь: таймаут. Откройте инвентарь через /mm вручную и повторите.', 'error')
        end
    end)
end

local function inventory_dialog(id, text)
    if id == 25494 or id == 25493 then return true end
    local t = clean(text)
    return (t:find('%[%d+%]') ~= nil and (t:find('%[%d+ шт%]') ~= nil or t:find('Инвентарь:') ~= nil))
        or t:find('Следующая страница', 1, true) ~= nil
        or t:find('Предыдущая страница', 1, true) ~= nil
end

function DSP.auto.on_dialog(id, style, title, b1, b2, text)
    DSP.auto.dialog_meta = {id=id, style=style, title=DSP.dialog_clean(title or ''),
        text=DSP.dialog_clean(text or ''), at=os.time(), mono=os.clock()}
    if DSP.market then
        if id == 15073 and DSP.market.mark_cr_dialog then DSP.market.mark_cr_dialog() end
        if DSP.market.observe_cr_detail then
            local ok,err=pcall(DSP.market.observe_cr_detail,title,text)
            if not ok then log('ЦР: ошибка разбора истории: '..tostring(err),'error') end
        end
    end
    -- v1.2 Stage 3 hotfix: CR marker scan (dialog 15073).
    -- When scan_cr_marker() has armed the scan state, intercept dialog 15073
    -- and let the market module parse + flip pages.
    if id == 15073 and DSP.market and DSP.market.cr_scan_state and DSP.market.cr_scan_state.active and DSP.market.on_cr_marker_dialog then
        pcall(DSP.market.on_cr_marker_dialog, text)
        return true  -- intercept: don't let other handlers close it
    end
    if DSP.auto.scanning then
        local generation = DSP.auto.scan_generation
        if id == 722 or id == 600 or id == 235 then
            lua_thread.create(function()
                trade_wait(120)
                if not DSP.auto.scanning or generation ~= DSP.auto.scan_generation then return end
                sampSendDialogResponse(id, 1, 0, '')
            end)
            return true
        end
        if inventory_dialog(id, text) then
            local items = parse_inventory(text)
            local slots = {}
            for _, old in ipairs(DSP.auto.inv) do
                for _, st in ipairs(old.stacks) do slots[st.slot] = true end
            end
            for _, it in ipairs(items) do
                local group
                for _, old in ipairs(DSP.auto.inv) do if old.name == it.name then group = old end end
                for _, st in ipairs(it.stacks) do
                    if not slots[st.slot] then
                        if not group then
                            group = {name = it.name, count = 0, stacks = {}}
                            table.insert(DSP.auto.inv, group)
                        end
                        group.count = group.count + st.count
                        table.insert(group.stacks, st)
                        slots[st.slot] = true
                    end
                end
            end
            DSP.auto.inv_status = #DSP.auto.inv .. ' поз. (' ..
                (function() local n = 0; for _, x in ipairs(DSP.auto.inv) do n = n + x.count end; return n end)() .. ' шт)'
            local next_idx
            local line_no = 0
            local header = style == 5 and 1 or 0
            for ln in tostring(text or ''):gmatch('[^\n]+') do
                line_no = line_no + 1
                if line_no > 1 and ln:find('Следующая страница', 1, true) then
                    next_idx = line_no - 1 - header
                    break
                end
            end
            if next_idx then
                log('Инвентарь: ' .. DSP.auto.inv_status .. ', дальше...')
                lua_thread.create(function()
                    trade_wait(140)
                    if not DSP.auto.scanning or generation ~= DSP.auto.scan_generation then return end
                    sampSendDialogResponse(id, 1, next_idx, '')
                end)
            else
                DSP.auto.scanning = false
                log('Инвентарь готов: ' .. DSP.auto.inv_status, 'ok')
                lua_thread.create(function()
                    trade_wait(100)
                    if generation ~= DSP.auto.scan_generation or DSP.auto.buy_running or DSP.auto.sell_running then return end
                    sampSendDialogResponse(id, 0, 0, '')
                    trade_wait(160)
                    if generation ~= DSP.auto.scan_generation or DSP.auto.buy_running or DSP.auto.sell_running then return end
                    _G.dsp_click_slot(52, -1, 4, '""')
                end)
            end
            return true
        end
    end
    DSP.auto.on_trade_feedback(text)
    return false
end

-- Arizona confirms shop listings through a SERVER CHAT message, not always
-- another dialog. A dialog-only acknowledgement made every real sale time out.
-- Never treat a generic chat message as a sale confirmation.
function DSP.auto.on_trade_feedback(text)
    if not DSP.auto.sell_running then return end
    local t=clean(text)
    if t:find('успешно выставлен на продажу',1,true)
        or t:find('Успешно выставлено на продажу',1,true)
        or t:find('Успешно выставлен на продажу',1,true) then
        DSP.auto.sell_confirmed=true
    elseif t:find('Данные товары запрещено продавать',1,true)
        or t:find('нельзя выставлять',1,true)
        or t:find('Запрещено',1,true) then
        DSP.auto.sell_forbidden=true;DSP.auto.sell_confirmed=true
    elseif t:find('нет доступных ячеек',1,true)
        or t:find('Нет доступных ячеек',1,true)
        or t:find('нет свободных мест',1,true)
        or t:find('Нет свободных мест',1,true) then
        DSP.auto.sell_no_slots=true;DSP.auto.sell_confirmed=true
    end
end

function DSP.auto.install()
    local ok, sampev = pcall(require, 'samp.events')
    if not ok or not sampev then
        log('Авто: samp.events недоступен', 'error')
        return
    end
    local prev_server=sampev.onServerMessage
    sampev.onServerMessage=function(color,text)
        -- Backup observer if the optional live hook is unavailable.
        if DSP.market and DSP.market.on_shop_lookup_feedback then
            local ok_feedback,err_feedback=pcall(DSP.market.on_shop_lookup_feedback,text)
            if not ok_feedback and DSP.flog then DSP.flog('FINDILAVKA auto feedback: '..tostring(err_feedback)) end
        end
        if DSP.auto.on_trade_feedback then
            local safe,err=pcall(DSP.auto.on_trade_feedback,text)
            if not safe then log('Торговля: ошибка обработки ответа: '..tostring(err),'error') end
        end
        if prev_server then return prev_server(color,text) end
    end
    DSP.auto._prev_dialog = sampev.onShowDialog
    sampev.onShowDialog = function(id, style, title, b1, b2, text)
        local prev = DSP.auto._prev_dialog
        local ret
        if prev then
            local r = { pcall(prev, id, style, title, b1, b2, text) }
            if r[1] then ret = r[2] end
        end
        local intercept = DSP.auto.on_dialog(id, style, title, b1, b2, text)
        if intercept then return false end
        return ret
    end
end

DSP.auto.helpers = {close_dialog = close_dialog, wait_dialog = wait_dialog, wait_text = wait_text,
    clean = clean, base_name = base_name, has_qty = has_qty,
    trade_dialog_matches = trade_dialog_matches, current_dialog_title = current_dialog_title,
    wait_trade_item_dialog = wait_trade_item_dialog}

end
__mod_40_auto()

local function __mod_41_trade_listing()
-- Auto listing orchestration, separate from inventory and dialog observation.
local runtime = DSP.trade_runtime
local trade_wait = runtime.pause
local log = DSP.add_log
local h = DSP.auto.helpers
local close_dialog, wait_dialog, wait_text = h.close_dialog, h.wait_dialog, h.wait_text
local clean, base_name, has_qty = h.clean, h.base_name, h.has_qty
local wait_item = h.wait_trade_item_dialog
local trade_dialog_matches, current_dialog_title = h.trade_dialog_matches, h.current_dialog_title
local trade_dialog_matches, current_dialog_title = h.trade_dialog_matches, h.current_dialog_title
local function queue_sell()
    local queue, available = {}, {}
    local preset=DSP.settings.sell_preset
    if type(preset)~='table' or type(preset.items)~='table' then return nil,'preset unavailable' end
    if type(DSP.auto.inv)~='table' then return nil,'inventory unavailable' end
    for _, p in ipairs(preset.items) do
        if type(p)~='table' then return nil,'invalid preset row' end
        if p.enabled ~= false and runtime.positive(p.price) and runtime.positive(p.qty or 1) then
            if type(p.name)~='string' or p.name=='' then return nil,'invalid item name' end
            local target = base_name(p.name)
            local left = tonumber(p.qty) or 1
            for _, inv in ipairs(DSP.auto.inv) do
                if type(inv)~='table' or type(inv.stacks)~='table' then
                    return nil,'inventory slot list is missing; scan inventory again'
                end
                if inv.name == p.name or ((tonumber(p.ench) or 0) == 0 and inv.name == target) then
                    for _, st in ipairs(inv.stacks) do
                        if type(st)~='table' or type(st.slot)~='number' or st.slot%1~=0
                            or st.slot<0 or st.slot>1000 then
                            return nil,'inventory slot invalid; scan inventory again'
                        end
                        if left <= 0 then break end
                        if available[st.slot] == nil then
                            available[st.slot] = runtime.positive(st.count) and tonumber(st.count) or 0
                        end
                        local take = math.min(available[st.slot], left)
                        if take > 0 then
                            table.insert(queue, {
                                name = p.name, base = target, price = p.price,
                                qty = take, slot = st.slot,
                            })
                            left = left - take
                            available[st.slot] = available[st.slot] - take
                        end
                    end
                end
            end
            if left > 0 then return nil, p.name .. ': недостаточно в инвентаре' end
        end
    end
    return queue
end

function DSP.auto.start_sell()
    if DSP.auto.sell_running or DSP.auto.scanning then return false end
    if DSP.auto.buy_running or DSP.auto.scanning then return false end
    local preset=DSP.settings.sell_preset
    local items=type(preset)=='table' and preset.items or nil
    if type(items)~='table' then DSP.notify('Sale preset unavailable');return false end
    local n = 0
    for _, it in ipairs(items) do
        if type(it)~='table' then DSP.notify('Invalid preset row');return false end
        if it.enabled ~= false then n = n + 1 end
    end
    if n == 0 then DSP.notify('Продажа: пресет пуст'); return end
    if #DSP.auto.inv == 0 then
        DSP.notify('Продажа: сначала просканируйте инвентарь')
        return
    end
    local q_ok,queue,err=pcall(queue_sell)
    if not q_ok then
        DSP.flog('PRESET queue_sell error: '..tostring(queue))
        DSP.notify('Preset error; check standalone.log')
        return false
    end
    if not queue then DSP.notify('Sale: '..tostring(err)); return false end
    if #queue == 0 then DSP.notify('Продажа: в инвентаре нет позиций из пресета'); return end
    local dry_run = DSP.settings.dry_run
    DSP.auto.sell_running = true
    DSP.auto.sell_confirmed = false
    DSP.auto.sell_forbidden = false
    DSP.auto.sell_no_slots = false
    DSP.auto.status = 'продажа...'
    DSP.flog('PRESET sale accepted: '..#queue..' stacks, dry_run='..tostring(dry_run))
    log('Продажа: ' .. #queue .. ' стек(ов)')
    if dry_run then
        DSP.notify('ТЕСТ: игровые окна не открываются. Для действий нужен режим РЕАЛЬНО.')
        -- A preview must NEVER send RakNet clicks or dialog responses.
        DSP.auto.sell_running=true
        DSP.auto.status='sale preview...'
        runtime.spawn('sell',function()
            DSP.auto.progress.total=#queue
            for i,it in ipairs(queue) do
                DSP.auto.progress.dry=i
                DSP.auto.progress.done=i
                log('preview: '..it.name..' x'..it.qty..' @ '..DSP.money(it.price))
            end
            DSP.auto.sell_running=false
            DSP.auto.status='sale preview: '..#queue..' stacks, no packets sent'
        end)
        return true
    end
    runtime.spawn('sell', function()
        DSP.auto.progress.total = #queue
        local done = 0
        -- Establish the same native stall context as manual listing before
        -- clicking inventory slots. Without it Arizona may ignore iface60 clicks.
        if DSP.auto.prepare_stall_inventory then
            local ok,why=DSP.auto.prepare_stall_inventory()
            if not ok then
                DSP.auto.sell_running=false
                DSP.auto.status='продажа: лавка не готова'
                log('Продажа: '..tostring(why or 'не удалось открыть инвентарь лавки'),'error')
                DSP.notify('Продажа: '..tostring(why or 'лавка не готова'))
                return
            end
            trade_wait(120)
        end
        for _, it in ipairs(queue) do
            if not DSP.auto.sell_running then break end
            DSP.auto.status = 'продажа: ' .. it.name .. ' (' .. done .. '/' .. #queue .. ')'
            local json = '{"amount":' .. it.qty .. ',"id":0,"slot":' .. it.slot .. ',"type":1}'
            local got, id, dialog_text = false, nil, nil
            for attempt = 1, 3 do
                close_dialog()
                DSP.auto.sell_confirmed = false
                DSP.auto.sell_forbidden, DSP.auto.sell_no_slots = false, false
                -- Native RakNet must not receive stale/invalid slot data.
                if type(it.slot)~='number' or it.slot<0 or it.slot>1000 or it.slot%1~=0 then
                    error('Invalid inventory slot at send: '..tostring(it.slot))
                end
                runtime.transition('sell','select_item',tostring(it.name)..' slot='..tostring(it.slot))
                DSP.flog('PRESET sale packet: item='..tostring(it.name)..' slot='..it.slot..' qty='..tostring(it.qty))
                _G.dsp_click_slot(60, -1, 2, json)
                runtime.transition('sell','wait_item_dialog',tostring(it.name))
                -- v1.2 hotfix: also accept 15068-15071 (newer Arizona Mobile выставление dialogs).
                id,dialog_text,dialog_title = wait_item({ 26547, 15068, 15069, 15070, 15071 }, it.name, 2600, 'sell')
                if id then
                    got = true
                    break
                end
                log('Продажа: диалог предмета не готов ('..attempt..'): '..tostring(dialog_text or ''):sub(1,90),'error')
                close_dialog()
                trade_wait(180)
            end
            if got then
                -- mimgui/MonetLoader may publish the dialog text before the
                -- native input control is ready. Follow the observed game
                -- sequence: one short settle, then verify the *same* item/ID.
                trade_wait(180)
                local current=sampIsDialogActive() and sampGetCurrentDialogId() or nil
                local valid,actual,actual_title=false,'',''
                if current then valid,actual,actual_title=trade_dialog_matches(current,it.name,'sell') end
                if current~=id or not valid then
                    got=false
                    log('\xcf\xf0\xee\xe4\xe0\xe6\xe0: \xe4\xe8\xe0\xeb\xee\xe3 \xf1\xec\xe5\xed\xe8\xeb\xf1\xff \xe4\xee \xee\xf2\xef\xf0\xe0\xe2\xea\xe8, id='..tostring(current)..
                        ', \xee\xe6\xe8\xe4\xe0\xeb\xf1\xff='..tostring(id)..' \xb7 '..it.name,'error')
                else
                    dialog_text,dialog_title=actual,actual_title
                end
            end
            if got then
                local txt = (dialog_title or '') .. '\n' .. (dialog_text or '')
                local combined = has_qty(txt)
                -- Market Helper behavior: amount is already present in the iface60
                -- slot packet. If this client only asks for price, send only price.
                local resp = combined and (tostring(it.qty) .. ',' .. tostring(it.price))
                    or tostring(it.price)
                DSP.flog('PRESET sale input: item='..tostring(it.name)..' dialog='..tostring(id)..
                    ' mode='..(combined and 'qty_price' or 'price_only')..' resp_len='..tostring(#resp))
                if dry_run then
                    DSP.auto.progress.dry = DSP.auto.progress.dry + 1
                    log('dry-run: продал бы ' .. it.name .. ' x' .. it.qty .. ' @ ' .. DSP.money(it.price))
                    close_dialog()
                else
                    DSP.auto.sell_confirmed = false
                    -- v1.2 hotfix: use the active dialog id (may be 26547 or
                    -- 15068-15071 in newer Arizona Mobile). Fallback chain.
                    local resp_id = id or sampGetCurrentDialogId and sampGetCurrentDialogId() or 26547
                    runtime.transition('sell','submit',tostring(it.name)..' qty='..tostring(it.qty)..' price='..tostring(it.price))
                    sampSendDialogResponse(resp_id, 1, 0, resp)
                    for _ = 1, 100 do
                        if DSP.auto.sell_confirmed then break end
                        trade_wait(40)
                    end
                    if sampIsDialogActive() and sampGetCurrentDialogId()==resp_id then
                        sampSendDialogResponse(resp_id, 0, 0, '')
                    end
                    if DSP.auto.sell_no_slots then
                        DSP.auto.progress.failed = DSP.auto.progress.failed + 1
                        log('Продажа: нет свободных мест', 'error')
                        DSP.auto.sell_running = false
                        break
                    end
                    if DSP.auto.sell_forbidden then
                        DSP.auto.progress.failed = DSP.auto.progress.failed + 1
                        log('Продажа: запрещено для ' .. it.name, 'error')
                    elseif DSP.auto.sell_confirmed then
                        done = done + 1
                        DSP.auto.progress.done = done
                        log('Выставлено: ' .. it.name .. ' x' .. it.qty .. ' @ ' .. DSP.money(it.price), 'ok')
                    else
                        DSP.auto.progress.failed = DSP.auto.progress.failed + 1
                        log('Продажа: нет подтверждения для ' .. it.name, 'error')
                    end
                end
                trade_wait(260)
            else
                DSP.auto.progress.failed = DSP.auto.progress.failed + 1
                log('Продажа: не открылся диалог для ' .. it.name .. ' (slot ' .. it.slot .. ')', 'error')
                close_dialog()
            end
        end
        DSP.auto.sell_running = false
        DSP.auto.status = 'продажа: ' .. done .. '/' .. #queue
        log('Продажа завершена: ' .. done .. '/' .. #queue, 'ok')
        -- Inventory is now stale; refresh explicitly before another sale.
        DSP.auto.inv = {}
        DSP.auto.inv_status = 'нужно обновить'
    end)
    return true
end

function DSP.auto.stop_sell()
    if not DSP.auto.sell_running then return false end
    runtime.cancel()
    DSP.auto.sell_running = false
    DSP.auto.status = 'продажа остановлена'
    close_dialog()
    log('Продажа остановлена')
end

end
__mod_41_trade_listing()

local function __mod_42_trade_buy()
-- Auto listing orchestration, separate from inventory and dialog observation.
local runtime = DSP.trade_runtime
local trade_wait = runtime.pause
local log = DSP.add_log
local h = DSP.auto.helpers
local close_dialog, wait_dialog, wait_text = h.close_dialog, h.wait_dialog, h.wait_text
local clean, base_name, has_qty = h.clean, h.base_name, h.has_qty
local wait_item = h.wait_trade_item_dialog
-- Search results may carry a line number, price/count columns and colour tags.
-- Match the complete normalized item name; do not pick an unrelated first-word hit.
local function find_list_index(text, name)
    local idx=0
    local fold=DSP.lower or string.lower
    local wanted=fold(base_name(name)):match('^%s*(.-)%s*$')
    local found=nil
    for line in tostring(text or ''):gmatch('[^\r\n]+') do
        local nm=clean(line):gsub('^%s*%d+[%.%)]%s*',''):match('^%s*(.-)%s*$')
        nm=(nm:match('^(.-)\t') or nm):match('^%s*(.-)%s*$')
        -- Some builds put quantity in square brackets after the item name.
        local base=nm:match('^(.-)%s+%[%d+[^%]]*%]') or nm
        base=fold(base_name(base)):match('^%s*(.-)%s*$')
        if base==wanted then
            if found~=nil then return nil,'несколько одинаковых строк' end
            found=idx
        end
        idx=idx+1
    end
    return found
end

local function open_shop_menu()
    runtime.transition('buy','open_shop','request native stall menu')
    close_dialog()
    _G.dsp_click_slot(8, 7, -1, '')
    runtime.transition('buy','wait_shop','dialogs 3040/15072')
    -- v1.2 hotfix: accept 15072/15073 fallback for shop menu open in newer Arizona Mobile.
    return wait_dialog({ 3040, 15072 }, 2500)
end

local function buy_one(it, pi, total, dry_run)
    DSP.auto.status = 'скупка: ' .. it.name .. ' (' .. pi .. '/' .. total .. ')'
    if not sampIsDialogActive() or (sampGetCurrentDialogId() ~= 3040 and sampGetCurrentDialogId()~=15072) then
        if not open_shop_menu() then
            log('Скупка: меню не открылось для ' .. it.name, 'error')
            return false
        end
    end
    local menu_id = sampGetCurrentDialogId()
    wait_text(menu_id, 350)
    runtime.transition('buy','open_search','menu='..tostring(menu_id))
    sampSendDialogResponse(menu_id, 1, 2, '')
    -- v1.2 hotfix: also accept 15065-15067 (newer search/dialog IDs).
    local id = wait_dialog({ 25663, 15065, 15066, 15067 }, 3000)
    if not id then
        log('Скупка: строка поиска не открылась', 'error')
        return false
    end
    wait_text(id, 700)
    local search = base_name(it.name):sub(1, 24)
    runtime.transition('buy','search',tostring(it.name))
    sampSendDialogResponse(id, 1, 0, search)
    -- v1.2 hotfix: search results dialog may also be 15068 in newer versions.
    id = wait_dialog({ 25664, 15068 }, 3500)
    if not id then
        log('Скупка: результаты не открылись: ' .. it.name, 'error')
        return false
    end
    local list_text = DSP.dialog_clean(wait_text(id, 500))
    local idx,index_err = find_list_index(list_text, it.name)
    if idx==nil then
        log('Скупка: '..tostring(index_err or 'не найдено')..': ' .. it.name, 'error')
        close_dialog()
        return false
    end
    runtime.transition('buy','select_result',tostring(it.name)..' row='..tostring(idx))
    sampSendDialogResponse(id, 1, idx, '')
    -- v1.2 hotfix: выставление price dialog may also use 15070/15071 in newer Arizona Mobile.
    id = wait_dialog({ 26560, 26563, 15070, 15071 }, 3000)
    if not id then
        log('Скупка: диалог цены не открылся: ' .. it.name, 'error')
        return false
    end
    if id == 26560 then
        sampSendDialogResponse(id, 1, 0, '')
        -- v1.2 hotfix: also accept 15071 fallback.
        id = wait_dialog({ 26563, 15071 }, 2000)
    end
    -- v1.2 hotfix: accept 15071 as alternative to 26563 for the final выставление dialog.
    if id ~= 26563 and id ~= 15071 then return false end
    local validated_id,txt,dialog_title=wait_item({id},it.name,1700,'buy')
    local base = base_name(it.name)
    if not validated_id then
        log('Скупка: в диалоге другой товар: ' .. it.name, 'error')
        close_dialog()
        return false
    end
    -- Stabilize the native price input after the dialog text appears. Never
    -- submit to another item/ID that replaced it during the delay.
    trade_wait(180)
    local current=sampIsDialogActive() and sampGetCurrentDialogId() or nil
    local valid,actual,actual_title=false,'',''
    if current then valid,actual,actual_title=trade_dialog_matches(current,it.name,'buy') end
    if current~=id or not valid then
        log('\xd1\xea\xf3\xef\xea\xe0: \xe4\xe8\xe0\xeb\xee\xe3 \xe8\xe7\xec\xe5\xed\xe8\xeb\xf1\xff \xe4\xee \xee\xf2\xef\xf0\xe0\xe2\xea\xe8 \xb7 '..it.name,'error')
        close_dialog()
        return false
    end
    txt,dialog_title=actual,actual_title
    local qty = tonumber(it.qty) or 1
    if qty < 1 then qty = 1 end
    local combined = has_qty((dialog_title or '') .. '\n' .. (txt or ''))
    if not combined and qty>1 then
        -- Same fallback as Market Helper: a price-only buy dialog represents one
        -- unit, so the outer loop repeats the listing until requested qty is done.
        log('Buy: price-only dialog, one unit per submit', 'info')
        qty=1
    end
    local resp = combined and (tostring(qty) .. ',' .. tostring(it.price))
        or tostring(it.price)
    DSP.flog('PRESET buy input: item='..tostring(it.name)..' dialog='..tostring(id)..
        ' mode='..(combined and 'qty_price' or 'price_only')..' resp_len='..tostring(#resp))
    if dry_run then
        log('dry-run: купил бы ' .. it.name .. ' x' .. qty .. ' @ ' .. DSP.money(it.price))
        close_dialog()
        return 'dry', tonumber(it.qty) or 1
    end
    -- v1.2 hotfix: use the active dialog id (may be 26563 or 15071 in newer
    -- Arizona Mobile выставление dialogs). Fallback chain via sampGetCurrentDialogId.
    local resp_id = id or (sampGetCurrentDialogId and sampGetCurrentDialogId()) or 26563
    sampSendDialogResponse(resp_id, 1, 0, resp)
    log('Скупка: ' .. it.name .. ' x' .. qty .. ' @ ' .. DSP.money(it.price), 'ok')
    for _ = 1, 24 do
        if not sampIsDialogActive() then return 'bought', qty end
        trade_wait(30)
    end
    log('Скупка: нет подтверждения закрытия диалога', 'error')
    return false
end

function DSP.auto.start_buy()
    if DSP.auto.buy_running or DSP.auto.scanning then return false end
    if DSP.auto.sell_running or DSP.auto.scanning then return false end
    local list = {}
    local preset=DSP.settings.buy_preset
    if type(preset)~='table' or type(preset.items)~='table' then
        DSP.notify('Buy preset unavailable');return false
    end
    for _, it in ipairs(preset.items) do
        if type(it)~='table' then DSP.notify('Invalid buy preset row');return false end
        if it.enabled ~= false and runtime.positive(it.price) and runtime.positive(it.qty or 1) then
            if type(it.name)~='string' or it.name=='' then
                DSP.notify('Invalid buy preset item name');return false
            end
            list[#list+1] = {name=it.name,price=tonumber(it.price),qty=tonumber(it.qty) or 1}
        end
    end
    if #list == 0 then DSP.notify('Скупка: пресет пуст или цены 0'); return end
    local dry_run = DSP.settings.dry_run
    DSP.auto.buy_running = true
    DSP.auto.status = 'скупка...'
    DSP.flog('PRESET buy accepted: '..#list..' positions, dry_run='..tostring(dry_run))
    log('Скупка: ' .. #list .. ' позиций' .. (dry_run and ' (dry-run)' or ''))
    if dry_run then
        DSP.notify('ТЕСТ: игровые окна не открываются. Для действий нужен режим РЕАЛЬНО.')
        -- No shop menu, network packets or dialog interactions in preview.
        runtime.spawn('buy',function()
            DSP.auto.progress.total=#list
            for i,it in ipairs(list) do
                DSP.auto.progress.dry=i
                DSP.auto.progress.done=i
                DSP.auto.progress.units=(DSP.auto.progress.units or 0)+(it.qty or 1)
                log('preview: '..it.name..' x'..it.qty..' @ '..DSP.money(it.price))
            end
            DSP.auto.buy_running=false
            DSP.auto.status='buy preview: '..#list..' positions, no packets sent'
        end)
        return true
    end
    runtime.spawn('buy', function()
        DSP.auto.progress.total = #list
        if not open_shop_menu() then
            log('Скупка: лавка не открылась. Подойдите к лавке.', 'error')
            DSP.auto.buy_running = false
            DSP.auto.status = 'скупка: ошибка'
            return
        end
        local bought, dry = 0, 0
        for pi, it in ipairs(list) do
            if not DSP.auto.buy_running then break end
            local remaining = tonumber(it.qty) or 1
            local result
            while remaining > 0 do
                local entry = {}
                for key, value in pairs(it) do entry[key] = value end
                entry.qty = remaining
                local units
                result, units = buy_one(entry, pi, #list, dry_run)
                if not result then break end
                remaining = remaining - (units or 1)
                DSP.auto.progress.units = (DSP.auto.progress.units or 0) + (units or 1)
                close_dialog()
            end
            if remaining == 0 and result == 'bought' then bought = bought + 1
            elseif remaining == 0 and result == 'dry' then dry = dry + 1
            else DSP.auto.progress.failed = DSP.auto.progress.failed + 1 end
            DSP.auto.progress.done, DSP.auto.progress.dry = bought, dry
            close_dialog()
            if pi < #list and DSP.auto.buy_running then
                if not open_shop_menu() then break end
            end
        end
        DSP.auto.buy_running = false
        DSP.auto.status = 'скупка: ' .. bought .. '/' .. #list .. (dry > 0 and (' (dry ' .. dry .. ')') or '')
        log('Скупка завершена: ' .. bought .. '/' .. #list, 'ok')
    end)
    return true
end

function DSP.auto.stop_buy()
    if not DSP.auto.buy_running then return false end
    runtime.cancel()
    DSP.auto.buy_running = false
    DSP.auto.status = 'скупка остановлена'
    close_dialog()
    log('Скупка остановлена')
end


-- Queue user-initiated listing outside the ImGui drawing callback. Synchronous
-- Lua exceptions during an ImGui frame can corrupt its Begin/End stack.
-- This catches Lua-side errors only; native Android faults still need a log.
function DSP.auto.safe_start(kind)
    if kind~='sell' and kind~='buy' then return false end
    if DSP.auto._launch_queued or DSP.auto.buy_running or DSP.auto.sell_running or DSP.auto.scanning then
        DSP.notify('Trade already running or inventory scan active')
        return false
    end
    if type(lua_thread)~='table' or type(lua_thread.create)~='function' then
        DSP.notify('Thread scheduler unavailable')
        return false
    end
    DSP.auto._launch_queued=true
    DSP.flog('PRESET queued: kind='..kind..' dry_run='..tostring(DSP.settings.dry_run))
    local ok,err=pcall(lua_thread.create,function()
        DSP.auto._launch_queued=false
        local started,result=xpcall(function()
            if kind=='sell' then return DSP.auto.start_sell() end
            return DSP.auto.start_buy()
        end,function(e)
            if debug and debug.traceback then return debug.traceback(tostring(e),2) end
            return tostring(e)
        end)
        if not started then
            DSP.auto[kind..'_running']=false
            DSP.auto.status='Preset error; see standalone.log'
            if DSP.flog then DSP.flog('PRESET launch exception: '..tostring(result)) end
            DSP.notify('Preset error; see standalone.log')
        elseif result~=true then
            if DSP.flog then DSP.flog('PRESET launch rejected: '..kind) end
        end
    end)
    if not ok then
        DSP.auto._launch_queued=false
        DSP.flog('PRESET scheduler failure: '..tostring(err))
        DSP.notify('Failed to queue preset; see standalone.log')
        return false
    end
    return true
end
end
