local function get_session(id,title)
    local now=os.time();local s=L.session
    if not s or now-(s.last or 0)>20 or
        (s.id~=tonumber(id) and tonumber(id)~=nil and not s.pawn_context) then
        s=new_session(id,title)
    end
    s.id=tonumber(id) or s.id
    s.last=now;if clean(title)~='' then s.title=clean(title) end
    return s
end
local function history_add(root,item,at,session)
    if session.history_seen[item.key] then return end
    session.history_seen[item.key]=true
    local h=root.history[item.key]
    if type(h)~='table' then h={name=item.name,side=item.side,item_id=item.item_id,ench=item.ench,points={}};root.history[item.key]=h end
    if type(h.points)~='table' then h.points={} end
    h.name=item.name;h.side=item.side;h.item_id=item.item_id or h.item_id;h.ench=item.ench or h.ench
    local prev=h.points[#h.points]
    if prev and prev.price==item.price and at-(prev.at or 0)<21600 then prev.at=at
    else h.points[#h.points+1]={at=at,price=item.price} end
    local cutoff=at-(tonumber(L.history_days) or 365)*86400
    while #h.points>0 and ((h.points[1].at or 0)<cutoff or #h.points>(tonumber(L.max_history_per_item) or 512)) do table.remove(h.points,1) end
end
local function commit_session(session,source)
    if not session then return false,'session' end
    local root,skey=srv(current_sid());local at=os.time();local items={}
    for _,k in ipairs(session.order) do local r=session.items[k];if r then items[#items+1]=r;history_add(root,r,at,session) end end
    table.sort(items,function(a,b) if a.name~=b.name then return a.name<b.name end;if a.side~=b.side then return a.side<b.side end;return a.price<b.price end)
    root.latest={at=at,started=session.started,title=session.title,items=items,pages=session.page_count or 0,source=source or 'dialog'}
    root.scans[#root.scans+1]={at=at,count=#items,pages=session.page_count or 0,source=source or 'dialog'}
    while #root.scans>180 do table.remove(root.scans,1) end
    L._dirty=true
    if DSP.flog then DSP.flog(('LOMBARD commit sid=%s items=%d pages=%d'):format(skey,#items,session.page_count or 0)) end
    return true,#items
end
function L.observe_dialog(id,style,title,b1,b2,text)
    if not L.is_dialog(title,text) then return false end
    L._last_dialog={id=id,style=style,title=title,b1=b1,b2=b2,text=text,at=os.time()}
    local s=get_session(id,title);local h=page_hash(title,text)
    if not s.pages[h] then
        s.pages[h]=true;s.page_count=(s.page_count or 0)+1
        local rows=L.parse_dialog(title,text)
        for _,r in ipairs(rows) do
            local k=r.key
            local old=s.items[k]
            if not old then s.items[k]=r;s.order[#s.order+1]=k
            elseif r.price~=old.price then
                -- Same item can legitimately appear more than once at different prices.
                local k2=k..':p'..tostring(r.price)
                if not s.items[k2] then r.key=k2;s.items[k2]=r;s.order[#s.order+1]=k2 end
            end
        end
        if #rows>0 then commit_session(s,L.auto_scan and 'auto_pages' or 'passive') end
    end
    return true
end
local function next_index(text)
    local i=0
    for line in tostring(text or ''):gmatch('[^\n]+') do
        local q=lower(clean(line))
        if q:find(CP_NEXT,1,true) or q:find(CP_MORE,1,true) or q=='>>' then return i end
        i=i+1
    end
    return nil
end
local function schedule_next(id,text)
    if not L.auto_scan then return end
    local idx=next_index(text);if idx==nil then
        L.auto_scan=false
        if DSP.notify then DSP.notify('Lombard scan complete: '..tostring(L.stats().items)..' items') end
        return
    end
    if not lua_thread or not lua_thread.create or not wait then return end
    lua_thread.create(function()
        wait(120)
        if L.auto_scan and sampIsDialogActive and sampIsDialogActive() and sampGetCurrentDialogId and sampGetCurrentDialogId()==id then
            pcall(sampSendDialogResponse,id,1,idx,'')
        end
    end)
end
function L.stats(server_id)
    local root=srv(server_id);local hist=0;for _ in pairs(root.history) do hist=hist+1 end
    return {items=#(root.latest.items or {}),last=root.latest.at or 0,pages=root.latest.pages or 0,history_items=hist,scans=#root.scans,server=tonumber(server_id) or current_sid()}
end
function L.search(query,server_id)
    local root=srv(server_id);local q=lower(clean(query));local out={}
    for _,r in ipairs(root.latest.items or {}) do
        if q=='' or lower(r.name):find(q,1,true) then out[#out+1]=r end
    end
    table.sort(out,function(a,b) if a.name~=b.name then return a.name<b.name end;return a.price<b.price end)
    return out
end
function L.history(item_key,server_id)
    local root=srv(server_id);local h=root.history[item_key];return h and h.points or {}
end
function L.links(query,server_id)
    local out={};if not DSP.shop_store or not DSP.shop_store.search then return out end
    local sidv=tonumber(server_id) or current_sid()
    for _,p in ipairs(L.search(query,sidv)) do
        local refs=DSP.shop_store.search(p.base_name or p.name,nil,sidv)
        local best_sell,best_buy
        for _,ref in ipairs(refs or {}) do
            local price=tonumber(ref.offer and ref.offer.price)
            if price then
                if ref.side=='sell' and (not best_sell or price<best_sell.price) then best_sell={price=price,shop=ref.shop and ref.shop.num,owner=ref.shop and ref.shop.owner} end
                if ref.side=='buy' and (not best_buy or price>best_buy.price) then best_buy={price=price,shop=ref.shop and ref.shop.num,owner=ref.shop and ref.shop.owner} end
            end
        end
        out[#out+1]={pawn=p,best_shop_sell=best_sell,best_shop_buy=best_buy,
            diff_from_shop_sell=best_sell and (p.price-best_sell.price) or nil,
            diff_to_shop_buy=best_buy and (best_buy.price-p.price) or nil}
    end
    return out
end
function L.flush()
    if not L._dirty then return true end
    local ok,json=pcall(encodeJson,L.data);if not ok or type(json)~='string' then return false,'encode' end
    local tmp=L.path..'.tmp';local f=io.open(tmp,'wb');if not f then return false,'open' end
    local a,b=f:write(json),f:close();if not a or not b then return false,'write' end
    local r,e=os.rename(tmp,L.path);if not r then return false,e end
    L._dirty=false;return true
end
function L.load()
    local f=io.open(L.path,'rb');if not f then return false end
    local raw=f:read('*a') or '';f:close();local ok,d=pcall(decodeJson,raw)
    if ok and type(d)=='table' and type(d.servers)=='table' then L.data=d;L.data.schema=L.schema;return true end
    return false
end
function L.command(param)
    param=clean(param or '')
    local st=L.stats()
    if param=='' then
        if DSP.notify then DSP.notify(('Lombard: items=%d pages=%d history=%d scans=%d'):format(st.items,st.pages,st.history_items,st.scans)) end
        return
    end
    local rows=L.search(param);if DSP.notify then DSP.notify('Lombard search "'..param..'": '..#rows) end
    for i=1,math.min(#rows,5) do local r=rows[i];if DSP.notify then DSP.notify((r.side or 'quote')..' '..r.name..' '..DSP.money(r.price)) end end
end
-- Store only an explicitly reviewed native observation, not an automatic trade.
function L.save_observation(rows,source)
    if type(rows)~='table' or #rows==0 or #rows>180 then return false,'no rows' end
    local session=new_session(-1,'Lombard native observation')
    session.page_count=1
    for _,item in ipairs(rows) do
        if type(item)=='table' and type(item.name)=='string'
            and tonumber(item.price) and tonumber(item.price)>0 then
            local key=tostring(item.key or item.name..':'..item.price)
            if not session.items[key] then
                session.items[key]=item
                session.order[#session.order+1]=key
            end
        end
    end
    if #session.order==0 then return false,'no recognized items' end
    return commit_session(session,source or 'packet_unverified')
end
function L.start_auto()
    if not sampIsDialogActive or not sampIsDialogActive() then
        if L.packet_probe and L.packet_probe.arm then
            L.packet_probe.arm(35)
            if DSP.notify then DSP.notify('Lombard: listening for native pawnshop menu (35 sec)')end
            return true
        end
        return false
    end
    local id=sampGetCurrentDialogId and sampGetCurrentDialogId() or -1
    local title=sampGetDialogTitle and sampGetDialogTitle() or ''
    local text=sampGetDialogText and sampGetDialogText() or ''
    if not L.is_dialog(title,text) then if DSP.notify then DSP.notify('Lombard: current dialog not recognized') end;return false end
    L.session=nil;L.auto_scan=true;L.observe_dialog(id,0,title,'','',text);schedule_next(id,text)
    if DSP.notify then DSP.notify('Lombard auto scan started') end;return true
end
function L.install()
    if L._installed then return end;L._installed=true
    pcall(L.load)
    if sampRegisterChatCommand then
        pcall(sampRegisterChatCommand,'crrlombard',L.command)
        pcall(sampRegisterChatCommand,'crrlombardscan',function() L.start_auto() end)
        pcall(sampRegisterChatCommand,'crrlombardui',function()
            if DSP.ui21 and DSP.ui21.set_screen then DSP.ui21.set_screen('lombard') end
        end)
    end
    local ok,sampev=pcall(require,'samp.events')
    if ok and sampev then
        local prev=sampev.onShowDialog
        sampev.onShowDialog=function(id,style,title,b1,b2,text)
            local seen=false;local good,ret=pcall(L.observe_dialog,id,style,title,b1,b2,text);if good then seen=ret end
            if seen then schedule_next(id,text) end
            if prev then return prev(id,style,title,b1,b2,text) end
        end
    end
    if lua_thread and lua_thread.create and wait then
        lua_thread.create(function() while true do wait(2500);if L._dirty then pcall(L.flush) end end end)
    end
end
return true
end
__mod_46c_lombard()

local function __mod_46d_lombard_packets()
-- Passive native pawnshop menu inspection. The packet layout is NOT
-- verified against a real pawnshop dump; all entries are observational only.
local L=DSP.lombard
if not L then return false end
local P={active=false,status='idle',until_ts=0,packets=0,tagged=0,
    ignored=0,candidates={},items={},order={},verified_label=false}
L.packet_probe=P
local MAX_BYTES,MAX_ROWS,MAX_CANDIDATES=100000,180,12
local function int(v,cap)
    local n=tonumber(v)
    if n and n==n and n>=0 and n<=cap and n%1==0 then return n end
end
local function lower(s)
    s=tostring(s or '')
    return DSP.lower and DSP.lower(s) or s:lower()
end
local function pawn_text(s)
    s=lower(s)
    return s:find('\xeb\xee\xec\xe1\xe0\xf0\xe4',1,true)~=nil
        or s:find('\208\187\208\190\208\188\208\177\208\176\209\128\208\180',1,true)~=nil
        or s:find('pawnshop',1,true)~=nil or s:find('pawn',1,true)~=nil
end
function P.arm(seconds)
    local duration=int(seconds or 35,60) or 35
    if duration<5 then duration=35 end
    P.active=true;P.status='listening';P.until_ts=os.time()+duration
    P.packets=0;P.tagged=0;P.ignored=0;P.candidates={};P.items={};P.order={}
    P.verified_label=false
    return true
end
function P.stop()
    P.active=false;P.status='review';return true
end
function P.state()
    if P.active and os.time()>P.until_ts then P.stop() end
    return P
end
local function has_known_game_name(item)
    return type(item)=='table' and type(item.name)=='string' and item.name~=''
end
local function recognize(item,index,tag)
    if type(item)~='table' then return nil end
    local explicit_price=int(item.price or item.cost or item.unit_price or item.unitPrice,9007199254740991)
    if not explicit_price or explicit_price<1 then return nil end
    local row
    if DSP.item_registry and DSP.item_registry.from_node then
        local ok,value=pcall(DSP.item_registry.from_node,item,'buy',index)
        if ok and value then row=value end
    end
    if not row and has_known_game_name(item) and L.parse_dialog then
        local lines=L.parse_dialog(tag or '',item.name..'\t'..tostring(explicit_price))
        row=lines[1]
    end
    if not row then return nil end
    row.side='buy'
    row.price=explicit_price
    return row
end
local function nodes(obj)
    if type(obj)~='table' then return nil end
    if type(obj.items)=='table' then return obj.items end
    if type(obj.rows)=='table' then return obj.rows end
    if type(obj.data)=='table' then
        if type(obj.data.items)=='table' then return obj.data.items end
        if type(obj.data.rows)=='table' then return obj.data.rows end
    end
end
function L.on_packet(iface,sub,raw)
    local active=P.state().active
    if type(raw)~='string' or #raw<2 or #raw>MAX_BYTES then return false end
    -- A labeled pawnshop packet may be observed passively. Unknown packet
    -- layouts are explored only during the explicit 35-second scan window.
    if not active and not pawn_text(raw) then return false end
    local ok,obj=pcall(decodeJson,raw:gsub('%z+$',''))
    if not ok or type(obj)~='table' then return false end
    local packet_type=int(obj.type,255)
    if packet_type==8 or packet_type==13 or packet_type==28 or
        (packet_type==1 and tonumber(sub)==2) or tonumber(iface)==57 then
        P.ignored=P.ignored+1;return false
    end
    local label=tostring(obj.title or obj.header or obj.caption or obj.name or
        (type(obj.data)=='table' and obj.data.title) or '')
    local labeled=pawn_text(label)
    if not active and not labeled then return false end
    local slot_list=nodes(obj)
    if not slot_list then
        if active then
            P.packets=P.packets+1
            if #P.candidates<MAX_CANDIDATES then
                P.candidates[#P.candidates+1]={iface=tonumber(iface),sub=tonumber(sub),
                    type=packet_type,rows=0,label=labeled}
            end
        end
        return false
    end
    if #slot_list>MAX_ROWS then return false end
    P.packets=P.packets+1
    if labeled then P.tagged=P.tagged+1;P.verified_label=true end
    local accepted=0
    for i,item in ipairs(slot_list)do
        local row=recognize(item,i,label)
        if row then
            local key=tostring(row.key or row.name)..':'..tostring(row.price)
            if not P.items[key] then P.order[#P.order+1]=key end
            P.items[key]=row;accepted=accepted+1
        end
    end
    if #P.candidates<MAX_CANDIDATES then
        P.candidates[#P.candidates+1]={iface=tonumber(iface),sub=tonumber(sub),
            type=packet_type,rows=accepted,label=labeled}
    end
    -- Never write any native observation automatically: the server has not
    -- supplied a proven end-of-list marker or stable pawnshop session ID.
    if accepted>0 then P.status='preview_ready' end
    return accepted>0
end
function P.preview()
    local rows={}
    for _,key in ipairs(P.order)do
        local row=P.items[key]
        if row then rows[#rows+1]=row end
    end
    return rows
end
function P.save()
    if P.state().active then return false,'stop the scan first' end
    local rows=P.preview()
    if #rows==0 then return false,'no recognized priced items' end
    if not L.save_observation then return false,'pawnshop store unavailable' end
    local ok,result=L.save_observation(rows,'packet_unverified')
    if ok then P.status='saved_unverified' end
    return ok,result
end
function P.report()
    -- Metadata only; never include names, IDs, raw JSON or account data.
    local candidates={}
    for _,c in ipairs(P.candidates)do
        candidates[#candidates+1]={iface=c.iface,sub=c.sub,
            type=c.type,rows=c.rows,labeled=c.label}
    end
    return {schema=1,packets=P.packets,tagged=P.tagged,ignored=P.ignored,
        candidates=candidates}
end
return true

end
__mod_46d_lombard_packets()

local function __mod_47_shop_marker()
-- Local world-anchored stall label. Coordinates come from server markers/labels.
DSP.shop_marker={cache={}}
local M=DSP.shop_marker
if DSP.settings.marker_3d_enabled==nil then DSP.settings.marker_3d_enabled=true end
local function valid_number(n)
    local text=tostring(n or '')
    return text:match('^%d+$') and tonumber(text)>0 and tonumber(text)<=99999 and text or nil
end
local function coordinate(p)
    if not p then return nil end
    local x,y,z=tonumber(p.x),tonumber(p.y),tonumber(p.z)
    for _,v in ipairs({x or math.huge,y or math.huge,z or math.huge})do
        if v~=v or math.abs(v)>100000 then return nil end
    end
    return{x=x,y=y,z=z}
end
function M.set_enabled(value)
    DSP.settings.marker_3d_enabled=value==true
    if DSP.mobile.defer_save then DSP.mobile.defer_save()end
end
function M.clear()M.target=nil end
function M.active()
    if M.target and M.target.sid~=DSP.market.state.sid then M.target=nil;M.cache={} end
    return DSP.settings.marker_3d_enabled and M.target and M.target.position and true or false
end
function M.observe_label(id,color,position,distance,test_los,player,vehicle,text)
    local clean=DSP.clean_text(tostring(text or ''))
    if not DSP.lower(clean):find(DSP.lower('лавк'),1,true)then return end
    local num=valid_number(clean:match('#%s*(%d+)')or clean:match('№%s*(%d+)'))
    local p=coordinate(position)
    if not num or not p then return end
    p.source='label';p.sid=DSP.market.state.sid
    M.cache[num]=p
    if M.target and M.target.num==num and M.target.sid==p.sid then M.target.position=p end
end
function M.observe_checkpoint(position)
    local t=M.target
    if not t or t.sid~=DSP.market.state.sid or os.time()>(t.pending_until or 0)then return end
    -- /findilavka is not the only producer of onSetCheckpoint. SA-MP does not
    -- attach a stall number to this event, so even the first checkpoint after
    -- the command may belong to a mission or another script. Remember it only
    -- for diagnostics; it is NOT a verified world position of this stall.
    local p=coordinate(position)
    if p then t.unverified_checkpoint=p end
end
function M.status()
    if not DSP.settings.marker_3d_enabled then return '3D: выключена' end
    local t=M.target
    if not t or t.sid~=DSP.market.state.sid then return '3D: лавка не выбрана' end
    if t.position then return '3D: лавка #'..t.num..' · точная подпись' end
    if os.time()<=(t.pending_until or 0) then
        return '3D: ищем подпись лавки #'..t.num..' (GPS не подтверждён)'
    end
    return '3D: координаты лавки #'..t.num..' не подтверждены'
end
local function find_streamed_labels(num)
    if not lua_thread or not wait or not sampIs3dTextDefined or not sampGet3dTextInfoById then return end
    local target=M.target
    lua_thread.create(function()
        for id=0,2047 do
            if M.target~=target or target.num~=num then return end
            if sampIs3dTextDefined(id)then
                local ok,text,color,x,y,z=pcall(sampGet3dTextInfoById,id)
                if ok then M.observe_label(id,color,{x=x,y=y,z=z},0,false,0,0,text)end
            end
            if id%32==31 then wait(25)end
        end
    end)
end
function M.project(projector,p,sw,sh)
    local ok,visible,x,y,depth=pcall(projector,p.x,p.y,p.z+1)
    if not ok or visible==false or type(x)~='number'or type(y)~='number'then return nil end
    if x~=x or y~=y or (depth and depth<=0)or x<0 or x>sw or y<0 or y>sh then return nil end
    return{x=x,y=y}
end
function M.draw()
    if not M.active()or not convert3DCoordsToScreenEx then return end
    local io=imgui.GetIO();local t=M.target
    local p=M.project(convert3DCoordsToScreenEx,t.position,io.DisplaySize.x,io.DisplaySize.y)
    if not p then return end
    local label='Лавка #'..t.num
    if getCharCoordinates and PLAYER_PED then
        local x,y,z=getCharCoordinates(PLAYER_PED)
        local d=math.sqrt((x-t.position.x)^2+(y-t.position.y)^2+(z-t.position.z)^2)
        label=label..' · '..math.floor(d)..' м'
    end
    label=DSP.utf8(label)
    local size=imgui.CalcTextSize(label);local dl=imgui.GetForegroundDrawList()
    local x,y=p.x-size.x/2,p.y-size.y-22
    dl:AddRectFilled(imgui.ImVec2(x-10,y-6),imgui.ImVec2(x+size.x+10,y+size.y+6),0xee201810,6)
    dl:AddText(imgui.ImVec2(x,y),0xffffffff,label,nil)
    dl:AddCircleFilled(imgui.ImVec2(p.x,p.y),5,0xffffb45c,12)
end
function M.install()
    if M.installed then return end;M.installed=true
    local original=DSP.market.mark_shop
    DSP.market.mark_shop=function(num)
        num=valid_number(num);if not num then return false end
        local old=M.target
        local p=M.cache[num]
        M.target={num=num,sid=DSP.market.state.sid,pending_until=os.time()+12,
            position=p and p.sid==DSP.market.state.sid and p or nil}
        local ok=original(num)
        if not ok then M.target=old;return false end
        find_streamed_labels(num)
        return true
    end
    local ok,events=pcall(require,'samp.events')
    if ok and events then
        local prev_cp,prev_label=events.onSetCheckpoint,events.onCreate3DText
        events.onSetCheckpoint=function(position,size)
            M.observe_checkpoint(position)
            if prev_cp then return prev_cp(position,size)end
        end
        events.onCreate3DText=function(id,color,pos,dist,los,player,vehicle,text)
            M.observe_label(id,color,pos,dist,los,player,vehicle,text)
            if prev_label then return prev_label(id,color,pos,dist,los,player,vehicle,text)end
        end
    end
    if imgui and imgui.OnFrame then imgui.OnFrame(M.active,function()
        local good,err=xpcall(M.draw,debug.traceback)
        if not good and M.error~=err then M.error=err;DSP.flog('3D marker: '..tostring(err))end
    end)end
end

end
__mod_47_shop_marker()

local function __mod_47_storage()
-- Read-only inventory analysis for classic SA-MP cabinet/trunk dialogs.
-- Does not issue game commands, move items, infer missing counts or inspect memory.
DSP.storage = DSP.storage or {}
local S = DSP.storage
S.snapshots = S.snapshots or (DSP.settings and DSP.settings.storage_snapshots) or {}
S.last_error = nil
S.max_rows = 180
S.max_saved = 20

local function normal(s)
    s = DSP.clean_text(tostring(s or ''))
    return s:gsub('\t',' '):gsub(' +',' ')
end
local function int(s)
    if not s then return nil end
    s=tostring(s):gsub('[%s%.%,]','')
    if not s:match('^%d+$') then return nil end
    local n=tonumber(s)
    if not n or n<1 or n>2000000000 or n%1~=0 then return nil end
    return n
end
local function kind_of(title)
    local s=DSP.lower(normal(title))
    if s:find('инвентарь',1,true) or s:find('Инвентарь',1,true) then return 'inventory' end
    if s:find('багажник',1,true) or s:find('Багажник',1,true) then return 'trunk' end
    if s:find('шкаф',1,true) or s:find('Шкаф',1,true) then return 'cabinet' end
    if s:find('склад',1,true) or s:find('Склад',1,true) or s:find('хранилище',1,true) or s:find('Хранилище',1,true) then return 'warehouse' end
    return nil
end
S.kind_of = kind_of
function S.parse_line(raw)
    local s=normal(raw)
    -- Strip only UI list position, not arbitrary numeric prefixes or item IDs.
    s=s:gsub('^%s*%d+[%.%)]%s+','')
    if s=='' or #s>320 then return nil end
    local name,qty
    -- An explicit unit is mandatory: 'slot #1' is NOT one item.
    name,qty=s:match('^(.-)%s*%(%s*([%d%., ]+)%s*шт%.?%s*%)%s*$')
    if not name then name,qty=s:match('^(.-)%s*%[%s*([%d%., ]+)%s*шт%.?%s*%]%s*$') end
    if not name then name,qty=s:match('^(.-)%s*[%-%—:]%s*([%d%., ]+)%s*шт%.?%s*$')end
    if not name then name,qty=s:match('^(.-)%s+[xхXХ]%s*([%d%., ]+)%s*$')end
    if not name then name,qty=s:match('^(.-)%s*%([xхXХ]%s*([%d%., ]+)%)%s*$')end
    if not name then
        -- Legitimate unlabeled line: show unknown count, never silently x1.
        if s:find('%$',1,true) or s:find('Выберите',1,true) or s:find('Назад',1,true)
            or DSP.lower(s):find('вместимость',1,true) or s:match('^[-=]+$')
            or s:find('Открыть',1,true) or s:find('Закрыть',1,true)
            or s:find('Забрать',1,true) or s:find('Положить',1,true) then return nil end
        name=s
    end
    name=DSP.trim(name or '')
    if name=='' or #name>125 then return nil end
    if name:match('^%d+$') then return nil end
    local count=int(qty)
    -- Explicitly malformed quantities are not accepted as reliable numeric values.
    return {name=name,qty=count,quantity_confirmed=count~=nil,raw=raw}
end
function S.parse_text(kind,title,text,ts)
    if not S.kind_of(title) or S.kind_of(title)~=kind then return nil,'not a container dialog' end
    if type(text)~='string' then return nil,'not text' end
    local rows,by_name={},{}
    for line in (text..'\n'):gmatch('(.-)\r?\n')do
        if #rows>=S.max_rows then break end
        local r=S.parse_line(line)
        if r then
            local key=DSP.item_key(r.name,0)
            if not by_name[key] then
                rows[#rows+1]=r;by_name[key]=r
            else
                -- Repeated view of the same item in one dialog is ambiguous;
                -- keep separate slots, never fabricate an aggregate count.
                rows[#rows+1]=r
            end
        end
    end
    if #rows==0 then return nil,'no item lines' end
    return {kind=kind,title=normal(title),rows=rows,observed_at=ts or os.time(),
        source='dialog',count_known=0}
end
function S.accept(kind,title,text,ts,source)
    local snap,err=S.parse_text(kind,title,text,ts)
    if not snap then S.last_error=err;return false,err end
    snap.source=source=='manual' and 'manual' or source=='textdraw' and 'textdraw' or 'dialog'
    for _,r in ipairs(snap.rows)do
        if r.qty then snap.count_known=snap.count_known+r.qty end
    end
    local signature=kind..'|'..snap.source..'|'..snap.title..'|'..text
    if S.last_signature==signature and S.last_snapshot and math.abs((ts or os.time())-(S.last_ts or 0))<=3 then
        -- Repeated same dialog callback does not add slots or duplicate snapshots.
        return true,S.last_snapshot
    end
    snap.id=tostring(ts or os.time())..'_'..tostring(#S.snapshots+1)
    snap.server=DSP.market and DSP.market.state and DSP.market.state.sid or nil
    table.insert(S.snapshots,1,snap)
    while #S.snapshots>S.max_saved+1 do table.remove(S.snapshots)end
    S.last_signature=signature;S.last_snapshot=snap;S.last_ts=ts or os.time();S.last_error=nil
    if DSP.settings and DSP.save_settings then
        DSP.settings.storage_snapshots=S.snapshots
        local ok,err=DSP.save_settings()
        if not ok then S.last_error='Не удалось сохранить снимок: '..tostring(err) end
    end
    return true,snap
end
function S.on_dialog(id,style,title,text)
    local kind=kind_of(title)
    if not kind then return false end
    local ok,err=S.accept(kind,title,text)
    if ok then DSP.flog('STORAGE read-only '..kind..' rows='..#S.snapshots[1].rows..' dialog='..tostring(id))
    else DSP.flog('STORAGE unavailable '..tostring(err))end
    return ok
end
local function market_lookup(name,ench)
    local row=DSP.market and DSP.market.row_for and DSP.market.row_for(name,ench or 0)
    if not row then return nil,nil end
    local buy=row.buy and tonumber(row.buy.max)
    local sell=row.sell and tonumber(row.sell.min)
    if buy and buy<=0 then buy=nil end
    if sell and sell<=0 then sell=nil end
    return buy,sell
end
S.market_lookup=market_lookup
function S.item_group_key(row)
    if tonumber(row.id) and tonumber(row.id)>0 then
        return 'id:'..tostring(math.floor(tonumber(row.id)))..':'..tostring(tonumber(row.ench) or 0)
    end
    return 'name:'..DSP.item_key(row.name or '',tonumber(row.ench) or 0)
end
function S.set_manual_price(snapshot, row, amount)
    local n=tonumber(amount)
    if not n or n~=n or n<0 or n>9007199254740991 or n%1~=0 then return false,'invalid price' end
    local found=false
    for _,s in ipairs(S.snapshots or{}) do if s==snapshot then found=true;break end end
    if not found then return false,'stale snapshot' end
    local key=S.item_group_key(row)
    snapshot.manual_prices=snapshot.manual_prices or {}
    local previous=snapshot.manual_prices[key]
    local sid=tostring(snapshot.server or (DSP.market and DSP.market.state and DSP.market.state.sid) or 0)
    DSP.settings.storage_prices=DSP.settings.storage_prices or {}
    DSP.settings.storage_prices[sid]=DSP.settings.storage_prices[sid] or {}
    local global=DSP.settings.storage_prices[sid]
    local old_global=global[key]
    global[key]=n>0 and n or nil
    snapshot.manual_prices[key]=n>0 and n or nil
    if DSP.settings then DSP.settings.storage_snapshots=S.snapshots end
    if DSP.save_settings then
        local called,ok,err=pcall(DSP.save_settings)
        if not called or not ok then
            snapshot.manual_prices[key]=previous
            global[key]=old_global
            return false,tostring(err or ok or 'save error')
        end
    end
    S.sort_cache=setmetatable({},{__mode='k'})
    return true
end
function S.set_snapshot_label(snapshot,label)
    if type(label)~='string' then return false,'invalid label' end
    label=DSP.trim(DSP.clean_text(label))
    if #label>66 or label=='' then return false,'name must be 1-66 bytes' end
    -- Live scans are deliberately NOT in S.snapshots. Allow naming only the
    -- current live result; stale objects from previous scans are rejected.
    if snapshot.source=='packet220_trunk' and S.trunk and S.trunk.snapshot==snapshot then
        return S.save_named_trunk(snapshot,label)
    end
    local found=false
    for _,saved in ipairs(S.snapshots or{})do if saved==snapshot then found=true;break end end
    if not found then return false,'stale snapshot' end
    -- The live trunk is disposable by design. Renaming it must create a
    -- persistent library entry, otherwise the next scan would erase the name.
    if snapshot.source=='packet220_trunk' then
        if not S.save_named_trunk then return false,'archive function unavailable' end
        return S.save_named_trunk(snapshot,label)
    end
    local previous=snapshot.title
    snapshot.title=label
    if DSP.settings then DSP.settings.storage_snapshots=S.snapshots end
    if DSP.save_settings then
        local called,ok,err=pcall(DSP.save_settings)
        if not called or not ok then snapshot.title=previous;return false,tostring(err or ok or 'save error')end
    end
    return true,snapshot
end
function S.evaluate(snapshot,lookup)
    lookup=lookup or market_lookup
    local res={total_qty=0,known_qty_rows=0,unknown_qty=0,missing_prices=0,
        sell_to_buyers=0,ask_value=0,estimated_rows=0,rows={},cross_server=false}
    local current=DSP.market and DSP.market.state and DSP.market.state.sid
    local wrong_server=snapshot and snapshot.server and current and tonumber(snapshot.server)~=tonumber(current)
    res.cross_server=not not wrong_server
    local by_key={}
    for i,src in ipairs(snapshot and snapshot.rows or{})do
        local key=S.item_group_key(src)
        local row=by_key[key]
        if not row then
            row={key=key,name=src.name,ench=src.ench or 0,id=src.id,qty=0,
                bid=nil,ask=nil,index=i,slots=0,unknown_slots=0}
            by_key[key]=row;res.rows[#res.rows+1]=row
            if not wrong_server then row.bid,row.ask=lookup(src.name,src.ench or 0) end
            local prices=DSP.settings and DSP.settings.storage_prices
            local server=tostring(snapshot.server or (DSP.market and DSP.market.state and DSP.market.state.sid) or 0)
            local shared=prices and prices[server]
            local manual=(snapshot.manual_prices and snapshot.manual_prices[key]) or (shared and shared[key])
            if manual and tonumber(manual) and tonumber(manual)>0 then
                row.bid=tonumber(manual);row.manual_price=true
            end
        end
        row.slots=row.slots+1
        if src.qty then
            row.qty=row.qty+src.qty
            res.total_qty=res.total_qty+src.qty
            res.known_qty_rows=res.known_qty_rows+1
            if row.bid then res.sell_to_buyers=res.sell_to_buyers+row.bid*src.qty;res.estimated_rows=res.estimated_rows+1
            else res.missing_prices=res.missing_prices+1 end
            if row.ask then res.ask_value=res.ask_value+row.ask*src.qty end
        else
            row.unknown_slots=row.unknown_slots+1
            res.unknown_qty=res.unknown_qty+1
        end
    end
    for _,row in ipairs(res.rows) do if row.unknown_slots>0 and row.qty==0 then row.qty=nil end end
    return res
end

S.sort_cache=setmetatable({},{__mode='k'})
function S.sorted(snapshot,mode,lookup)
    if not lookup and snapshot then
        local st=DSP.market and DSP.market.state or {}
        local key=tostring(mode)..'/'..tostring(st.sid)..'/'..tostring(st.version)
        local entry=S.sort_cache[snapshot]
        if entry and entry.key==key then return entry.rows,entry.info end
    end
    local info=S.evaluate(snapshot,lookup)
    local sorted=info.rows
    table.sort(sorted,function(a,b)
        if mode=='category' then
            local function cat(n)
                n=DSP.lower(tostring(n or ''))
                if n:find('дров',1,true) or n:find('металл',1,true) or n:find('камень',1,true)
                    or n:find('лен',1,true) or n:find('хлоп',1,true) then return 1 end
                if n:find('ларец',1,true) or n:find('кейс',1,true) then return 2 end
                if n:find('деталь тюнинга',1,true) then return 3 end
                return 4
            end
            if cat(a.name)~=cat(b.name)then return cat(a.name)<cat(b.name)end
        elseif mode=='qty' then
            if (a.qty or -1)~=(b.qty or -1)then return(a.qty or -1)>(b.qty or -1)end
        elseif mode=='value' then
            local av=a.bid and a.qty and a.bid*a.qty or -1
            local bv=b.bid and b.qty and b.bid*b.qty or -1
            if av~=bv then return av>bv end
        elseif mode=='price' then
            if (a.bid or -1)~=(b.bid or -1)then return(a.bid or -1)>(b.bid or -1)end
        end
        return tostring(a.name)<tostring(b.name)
    end)
    if not lookup and snapshot then
        local st=DSP.market and DSP.market.state or {}
        S.sort_cache[snapshot]={key=tostring(mode)..'/'..tostring(st.sid)..'/'..tostring(st.version),rows=sorted,info=info}
    end
    return sorted,info
end

-- Palatka AI v2.2.13 / Packet220 inventory trunk only (type=8).
-- Runs within __mod_47_storage, after the original storage/sorting functions.
-- No packet injection, commands, memory hooks or automatic inventory actions.
S.trunk = S.trunk or {status='idle', received=0, last_error=nil}
local T = S.trunk
local TRUNK_TYPE, TRUNK_SLOTS = 8, 180
local VALID_CAPACITY = {[30]=true,[60]=true,[90]=true,[120]=true,[150]=true,[180]=true}
local PENDING_TIMEOUT = 15       -- seconds to receive the 180-slot full snapshot
-- Partial slot changes are intentionally not applied without vehicle identity.

local function valid_slot(v)
    local n = tonumber(v)
    if n and n % 1 == 0 and n >= 0 and n < TRUNK_SLOTS then return n end
    return nil
end

local function valid_count(v)
    local n = tonumber(v)
    if n and n == n and n >= 0 and n <= 2000000000 and n % 1 == 0 then return n end
    return nil
end

local function sanitized_slot(it)
    if type(it) ~= 'table' then return nil end
    local slot = valid_slot(it.slot)
    if slot == nil then return nil end
    local id = it.item == nil and 0 or tonumber(it.item)
    if not id or id ~= id or id < 0 or id > 2000000000 or id % 1 ~= 0 then return nil end
    local amount = id > 0 and valid_count(it.amount) or 0
    return {slot=slot,item_id=id,qty=amount,
        ench=tonumber(it.enchant) or 0,empty=(id == 0)}
end

local function parse_payload(raw)
    if type(raw) ~= 'string' or #raw == 0 or #raw > 100000 then return nil end
    -- StringCompressor occasionally returns an extra trailing NUL byte.
    raw = raw:gsub('%z+$','')
    local ok, obj = pcall(decodeJson, raw)
    if not ok or type(obj) ~= 'table' or tonumber(obj.type) ~= TRUNK_TYPE
        or type(obj.items) ~= 'table' or #obj.items > TRUNK_SLOTS then return nil end
    local normalized, used = {}, {}
    for _, item in ipairs(obj.items) do
        local sl = sanitized_slot(item)
        if not sl or used[sl.slot] then return nil end
        used[sl.slot] = true
        normalized[#normalized+1] = sl
    end
    local capacity=tonumber(obj.capacity or obj.slotCount or obj.totalSlots)
    if not VALID_CAPACITY[capacity] then capacity=nil end
    return normalized,capacity
end

local function active_snapshot()
    for _, s in ipairs(S.snapshots or {}) do
        if s.source == 'packet220_trunk' and s.kind == 'trunk' then return s end
    end
    return nil
end

local function build_rows(slots, capacity)
    local rows, count, occupied = {}, 0, 0
    for i=0,(capacity or TRUNK_SLOTS)-1 do
        local v = slots[i+1]
        if v and v.item_id and v.item_id > 0 then
            local name = DSP.items and DSP.items.name and DSP.items.name(v.item_id)
                or ('ID:'..tostring(v.item_id))
            if type(name) ~= 'string' or name == '' then name='ID:'..tostring(v.item_id) end
            rows[#rows+1] = {
                slot=i,id=v.item_id,name=name,ench=v.ench or 0,
                qty=v.qty,quantity_confirmed=v.qty ~= nil,
            }
            occupied=occupied+1
            if v.qty then count=count+v.qty end
        end
    end
    return rows,count,occupied
end

local function save_snapshot(slots, source_reason, capacity)
    local ts=os.time()
    capacity=capacity or TRUNK_SLOTS
    local rows, total, occupied = build_rows(slots,capacity)
    local requested_at=T.requested_at
    local update_target_id=T.update_target_id
    local snap={
        id='trunk_live_'..tostring(ts)..'_'..tostring((T.scan_generation or 0)+1),
        kind='trunk',
        -- No persistent vehicle identity in observed packet. This is ALWAYS the last opened trunk.
        title='Последний открытый багажник',
        source='packet220_trunk', identity_verified=false,
        observed_at=ts, updated_at=ts, server=DSP.market and DSP.market.state and DSP.market.state.sid or nil,
        slots_count=capacity, occupied_slots=occupied,count_known=total,
        rows=rows, slots=slots, update_kind=source_reason,
    }
    -- A scan is IN MEMORY ONLY. A user-named copy is the sole path to the
    -- persistent library. Never write an unnamed scan to storage_snapshots.
    T.snapshot=snap
    T.last_update=ts
    T.status='saved'
    T.received=capacity
    T.occupied=occupied
    T.total=total
    T.last_saved_at=ts
    if requested_at then
        T.last_completed_request_at=ts
        T.requested_at=nil
        T.completed_update_target_id=update_target_id
        T.update_target_id=nil
    end
    T.last_error=nil
    T.last_warning=nil
    T.scan_generation=(T.scan_generation or 0)+1
    T.review_generation=T.scan_generation
    T.review_needed=true
    if DSP.flog then DSP.flog('TRUNK '..source_reason..' slots='..capacity..' occupied='..occupied..' count='..total) end
    return true
end

-- No vehicle/container ID is exposed by the observed packets. A partial
-- update could belong to an entirely different trunk. Never merge it into
-- a previously saved snapshot without a verified identity.

-- Only handles JSON with type=8; never processes other inventory blocks (market/player/etc).
function S.on_inventory_packet(sub, raw)
    -- Real trunk full snapshots use subid=0. subid=2 carries a separate slot
    -- namespace for other inventory blocks; never merge it with trunk slots.
    if tonumber(sub)~=0 then return false end
    T.raw_packet_events=(T.raw_packet_events or 0)+1
    T.last_raw_packet_at=os.time()
    if not (T.autoscan_enabled or T.requested_at) then return false end
    local items,declared_capacity=parse_payload(raw)
    if not items or #items == 0 then
        T.invalid_packet_events=(T.invalid_packet_events or 0)+1
        T.last_error='type 8 received; payload could not be decoded'
        return false
    end
    local ts=os.time()
    -- Observed incoming payload; do not claim the trunk window is open.
    T.packet_events=(T.packet_events or 0)+1
    T.last_packet_at=ts
    if T.pending and (ts-T.pending.started)>PENDING_TIMEOUT then
        T.pending=nil;T.status='incomplete';T.last_error='Incomplete 180-slot batch timed out'
    end
    -- A trunk may arrive in chunks whose first chunk is not slot 0.
    -- type=8 is already the confirmed trunk namespace; large batches start a
    -- fresh capture, while tiny <=5 slot deltas remain ignored.
    local starts_capture=(not T.pending and #items>5)
    local explicit_restart=(T.pending and #items>5 and items[1] and items[1].slot==0 and T.pending.seen[0])
    local stale_restart=(T.pending and #items>5 and T.pending.last_at and (ts-T.pending.last_at)>3)
    if starts_capture or explicit_restart or stale_restart then
        T.pending={slots={},seen={},count=0,started=ts,last_at=ts,
            capacity=declared_capacity or T.selected_capacity or TRUNK_SLOTS}
        T.status='receiving';T.received=0;T.last_error=nil
    end
    if T.pending then
        local p=T.pending
        p.last_at=ts
        if declared_capacity then p.capacity=declared_capacity end
        -- Never finalize a user-selected 30-slot scan if the packet explicitly
        -- includes slots outside its capacity: the observed layout is larger.
        for _,v in ipairs(items) do
            if v.slot>=p.capacity then
                p.capacity=TRUNK_SLOTS
            end
        end
        for _,v in ipairs(items) do
            if not p.seen[v.slot] then p.seen[v.slot]=true;p.count=p.count+1 end
            p.slots[v.slot+1]=v
        end
        T.received=p.count
        if p.count>=p.capacity then
            -- Full means all expected slots in THIS layout were seen. If the
            -- server does not declare capacity, the player explicitly chooses
            -- their car's capacity (30/180), not automatic guessing.
            local complete=true
            for i=1,p.capacity do if not p.slots[i] then complete=false;break end end
            if complete then
                T.pending=nil
                save_snapshot(p.slots,'full',p.capacity)
            end
        end
        return true
    end
    -- If the user started a new scan while the trunk was already open,
    -- the game usually sends only tiny slot deltas when an item moves. Those
    -- deltas are not a full second trunk and must never replace the old scan.
    if #items<=5 then
        if T.requested_at then
            T.saw_delta_after_request=true
            T.status='need_reopen'
            T.last_error='Полный снимок не пришёл. Закрой багажник и открой его заново.'
        elseif T.snapshot then
            -- Do not hide a previously valid full scan just because a single
            -- slot changed while the player was inside the trunk.
            T.last_warning='Изменение отдельных слотов не применено. Для новых данных открой багажник заново.'
        end
        return false
    end
    T.status=T.requested_at and 'need_reopen' or 'unknown_partial'
    if T.requested_at then
        T.last_error='Получена только часть. Закрой багажник и открой заново.'
    end
    return false
end

-- Load the most recently persisted trunk as read-only history after restart.
-- Old versions may have stored a nameless live scan. Do not resurrect it
-- in the new unsaved session; named library entries remain untouched.
T.snapshot=nil
T.autoscan_enabled=not (DSP.settings and DSP.settings.storage_trunk_autoscan==false)
T.selected_capacity=VALID_CAPACITY[tonumber(DSP.settings and DSP.settings.storage_trunk_capacity)]
    and tonumber(DSP.settings.storage_trunk_capacity) or 180

function S.set_trunk_capacity(cap)
    cap=tonumber(cap)
    if not VALID_CAPACITY[cap] then return false,'Недопустимая вместимость' end
    if T.requested_at then return false,'Сначала останови текущий скан' end
    local previous=T.selected_capacity
    T.selected_capacity=cap
    if DSP.settings then DSP.settings.storage_trunk_capacity=cap end
    if DSP.save_settings then
        local ok,saved,err=pcall(DSP.save_settings)
        if not ok or not saved then
            T.selected_capacity=previous
            if DSP.settings then DSP.settings.storage_trunk_capacity=previous end
            return false,tostring(err or saved or 'Ошибка сохранения')
        end
    end
    return true
end

-- The normal UI uses these methods; no additional game commands are needed.
function S.set_trunk_autoscan(enabled)
    local value=not not enabled
    local prior=T.autoscan_enabled
    T.autoscan_enabled=value
    if DSP.settings then DSP.settings.storage_trunk_autoscan=value end
    if DSP.save_settings then
        local ok,saved,err=pcall(DSP.save_settings)
        if not ok or not saved then
            T.autoscan_enabled=prior
            if DSP.settings then DSP.settings.storage_trunk_autoscan=prior end
            return false,tostring(err or saved or 'save failed')
        end
    end
    if not value and not T.requested_at then
        T.pending=nil
        T.status='disabled'
    elseif value and T.status=='disabled' then
        T.status='idle'
    end
    return true
end

function S.begin_trunk_scan(update_target_id)
    T.pending=nil
    T.received=0
    T.last_error=nil
    T.last_completed_request_at=nil
    T.completed_update_target_id=nil
    T.review_needed=false
    T.update_target_id=update_target_id
    T.requested_at=os.time()
    T.scan_started_at=T.requested_at
    T.scan_raw_start=T.raw_packet_events or 0
    T.scan_packet_start=T.packet_events or 0
    T.saw_delta_after_request=false
    T.status='waiting_open'
    return true
end

function S.cancel_trunk_scan()
    T.pending=nil
    T.received=0
    T.requested_at=nil
    T.update_target_id=nil
    T.completed_update_target_id=nil
    T.saw_delta_after_request=false
    T.status=T.autoscan_enabled and 'idle' or 'disabled'
    T.last_error=nil
    return true
end

function S.find_snapshot(id)
    if not id then return nil end
    for i,saved in ipairs(S.snapshots or {}) do
        if tostring(saved.id)==tostring(id) then return saved,i end
    end
    return nil
end

function S.delete_snapshot(snapshot)
    if type(snapshot)~='table' then return false,'Хранилище не выбрано' end
    if snapshot.source=='packet220_trunk' then
        return S.clear_live_snapshot()
    end
    local index=nil
    for i,saved in ipairs(S.snapshots or {})do
        if saved==snapshot then index=i;break end
    end
    if not index then return false,'Хранилище уже удалено' end
    local prior=S.snapshots
    local prior_saved=DSP.settings and DSP.settings.storage_snapshots
    local fresh={}
    for i,saved in ipairs(prior)do if i~=index then fresh[#fresh+1]=saved end end
    S.snapshots=fresh
    if DSP.settings then DSP.settings.storage_snapshots=fresh end
    if DSP.save_settings then
        local called,ok,err=pcall(DSP.save_settings)
        if not called or not ok then
            S.snapshots=prior
            if DSP.settings then DSP.settings.storage_snapshots=prior_saved end
            return false,tostring(err or ok or 'save error')
        end
    end
    S.sort_cache=setmetatable({},{__mode='k'})
    return true
end

function S.clear_live_snapshot()
    local prior=S.snapshots
    local prior_saved=DSP.settings and DSP.settings.storage_snapshots
    local fresh={}
    for _,saved in ipairs(prior or {})do
        if saved.source~='packet220_trunk' then fresh[#fresh+1]=saved end
    end
    S.snapshots=fresh
    if DSP.settings then DSP.settings.storage_snapshots=fresh end
    local old_state={snapshot=T.snapshot,occupied=T.occupied,total=T.total,received=T.received,
        last_saved_at=T.last_saved_at,last_completed_request_at=T.last_completed_request_at,
        status=T.status}
    T.snapshot=nil;T.occupied=nil;T.total=nil;T.received=0
    T.last_saved_at=nil;T.last_completed_request_at=nil
    if not T.requested_at then T.status=T.autoscan_enabled and 'idle' or 'disabled' end
    if DSP.save_settings then
        local called,ok,err=pcall(DSP.save_settings)
        if not called or not ok then
            S.snapshots=prior
            if DSP.settings then DSP.settings.storage_snapshots=prior_saved end
            for k,v in pairs(old_state)do T[k]=v end
            return false,tostring(err or ok or 'save error')
        end
    end
    S.sort_cache=setmetatable({},{__mode='k'})
    return true
end

function S.library()
    local rows={}
    for i,saved in ipairs(S.snapshots or {}) do
        if saved.source~='packet220_trunk' then
            rows[#rows+1]={snapshot=saved,index=i}
        end
    end
    return rows
end

-- Candidate detection is only a suggestion, never a vehicle identifier.
-- Compare item IDs and enchantments across slots, not slot positions or amounts.
-- Only fully saved, named type-8 trunk snapshots are eligible.
local function trunk_types(snapshot)
    local keys, count={},0
    for _,row in ipairs(snapshot and snapshot.rows or {}) do
        local id=tonumber(row.id)
        if id and id>0 and id%1==0 then
            local enchant=tonumber(row.ench) or 0
            local key=tostring(id)..':'..tostring(enchant)
            if not keys[key] then keys[key]=true;count=count+1 end
        end
    end
    return keys,count
end

function S.match_saved_trunks(snapshot)
    if type(snapshot)~='table' or snapshot.kind~='trunk'
        or snapshot.source~='packet220_trunk' or not VALID_CAPACITY[snapshot.slots_count]
        or type(snapshot.rows)~='table' then return {} end
    local current,total=trunk_types(snapshot)
    if total==0 then return {} end
    local matches={}
    for _,saved in ipairs(S.snapshots or {}) do
        if saved.source=='packet220_trunk_named' and saved.kind=='trunk'
            and type(saved.rows)=='table'
            and (snapshot.server==nil or saved.server==nil
                 or tostring(snapshot.server)==tostring(saved.server)) then
            local previous,count=trunk_types(saved)
            if count>0 then
                local common=0
                for key in pairs(current)do if previous[key] then common=common+1 end end
                if common>0 then
                    local union=total+count-common
                    matches[#matches+1]={
                        id=saved.id,title=saved.title,shared=common,
                        current_types=total,saved_types=count,
                        similarity=math.floor(100*common/math.max(1,union)+.5),
                        observed_at=tonumber(saved.observed_at) or 0
                    }
                end
            end
        end
    end
    table.sort(matches,function(a,b)
        if a.similarity~=b.similarity then return a.similarity>b.similarity end
        if a.shared~=b.shared then return a.shared>b.shared end
        if a.observed_at~=b.observed_at then return a.observed_at>b.observed_at end
        return tostring(a.id)<tostring(b.id)
    end)
    return matches
end

-- Keep manually named copies independent from the latest automatically opened
-- vehicle. The packet has no trusted vehicle ID: do NOT auto-assign old labels
-- when a different trunk is opened.
function S.save_named_trunk(snapshot,label)
    if type(snapshot)~='table' or snapshot.source~='packet220_trunk' then
        return false,'select a confirmed full trunk snapshot'
    end
    if not snapshot.rows or not VALID_CAPACITY[snapshot.slots_count] then
        return false,'incomplete trunk snapshot'
    end
    local name=DSP.trim(DSP.clean_text(tostring(label or '')))
    if name=='' or #name>66 or name:find('[%c]') then
        return false,'name must contain 1-66 characters without controls'
    end
    S._named_seq=(S._named_seq or 0)+1
    local ts=os.time()
    local rows={}
    for i,r in ipairs(snapshot.rows) do
        rows[i]={slot=r.slot,id=r.id,name=r.name,ench=r.ench,
            qty=r.qty,quantity_confirmed=r.quantity_confirmed}
    end
    local named={id='trunk_saved_'..tostring(ts)..'_'..tostring(S._named_seq),
        title=name,kind='trunk',source='packet220_trunk_named',
        identity_verified=false,complete_verified=true,
        observed_at=snapshot.observed_at,server=snapshot.server,
        slots_count=snapshot.slots_count,occupied_slots=snapshot.occupied_slots,
        count_known=snapshot.count_known,rows=rows}
    for _,existing in ipairs(S.snapshots or {}) do
        if existing.source~='packet220_trunk' and DSP.lower(tostring(existing.title or ''))==DSP.lower(name) then
            return false,'Такое название уже есть. Открой его и выбери «Обновить».'
        end
    end
    local prior=S.snapshots
    local prior_saved=DSP.settings and DSP.settings.storage_snapshots
    local fresh={named}
    for _,existing in ipairs(prior) do
        -- Old releases wrote a nameless live scan into settings. Keep ONLY
        -- deliberately saved user records in the persistent library.
        if existing.source~='packet220_trunk' then
            fresh[#fresh+1]=existing
            if #fresh>=S.max_saved then break end
        end
    end
    S.snapshots=fresh
    if DSP.settings then DSP.settings.storage_snapshots=fresh end
    if DSP.save_settings then
        local ok,saved,err=pcall(DSP.save_settings)
        if not ok or not saved then
            S.snapshots=prior
            if DSP.settings then DSP.settings.storage_snapshots=prior_saved end
            return false,tostring(err or saved or 'save failed')
        end
    end
    T.completed_update_target_id=nil
    T.review_needed=false
    S.sort_cache=setmetatable({},{__mode='k'})
    return true,named
end

function S.apply_latest_to_saved(target_id)
    local live=T.snapshot
    local target=S.find_snapshot(target_id)
    if not live or live.source~='packet220_trunk' or not VALID_CAPACITY[live.slots_count] then
        return false,'Нет полного нового скана'
    end
    if not target or target.source~='packet220_trunk_named' then
        return false,'Сохранённый багажник не найден'
    end
    local backup={
        rows=target.rows,observed_at=target.observed_at,server=target.server,
        occupied_slots=target.occupied_slots,count_known=target.count_known,
        slots_count=target.slots_count,updated_at=target.updated_at
    }
    local rows={}
    for i,row in ipairs(live.rows or {}) do
        rows[i]={slot=row.slot,id=row.id,name=row.name,ench=row.ench,
            qty=row.qty,quantity_confirmed=row.quantity_confirmed}
    end
    target.rows=rows
    target.observed_at=live.observed_at
    target.updated_at=os.time()
    target.server=live.server
    target.occupied_slots=live.occupied_slots
    target.count_known=live.count_known
    target.slots_count=live.slots_count
    if DSP.settings then DSP.settings.storage_snapshots=S.snapshots end
    if DSP.save_settings then
        local called,ok,err=pcall(DSP.save_settings)
        if not called or not ok then
            for k,v in pairs(backup) do target[k]=v end
            if DSP.settings then DSP.settings.storage_snapshots=S.snapshots end
            return false,tostring(err or ok or 'save error')
        end
    end
    T.completed_update_target_id=nil
    T.review_needed=false
    S.sort_cache=setmetatable({},{__mode='k'})
    return true,target
end

-- Refresh timeout status when the scanner panel is drawn, even if no more packets arrive.
function S.trunk_state()
    local now=os.time()
    if T.pending and now-T.pending.started>PENDING_TIMEOUT then
        T.pending=nil;T.status='incomplete';T.last_error='Incomplete 180-slot batch timed out'
    end
    if T.requested_at and now-T.requested_at>45 then
        T.requested_at=nil
        T.update_target_id=nil
        if T.status=='waiting_open' or T.status=='receiving' or T.status=='need_reopen' then
            T.status='no_packets'
            T.last_error='Полный снимок 180/180 не получен. Запусти скан и заново открой багажник.'
        end
    end
    return T
end

end
__mod_47_storage()

local function __mod_47a_storage_textdraw()
-- Bounded, explicitly armed TextDraw observation for container diagnostics.
-- This is NOT OCR, memory reading or a general inventory scraper.
local S=DSP.storage
S.td_session=S.td_session or {state='off',draws={},seen=0}
local T=S.td_session
local function now() return os.time() end
local function valid()
    if T.state~='armed' then return false end
    if now()>(T.until_ts or 0) then T.state='expired';return false end
    return true
end
function S.arm_textdraw(seconds)
    T.state='armed';T.until_ts=now()+math.max(5,math.min(60,tonumber(seconds)or 25))
    T.draws={};T.seen=0;T.events=0;T.unique=0;T.last_error=nil;T.selected_kind=nil;T.result=nil;T.kind=nil;T.title=nil
    return true
end
function S.textdraw_state()
    valid()
    return T.state,T.seen or 0,T.last_error
end
local function text_of(value)
    if type(value)=='table' then value=value.text or value.string or value.value end
    if type(value)~='string' then return nil end
    local s=DSP.clean_text(value):gsub('~[%w]~',''):gsub('[\r\n]',' ')
    s=DSP.trim(s)
    if s=='' or #s>255 then return nil end
    return s
end
function S.observe_textdraw(id,value)
    if not valid() then return false end
    T.events=(T.events or 0)+1
    if type(id)~='number' and type(id)~='string' then return false end
    local s=text_of(value)
    if not s then return false end
    T.seen=T.seen+1
    -- Headers are often overwritten by a later TextDraw update. Remember only
    -- a title explicitly received during this capture, never guess a source.
    if S.kind_of(s) then T.kind=S.kind_of(s);T.title=s end
    -- Bounded by 110 unique IDs; update in place, no per-frame scanning.
    if T.draws[id]==nil and (T.unique or 0)>=110 then return false end
    if T.draws[id]==nil then T.unique=(T.unique or 0)+1 end
    T.draws[id]=s
    return true
end
function S.finish_textdraw()
    if T.state~='armed' and T.state~='expired' then return false,'Нет активного сбора' end
    T.state='done'
    local lines={}
    local kind,title=T.kind,T.title
    local ids={}
    for id in pairs(T.draws or {}) do ids[#ids+1]=id end
    table.sort(ids,function(a,b)return tostring(a)<tostring(b)end)
    for _,id in ipairs(ids) do
        local line=T.draws[id]
        local k=S.kind_of(line)
        if k and not kind then kind=k;title=line end
        local r=S.parse_line(line)
        -- Unknown qty from a TextDraw is a UI label, not a reliable item count.
        if r and r.quantity_confirmed and not k then lines[#lines+1]=line end
    end
    if not kind then
        T.last_error='Не обнаружен заголовок хранилища: событий '..tostring(T.events or 0)..', текстовых '..tostring(T.seen)..'. Возможно, интерфейс нативный.'
        return false,T.last_error
    end
    if #lines==0 then
        T.last_error='Заголовок '..tostring(title)..' есть, но количество не распознано ('..tostring(T.unique or 0)..' TextDraw). Нужен формат клиента.'
        return false,T.last_error
    end
    local ok,r=S.accept(kind,title,table.concat(lines,'\n'),now(),'textdraw')
    if not ok then T.last_error=tostring(r);return false,T.last_error end
    T.result=r;T.last_error=nil
    return true,r
end
function S.install_textdraw()
    if S.td_hook_installed then return end
    local ok,sampev=pcall(require,'samp.events')
    if not ok or not sampev then return false,'samp.events unavailable' end
    S.td_hook_installed=true
    local prev_show=sampev.onShowTextDraw
    sampev.onShowTextDraw=function(id,data)
        if T.state=='armed' then pcall(S.observe_textdraw,id,data) end
        if prev_show then return prev_show(id,data) end
    end
    local prev_player=sampev.onShowPlayerTextDraw
    sampev.onShowPlayerTextDraw=function(id,data)
        if T.state=='armed' then pcall(S.observe_textdraw,'p'..tostring(id),data) end
        if prev_player then return prev_player(id,data) end
    end
    local prev_player_change=sampev.onPlayerTextDrawSetString
    sampev.onPlayerTextDrawSetString=function(id,value)
        if T.state=='armed' then pcall(S.observe_textdraw,'p'..tostring(id),value) end
        if prev_player_change then return prev_player_change(id,value) end
    end
    local prev_change=sampev.onTextDrawSetString
    sampev.onTextDrawSetString=function(id,text)
        if T.state=='armed' then pcall(S.observe_textdraw,id,text) end
        if prev_change then return prev_change(id,text) end
    end
    return true
end

end
__mod_47a_storage_textdraw()

local function __mod_47b_storage_probe()
-- Opt-in, read-only observer for unknown InventoryScreen containers.
-- Does not send packets, click slots or assume undocumented type => kind mappings.
local S = DSP.storage
local P = {armed=false, status='idle', entries={}, order={}, observed=0, ignored_trunk=0, ignored_stall=0}
DSP.storage_probe = P
local MAX_SECONDS, MAX_SLOTS, MAX_SAMPLES, MAX_BYTES = 60, 180, 8, 100000
local allowed = {cabinet=true, warehouse=true}

local function integer(value, maximum, minimum)
    local n=tonumber(value)
    minimum=minimum or 0
    if n and n==n and n%1==0 and n>=minimum and n<=maximum then return n end
    return nil
end
local function observed_slot(item)
    if type(item)~='table' then return nil end
    local slot=integer(item.slot,MAX_SLOTS-1)
    local id=integer(item.item or item.id,2000000000)
    if not slot or not id then return nil end
    local qty=id==0 and 0 or integer(item.amount or item.count,2000000000)
    local ench=integer(item.enchant or item.ench or 0,100) or 0
    return {slot=slot,id=id,qty=qty,ench=ench}
end
local function decode_candidate(raw)
    if type(raw)~='string' or #raw<2 or #raw>MAX_BYTES then return nil end
    local ok,obj=pcall(decodeJson,raw:gsub('%z+$',''))
    if not ok or type(obj)~='table' or type(obj.items)~='table' then return nil end
    local packet_type=integer(obj.type,255)
    if not packet_type or #obj.items<1 or #obj.items>MAX_SLOTS then return nil end
    local slots,seen={},{}
    for _,item in ipairs(obj.items)do
        local v=observed_slot(item)
        if not v or seen[v.slot] then return nil end
        seen[v.slot]=true
        slots[#slots+1]=v
    end
    -- A declared capacity is diagnostic metadata, not proof of identity.
    local cap=integer(obj.capacity or obj.slotCount or obj.totalSlots,MAX_SLOTS,1)
    return packet_type,slots,cap
end

function P.arm(kind, seconds)
    if not allowed[kind] then return false,'unknown kind' end
    local dur=integer(seconds or 40,MAX_SECONDS,5) or 40
    P.armed=true;P.status='armed';P.kind=kind;P.started=os.time()
    P.until_ts=P.started+dur;P.entries={};P.order={}
    P.observed=0;P.ignored_trunk=0;P.ignored_stall=0;P.last_error=nil
    return true
end
function P.stop()
    if P.armed then P.armed=false;P.status='review';return true end
    return false
end
function P.state()
    if P.armed and os.time()>P.until_ts then P.armed=false;P.status='review' end
    return P
end
function P.on_packet(sub,raw)
    if not P.state().armed then return false end
    local namespace=integer(sub,255)
    if namespace~=0 and namespace~=2 then return false end
    local typ,slots,capacity=decode_candidate(raw)
    if not typ then return false end
    -- type 8 is the independently observed vehicle trunk, never a cupboard.
    if typ==8 then P.ignored_trunk=P.ignored_trunk+1;return false end
    -- The existing trade handler identifies type 1/sub 2 as stall inventory.
    if typ==1 and namespace==2 then P.ignored_stall=P.ignored_stall+1;return false end
    local key=tostring(typ)..'/'..tostring(namespace)
    local row=P.entries[key]
    if not row then
        if #P.order>=MAX_SAMPLES then return false end
        row={type=typ,sub=namespace,slots={},seen={},count=0,packet_count=0,
             capacity=capacity,started=os.time(),last_at=os.time()}
        P.entries[key]=row;P.order[#P.order+1]=row
    end
    -- A fresh batch starting with slot 0 cannot silently merge with an old view.
    if row.seen[0] and slots[1].slot==0 and #slots>=8 then
        row.slots={};row.seen={};row.count=0;row.started=os.time()
    end
    if capacity and row.capacity and row.capacity~=capacity then
        row.slots={};row.seen={};row.count=0;row.started=os.time()
    end
    row.capacity=capacity or row.capacity
    row.packet_count=row.packet_count+1
    row.last_at=os.time()
    for _,v in ipairs(slots) do
        if not row.seen[v.slot] then row.seen[v.slot]=true;row.count=row.count+1 end
        row.slots[v.slot]=v
    end
    P.observed=P.observed+1
    return true
end
function P.preview(index)
    local entry=P.order[tonumber(index) or 0]
    if not entry then return nil,'candidate not found' end
    local rows,occupied,known,missing={},0,0,0
    for i=0,MAX_SLOTS-1 do
        local v=entry.slots[i]
        if v and v.id>0 then
            occupied=occupied+1
            local name=DSP.items and DSP.items.name and DSP.items.name(v.id)
                or ('ID:'..tostring(v.id))
            if type(name)~='string' or name=='' then name='ID:'..tostring(v.id) end
            rows[#rows+1]={slot=i,id=v.id,ench=v.ench,name=name,
                qty=v.qty,quantity_confirmed=v.qty~=nil}
            if v.qty==nil then missing=missing+1 else known=known+v.qty end
        end
    end
    return {entry=entry,rows=rows,occupied=occupied,known=known,unknown_qty=missing,
        complete_unverified=entry.capacity~=nil and entry.count==entry.capacity}
end
function P.save(index)
    if P.state().armed then return false,'stop capture before saving' end
    local view,err=P.preview(index)
    if not view then return false,err end
    if #view.rows==0 then return false,'no occupied items observed' end
    if not allowed[P.kind] then return false,'unknown kind' end
    local titles={cabinet='Шкаф',warehouse='Склад'}
    local now=os.time()
    local snap={id='probe_'..tostring(now)..'_'..tostring(index),
        kind=P.kind,title=titles[P.kind]..' (наблюдение; не проверено)',
        source='packet220_probe',identity_verified=false,complete_verified=false,
        observed_at=now,server=DSP.market and DSP.market.state and DSP.market.state.sid,
        packet_type=view.entry.type,packet_sub=view.entry.sub,
        slots_observed=view.entry.count,slots_reported=view.entry.capacity,
        rows=view.rows,count_known=view.known,occupied_slots=view.occupied}
    local previous=S.snapshots
    local previous_saved=DSP.settings and DSP.settings.storage_snapshots
    -- Keep explicitly saved observations (including their chosen names).
    -- They are history, never proof that the same cabinet was opened again.
    local replacement={snap}
    for _,old in ipairs(previous or {})do
        replacement[#replacement+1]=old
        if #replacement>=(S.max_saved or 20)+1 then break end
    end
    S.snapshots=replacement
    if DSP.settings then DSP.settings.storage_snapshots=replacement end
    if DSP.save_settings then
        local ok,saved,save_error=pcall(DSP.save_settings)
        if not ok or not saved then
            S.snapshots=previous
            if DSP.settings then DSP.settings.storage_snapshots=previous_saved end
            return false,tostring(save_error or saved or 'save failed')
        end
    end
    S.sort_cache=setmetatable({},{__mode='k'})
    return true,snap
end

-- Explicit local diagnostics export. Metadata only: no raw JSON, item names,
-- item IDs, account identifiers, chat, tokens or individual item quantities.
function P.export_report()
    if P.state().armed then return false,'stop capture before export' end
    if type(encodeJson)~='function' or type(DSP.dir)~='string' then
        return false,'JSON export unavailable'
    end
    local candidates={}
    for _,e in ipairs(P.order)do
        candidates[#candidates+1]={type=e.type,sub=e.sub,slots_observed=e.count,
            declared_slots=e.capacity,packets=e.packet_count}
    end
    local report={schema=1,source='Palatka AI read-only probe',kind_label=P.kind,
        duration_seconds=math.max(0,(P.until_ts or 0)-(P.started or 0)),
        packets=P.observed,ignored_trunk=P.ignored_trunk,
        ignored_stall=P.ignored_stall,candidates=candidates}
    local ok,body=pcall(encodeJson,report)
    if not ok or type(body)~='string' then return false,'JSON encoding failed' end
    local path=DSP.dir..'/storage_probe_report.json'
    local file,err=io.open(path,'wb')
    if not file then return false,tostring(err or 'cannot open report') end
    local wrote,write_err=file:write(body)
    file:close()
    if not wrote then return false,tostring(write_err or 'write failed') end
    return true,path
end

end
__mod_47b_storage_probe()

local function __mod_47c_storage_search()
-- Search saved containers by item name; all totals are scoped to the
-- user's query, never the entire trunk. Works only with user-saved snapshots.
local S=DSP.storage

function S.search_library(query,lookup)
    local needle=DSP.lower(DSP.trim(query or ''))
    local report={
        query=needle, results={},storage_count=0,match_groups=0,
        known_qty=0,unknown_slots=0,priced_value=0,unpriced_groups=0,
        different_server=0
    }
    if needle=='' then return report end
    for _,entry in ipairs(S.library())do
        local snap=entry.snapshot
        local info=S.evaluate(snap,lookup)
        local hits={}
        local qty,unknown,value,unpriced=0,0,0,0
        for _,item in ipairs(info.rows or {})do
            if DSP.lower(tostring(item.name or '')):find(needle,1,true) then
                local known=tonumber(item.qty) or 0
                local missing=tonumber(item.unknown_slots) or 0
                local bid=not info.cross_server and tonumber(item.bid) or nil
                local estimated=bid and known*bid or nil
                hits[#hits+1]={
                    name=item.name, key=item.key,id=item.id,ench=item.ench,
                    qty=known,unknown_slots=missing,
                    unit_buy=bid,total_buy=estimated,
                    market_unavailable=info.cross_server
                }
                qty=qty+known
                unknown=unknown+missing
                if estimated then value=value+estimated
                elseif known>0 then unpriced=unpriced+1 end
            end
        end
        table.sort(hits,function(a,b)
            if a.qty~=b.qty then return a.qty>b.qty end
            return tostring(a.name)<tostring(b.name)
        end)
        local title_hit=DSP.lower(tostring(snap.title or '')):find(needle,1,true)~=nil
        if #hits>0 or title_hit then
            local line={
                index=entry.index,snapshot=snap,matched_items=hits,title_only=title_hit and #hits==0,
                known_qty=qty,unknown_slots=unknown,
                priced_value=value,unpriced_groups=unpriced,
                cross_server=info.cross_server
            }
            report.results[#report.results+1]=line
            report.storage_count=report.storage_count+1
            report.match_groups=report.match_groups+#hits
            report.known_qty=report.known_qty+qty
            report.unknown_slots=report.unknown_slots+unknown
            report.priced_value=report.priced_value+value
            report.unpriced_groups=report.unpriced_groups+unpriced
            if info.cross_server and #hits>0 then
                report.different_server=report.different_server+1
            end
        end
    end
    table.sort(report.results,function(a,b)
        if a.title_only~=b.title_only then return not a.title_only end
        if a.known_qty~=b.known_qty then return a.known_qty>b.known_qty end
        return tostring(a.snapshot.title)<tostring(b.snapshot.title)
    end)
    return report
end

end
__mod_47c_storage_search()

local function __mod_48_flip_intel()
-- v2.2.4: independent resale workstation. All values are estimates from market
-- offers, never evidence of completed transactions or reserved stock.
DSP.flip = DSP.flip or {}
local F = DSP.flip
local MAX_SAFE = 9007199254740991
local function num(x, fallback)
    local n=tonumber(x)
    if not n or n~=n or n==math.huge or n==-math.huge then return fallback or 0 end
    return n
end
local function integer(x, fallback)
    return math.max(0,math.floor(num(x,fallback)))
end
function F.settings()
    if type(DSP.settings.flip)~='table' then DSP.settings.flip={} end
    local s=DSP.settings.flip
    s.capital=math.min(MAX_SAFE,integer(s.capital))
    s.reserve_pct=math.min(90,integer(s.reserve_pct,20))
    s.max_position_pct=math.min(100,math.max(5,integer(s.max_position_pct,35)))
    s.min_roi=math.min(10000,integer(s.min_roi,5))
    s.max_risk=math.min(3,integer(s.max_risk,2))
    if s.sort~='roi' and s.sort~='unit' then s.sort='profit' end
    if type(s.watch)~='table' then s.watch={} end
    if type(s.alerts)~='boolean' then s.alerts=false end
    return s
end
local function risk_of(r,now,max_age)
    local a,b=r.sell_offer or {},r.buy_offer or {}
    local risk=0;local reasons={}
    local function flag(msg,level)
        if level>risk then risk=level end
        reasons[#reasons+1]=msg
    end
    for _,o in ipairs({a,b}) do
        if integer(o.qty)==1 and not o.verified_at then flag('объём API=1 может быть одним слотом',3) end
        local ts=integer(o.ts)
        if ts<=0 then flag('нет времени снимка',2)
        elseif ts>now+60 or now-ts>max_age then flag('старые данные',3) end
        if o.qty_source~='game' and o.qty_source~='manual' then flag('остаток не проверен в игре',1) end
    end
    if tostring(a.shop)==tostring(b.shop) then flag('одна лавка с обеих сторон',3) end
    if r.demand_verified==false then flag('скупка не гарантирована',2) end
    return risk,table.concat(reasons,'; ')
end
function F.score_route(route,opts,now)
    opts=opts or{};now=now or os.time()
    local q=integer(route and route.tradable_qty)
    local buy=integer(route and route.p_buy)
    local sell=integer(route and route.p_sell)
    if q==0 or buy==0 or sell<=buy then return nil end
    local tax=math.min(10000,integer(opts.tax_bp,integer(DSP.settings.tax_bp,200)))
    local max_age=integer(opts.max_age,1800)
    local risk,reason=risk_of(route,now,max_age)
    local cap=integer(opts.budget)
    if cap>0 then q=math.min(q,math.floor(cap/buy)) end
    if q<=0 then return nil end
    q=math.min(q,math.floor(MAX_SAFE/math.max(sell,buy)))
    if q<=0 then return nil end
    local cost=q*buy
    local gross=q*sell
    local fee=math.floor(gross*tax/10000)
    local revenue=gross-fee
    local profit=revenue-cost-integer(opts.extra)
    local roi=cost>0 and profit/cost*100 or 0
    if profit<=0 or roi<num(opts.min_roi) then return nil end
    return {route=route,key=route.row and route.row.key or '?',name=route.name or (route.row and route.row.display) or '?',
        qty=q,buy_price=buy,sell_price=sell,cost=cost,gross=gross,fee=fee,
        revenue=revenue,profit=profit,roi=roi,risk=risk,reason=reason,
        seller=route.sell_offer,buyer=route.buy_offer,
        seller_shop=route.sell_offer and route.sell_offer.shop,
        buyer_shop=route.buy_offer and route.buy_offer.shop}
end
local cache_key,cache
local function signature(groups,s,now)
    local st=DSP.market.state or{}
    return table.concat({tostring(groups),st.sid or 0,st.version or 0,
        s.capital,s.reserve_pct,s.max_position_pct,s.min_roi,s.max_risk,s.sort,
        DSP.settings.tax_bp or 200,math.floor(now/30)},'|')
end
-- Input routes are disjoint allocations produced by the existing allocator.
-- Do not sum each candidate's profit blindly; budget is reserved once globally.
function F.rank(groups, now)
    now=now or os.time()
    local s=F.settings()
    local sig=signature(groups,s,now)
    if sig==cache_key and cache then return cache end
    local options={tax_bp=DSP.settings.tax_bp,max_age=(DSP.settings.arb_filters or{}).max_age or 600,min_roi=s.min_roi}
    local candidates={}
    for _,group in ipairs(groups or{}) do
        for _,r in ipairs(group.routes or{}) do
            local c=F.score_route(r,options,now)
            if c and c.risk<=s.max_risk then
                c.group=group
                candidates[#candidates+1]=c
            end
        end
    end
    local mode=s.sort
    table.sort(candidates,function(a,b)
        local ax=mode=='roi' and a.roi or mode=='unit' and a.profit/a.qty or a.profit
        local bx=mode=='roi' and b.roi or mode=='unit' and b.profit/b.qty or b.profit
        if ax~=bx then return ax>bx end
        if a.risk~=b.risk then return a.risk<b.risk end
        return tostring(a.key)<tostring(b.key)
    end)
    local budget=s.capital>0 and math.floor(s.capital*(100-s.reserve_pct)/100) or 0
    local rest=budget
    local per_item={}
    local selected={}
    local total={cost=0,gross=0,fee=0,revenue=0,profit=0,qty=0,count=0,
        capital=s.capital,budget=budget,reserve=s.capital-budget,limited=s.capital>0}
    for _,c in ipairs(candidates) do
        local available=rest
        if s.capital>0 then
            local item_limit=math.floor(budget*s.max_position_pct/100)
            available=math.min(rest,math.max(0,item_limit-(per_item[c.key]or 0)))
        end
        local choice=F.score_route(c.route,{budget=available,tax_bp=DSP.settings.tax_bp,
            max_age=options.max_age,min_roi=s.min_roi},now)
        -- If a capital is set and no more budget remains, never interpret 0
        -- as "unlimited" (the score_route API uses 0 for no limit).
        if s.capital==0 or available>=c.buy_price then
            if choice and total.cost+choice.cost<=MAX_SAFE
                and total.gross+choice.gross<=MAX_SAFE and total.revenue+choice.revenue<=MAX_SAFE then
                choice.group=c.group;selected[#selected+1]=choice
                rest=rest-choice.cost
                per_item[c.key]=(per_item[c.key]or 0)+choice.cost
                total.cost=total.cost+choice.cost;total.gross=total.gross+choice.gross
                total.fee=total.fee+choice.fee;total.revenue=total.revenue+choice.revenue
                total.profit=total.profit+choice.profit;total.qty=total.qty+choice.qty
            end
        end
    end
    total.count=#selected;total.unallocated=rest
    cache={rows=selected,candidates=#candidates,summary=total,version=sig,source='market snapshot'}
    cache_key=sig
    return cache
end
function F.invalidate() cache_key=nil;cache=nil end

-- Independent observations never overwrite the API quote automatically.
-- CR "today" is only shown when the stored sale history explicitly has
-- a day and a positive sold quantity. Open-stall quotes are local sightings.
function F.price_evidence(row)
    local out={api=nil,cr=nil,today=nil,opened=nil,buy=nil,age=nil,interest=0}
    if type(row)~='table' then return out end
    local st=DSP.market.state or{}
    if tonumber(st.sid)~=tonumber(DSP.settings.server) then return out end
    out.api=integer(row.sell and row.sell.med)>0 and integer(row.sell.med) or nil
    out.buy=integer(row.buy and row.buy.med)>0 and integer(row.buy.med) or nil
    out.interest=integer(row.buy and row.buy.shop_n)
    out.age=integer(st.updated)>0 and math.max(0,os.time()-integer(st.updated)) or nil
    local marker=DSP.market.load_cr_marker and DSP.market.load_cr_marker(st.sid)
    if marker and tonumber(marker.sid)==tonumber(st.sid) and (tonumber(row.ench)or 0)==0 then
        local key=DSP.lower(row.name or '')
        for _,it in ipairs(marker.items or{})do
            if DSP.lower(tostring(it.name or ''))==key then
                local val=integer(it.sell_med)
                if val>0 then out.cr=val;out.cr_age=integer(marker.saved_at)>0 and math.max(0,os.time()-integer(marker.saved_at))or nil end
                break
            end
        end
        local history=marker.histories and marker.histories[key]
        if history and history.day==os.date('%Y-%m-%d') and integer(history.qty)>0 and integer(history.avg)>0 then
            out.today=integer(history.avg);out.today_qty=integer(history.qty)
        end
    end
    local shop=DSP.live and DSP.live.shop or nil
    local updated=shop and integer(shop.items_updated or shop.updated)
    if shop and tonumber(shop.server)==tonumber(st.sid) and integer(shop.menu_closed)==0
        and updated>0 and os.time()-updated<=120 then
        local key=row.key or DSP.item_key(row.name,row.ench or 0)
        for _,it in ipairs(shop.sell or{})do
            local k=DSP.item_key(it.name or '',it.ench or 0)
            if k==key and integer(it.price)>0 then
                out.opened=out.opened and math.min(out.opened,integer(it.price)) or integer(it.price)
            end
        end
    end
    return out
end
function F.market_interest(row)
    local n=integer(row and row.buy and row.buy.shop_n)
    if n>=5 then return 'много скупщиков ('..n..')'
    elseif n>=2 then return 'несколько скупщиков ('..n..')'
    elseif n==1 then return 'один скупщик'
    end
    return 'нет наблюдаемой скупки'
end

-- SELL recommendations from asking prices only. They are not completed sales.
function F.suggest_price(row,mode,cost,tax)
    if not row or not row.sell then return nil,'нет рынка' end
    local sell=row.sell
    if integer(sell.count)==0 then return nil,'нет цен предложений' end
    local reference=mode=='fast' and (sell.p25>0 and sell.p25 or sell.min)
        or mode=='premium' and (sell.p75>0 and sell.p75 or sell.med)
        or sell.med
    local rate=mode=='fast' and 0.99 or mode=='premium' and 1.02 or 1
    local price=math.max(1,math.floor(reference*rate))
    if cost~=nil then
        local paid=num(cost,-1)
        if paid<0 then return nil,'неверная себестоимость' end
        local fee=math.min(10000,integer(tax,integer(DSP.settings.tax_bp,200)))
        if fee>=10000 then return nil,'комиссия 100%' end
        local floor_price=math.ceil(paid*10000/(10000-fee))
        price=math.max(price,floor_price)
    end
    return price,'по объявлениям; не подтверждённая цена сделки'
end
function F.watch_set(key,name,limit)
    local s=F.settings();key=tostring(key or '')
    local p=integer(limit)
    if key=='' or p==0 or p>MAX_SAFE then return false,'нужен предмет и цена выше нуля' end
    if not s.watch[key] then
        local n=0;for _ in pairs(s.watch)do n=n+1 end
        if n>=30 then return false,'максимум 30 наблюдений' end
    end
    local previous=s.watch[key]
    s.watch[key]={name=tostring(name or key),max_price=p,server=tonumber((DSP.market.state or{}).sid)or DSP.settings.server}
    if not DSP.save_settings() then s.watch[key]=previous;return false,'не удалось записать настройки' end
    return true
end
function F.watch_remove(key)
    local s=F.settings();local previous=s.watch[key];s.watch[key]=nil
    if not DSP.save_settings() then s.watch[key]=previous;return false,'не удалось записать настройки' end
    return true
end
F.last_alert=0;F.alerted={}
function F.check_alerts(now,notify)
    now=now or os.time();local s=F.settings();local st=DSP.market.state or{}
    if not s.alerts or not st.version or now-F.last_alert<300 then return 0 end
    local count=0
    for key,rule in pairs(s.watch)do
        local r=(st.by_key or{})[key]
        if tonumber(rule.server)==tonumber(st.sid) and r and r.sell and r.sell.min and r.sell.min>0
            and r.sell.min<=integer(rule.max_price) then
            local signature=tostring(st.sid)..':'..tostring(st.version)..':'..key
            if not F.alerted[signature] then
                F.alerted[signature]=true;F.last_alert=now
                if type(notify)=='function' then notify('Наблюдение: '..tostring(rule.name)..' по '..DSP.money(r.sell.min)..' (API, проверьте лавку)')end
                count=count+1;break
            end
        end
    end
    if count>0 then
        local n=0;for _ in pairs(F.alerted)do n=n+1 end
        if n>100 then F.alerted={} end
    end
    return count
end
-- Actual cash movements from saved trades only. Item valuations are excluded.
function F.cash_summary(trades,day)
    local out={trades=0,cash_in=0,cash_out=0,cash_net=0,valued_trades=0}
    local now=os.time();local today=os.date('%Y-%m-%d',now)
    for _,e in pairs(trades or{})do
        if type(e)=='table' and e.type=='trade' and (not day or os.date('%Y-%m-%d',integer(e.ts))==today) then
            out.trades=out.trades+1
            out.cash_in=out.cash_in+integer(e.money_get)
            out.cash_out=out.cash_out+integer(e.money_give)
            if # (e.items_get or{})>0 or #(e.items_give or{})>0 then out.valued_trades=out.valued_trades+1 end
        end
    end
    out.cash_net=out.cash_in-out.cash_out
    return out
end

end
__mod_48_flip_intel()

local function __mod_49_promo()
-- v2.2.4: independent opt-in promotional templates. No dialog bypassing,
-- no posting until a user explicitly starts this session. Bounded rate.
DSP.promo = DSP.promo or {}
local P=DSP.promo
P.running=false;P.last_sent=0;P.session_count=0;P.last_error=nil
P.MAX_SESSION=12;P.MIN_INTERVAL=180
function P.settings()
    if type(DSP.settings.promo)~='table' then DSP.settings.promo={} end
    local s=DSP.settings.promo
    if type(s.templates)~='table' then s.templates={} end
    return s
end
-- One preset can contain multiple channels. Each line is sent separately
-- with the global cooldown: never batch flood several chats together.
P.ALLOWED={vr=true,s=true,ad=true,fam=true,gd=true}
function P.lines(text)
    local rows={}
    for line in (tostring(text or '')..'\n'):gmatch('([^\r\n]*)\r?\n') do
        line=line:match('^%s*(.-)%s*$')
        if line~='' then rows[#rows+1]=line end
    end
    return rows
end
function P.validate(text)
    if type(text)~='string' or #text<5 or #text>720 then return false,'текст 5–720 байт' end
    if text:find('[%z\1-\8\11\12\14-\31]') then return false,'запрещён управляющий символ' end
    local lines=P.lines(text)
    if #lines==0 or #lines>6 then return false,'от 1 до 6 строк рекламы' end
    for _,line in ipairs(lines) do
        if #line>200 then return false,'строка превышает 200 байт' end
        local command=line:match('^/([%a]+)%s+%S')
        if not (command and P.ALLOWED[command]) then
            return false,'строка должна начинаться с /vr, /s, /ad, /fam или /gd'
        end
    end
    return true
end
function P.own_shop_number()
    local s=P.settings()
    local manual=tonumber(s.shop_number)
    if manual and manual>=1 and manual<=99999 and manual%1==0 then return math.floor(manual),'в настройках' end
    if DSP.shop_identity and DSP.shop_identity.own_shop_number then
        local ok,n,src=pcall(DSP.shop_identity.own_shop_number)
        if ok and n then return n,'авто: '..tostring(src or 'identity') end
    end
    local saved=tonumber(DSP.settings and DSP.settings.own_shop_num_saved)
    if saved and saved>=1 and saved<=99999 and saved%1==0 then return math.floor(saved),'запомнен автоматически' end
    local shop=DSP.live and DSP.live.shop
    local nickname=DSP.player_nick and DSP.player_nick() or ''
    local id=shop and tonumber(shop.num)
    if nickname~='' and shop and DSP.lower(tostring(shop.owner or ''))==DSP.lower(nickname) and id and id>=1 and id<=99999 and id%1==0 then
        return math.floor(id),'своя открытая лавка'
    end
    return nil,'номер своей лавки пока не определён'
end
function P.set_shop_number(n)
    n=tonumber(n)
    if not n or n%1~=0 or n<0 or n>99999 then return false,'номер: 0–99999' end
    local s=P.settings();local before=s.shop_number
    s.shop_number=n
    if not DSP.save_settings() then s.shop_number=before;return false,'не удалось сохранить' end
    return true
end
function P.expand(text)
    if not (text:find('{лавка}',1,true) or text:find('{shop}',1,true) or text:find('[ЛАВКА]',1,true) or text:find('{номер}',1,true)) then return text end
    local num,err=P.own_shop_number()
    if not num then return nil,err end
    local clickable=':lavka'..tostring(num)..':'
    return (text:gsub('{лавка}',clickable):gsub('{shop}',clickable):gsub('%[ЛАВКА%]',clickable):gsub('{номер}',tostring(num)))
end
function P.add(name,text,interval)
    local s=P.settings()
    if #s.templates>=8 then return false,'максимум 8 шаблонов' end
    local ok,err=P.validate(text);if not ok then return false,err end
    local item={name=tostring(name or 'Объявление'):sub(1,48),text=text,
        interval=math.max(P.MIN_INTERVAL,math.min(3600,math.floor(tonumber(interval)or 300))),auto=false}
    s.templates[#s.templates+1]=item
    if not DSP.save_settings() then table.remove(s.templates);return false,'ошибка сохранения' end
    return true
end
function P.update(index,name,text,interval)
    local item=P.settings().templates[index]
    if not item then return false,'шаблон не найден' end
    local ok,err=P.validate(text);if not ok then return false,err end
    local previous={name=item.name,text=item.text,interval=item.interval,auto=item.auto}
    item.name=tostring(name or ''):sub(1,48)
    item.text=text
    item.interval=math.max(P.MIN_INTERVAL,math.min(3600,math.floor(tonumber(interval)or 300)))
    if not DSP.save_settings() then
        for k,v in pairs(previous)do item[k]=v end
        return false,'ошибка сохранения'
    end
    return true
end
function P.remove(index)
    local s=P.settings();if not s.templates[index] then return false end
    local old=table.remove(s.templates,index)
    if not DSP.save_settings() then table.insert(s.templates,index,old);return false end
    return true
end
local function online_check()
    if type(sampSendChat)~='function' then return false end
    if type(sampIsSampAvailable)=='function' and not sampIsSampAvailable() then return false end
    if type(sampIsLocalPlayerSpawned)=='function' and not sampIsLocalPlayerSpawned() then return false end
    return true
end
function P.send_once(index,now,send,online)
    now=now or os.time()
    local item=P.settings().templates[index]
    if not item then return false,'шаблон не найден' end
    local ok,err=P.validate(item.text);if not ok then return false,err end
    if P.session_count>=P.MAX_SESSION then P.running=false;return false,'лимит за сессию достигнут' end
    if P.last_sent>0 and now-P.last_sent<P.MIN_INTERVAL then return false,'подождите до следующей отправки' end
    if online==nil then online=online_check() end
    if not online then return false,'нет соединения с игрой' end
    local sender=send or sampSendChat
    local lines=P.lines(item.text)
    local index=(tonumber(item.line_index) or 0)%#lines+1
    local resolved,expand_err=P.expand(lines[index])
    if not resolved then return false,expand_err end
    if #resolved>200 then return false,'после подстановки текст слишком длинный' end
    local sent,response=pcall(sender,resolved)
    if not sent or response==false then return false,'команда не отправлена' end
    P.last_sent=now;P.session_count=P.session_count+1
    item.last_sent=now
    item.line_index=index
    P.last_error=nil
    if P.session_count>=P.MAX_SESSION then P.running=false end
    return true
end
function P.start()
    if #P.settings().templates==0 then return false,'сначала создайте шаблон' end
    local active=false
    for _,t in ipairs(P.settings().templates)do if t.auto then active=true end end
    if not active then return false,'выберите шаблон для автоматической отправки' end
    if P.session_count>=P.MAX_SESSION then return false,'лимит за сессию исчерпан' end
    P.running=true
    P.last_error=nil
    P.started=os.time()
    return true
end
function P.stop()P.running=false end
function P.tick(now,send,online)
    if not P.running then return false end
    now=now or os.time()
    if P.session_count>=P.MAX_SESSION then P.stop();return false end
    if online==false or (online==nil and not online_check()) then
        P.last_error='авто-пиар остановлен: соединение потеряно'
        P.stop();return false
    end
    if P.last_sent>0 and now-P.last_sent<P.MIN_INTERVAL then return false end
    for i,t in ipairs(P.settings().templates)do
        if t.auto and (not t.last_sent or now-t.last_sent>=math.max(P.MIN_INTERVAL,tonumber(t.interval)or 300)) then
            local ok,err=P.send_once(i,now,send,online)
            if not ok then P.last_error=err end
            return ok
        end
    end
    return false
end
function P.install()
    if P.installed then return end
    P.installed=true
    -- Resume only templates explicitly marked auto by the user. This is not
    -- a new opt-in: the persisted per-template flag is the user's choice.
    for _,t in ipairs(P.settings().templates) do
        if t.auto then P.running=true; break end
    end
    P.session_count=0
    if not lua_thread or not wait then return end
    lua_thread.create(function()
        while true do
            wait(1000)
            local ok,err=pcall(P.tick,os.time())
            if not ok then P.last_error=tostring(err);P.stop();if DSP.flog then DSP.flog('PROMO '..P.last_error)end end
            -- Watchlists are checked from the already loaded market snapshot;
            -- HTTP refresh remains owned by the existing market updater.
            if DSP.flip and DSP.flip.check_alerts then
                pcall(DSP.flip.check_alerts,os.time(),DSP.notify)
            end
        end
    end)
end

end
__mod_49_promo()

local function __mod_49a_promo_universal()
-- Universal promotion scheduler. Built on Palatka's existing settings and
-- game connection; never bypasses server chat cooldowns or auto-posts by default.
local P=DSP.promo
P.MIN_INTERVAL=60
P.MAX_SESSION=12
P.MAX_TEMPLATES=32
P.MAX_STEP_BYTES=200
P.running=P.running==true
P.cursor=P.cursor or 1
P.next_at=P.next_at or 0
P.cycle_count=P.cycle_count or 0
P.pause_reason=nil
local function num(n,lo,hi)
    n=tonumber(n)
    if n and n==n and n%1==0 then return math.max(lo,math.min(hi,math.floor(n)))end
end
local function persist()
    if DSP.save_settings then return DSP.save_settings()~=false end
    if DSP.mobile and DSP.mobile.defer_save then DSP.mobile.defer_save()end
    return true
end
local function settings()
    local s=P.settings()
    if s.continuous==nil then s.continuous=false end
    if s.resume_on_login==nil then s.resume_on_login=false end
    if s.enabled==nil then s.enabled=false end
    s.start_delay=num(s.start_delay,10,120)or 20
    return s
end
local function online()
    if not sampSendChat then return false end
    if sampIsSampAvailable and not sampIsSampAvailable()then return false end
    if sampIsLocalPlayerSpawned and not sampIsLocalPlayerSpawned()then return false end
    return true
end
local function trim(s)return tostring(s or ''):match('^%s*(.-)%s*$')end
function P.validate(text)
    if type(text)~='string' or #text==0 or #text>1500 then
        return false,'Введите команду или текст (до 1500 байт)'end
    if text:find('[%z\1-\8\11\12\14-\31]')then
        return false,'Управляющие символы запрещены'end
    local n=0
    for _,line in ipairs(P.lines(text))do
        n=n+1
        if n>12 then return false,'Не более 12 команд в одном старом шаблоне'end
        if #line>P.MAX_STEP_BYTES then return false,'Длина строки более 200 байт'end
        -- This scheduler sends chat commands only; no arbitrary raw packets.
        if not line:match('^/[%w_]+[%s%S]*$') then
            return false,'Строка должна начинаться с /команды'end
    end
    return n>0,n==0 and 'Пустой шаблон' or nil
end
local function normalize_item(name,text,interval,auto)
    local ok,err=P.validate(text);if not ok then return nil,err end
    local item={name=trim(name):sub(1,48),text=trim(text),
        interval=num(interval,P.MIN_INTERVAL,3600)or 180,auto=auto~=false,
        last_sent=0,line_index=0}
    if item.name==''then item.name='Строка'end
    return item
end
function P.add(name,text,interval)
    local s=settings()
    if #s.templates>=P.MAX_TEMPLATES then return false,'Лимит 32 строк'end
    local item,err=normalize_item(name,text,interval,true);if not item then return false,err end
    s.templates[#s.templates+1]=item
    if not persist()then table.remove(s.templates);return false,'Настройки не сохранены'end
    return true
end
function P.update(index,name,text,interval)
    local s=settings();local old=s.templates[index]
    if not old then return false,'Строка не найдена'end
    local new,err=normalize_item(name,text,interval,old.auto);if not new then return false,err end
    new.last_sent=old.last_sent or 0;new.line_index=old.line_index or 0
    s.templates[index]=new
    if not persist()then s.templates[index]=old;return false,'Настройки не сохранены'end
    return true
end
function P.remove(index)
    local s=settings()
    if not s.templates[index]then return false end
    local old=table.remove(s.templates,index)
    if not persist()then table.insert(s.templates,index,old);return false end
    P.cursor=math.max(1,math.min(P.cursor,#s.templates))
    return true
end
function P.move(index,delta)
    local rows=settings().templates;local next_index=index+delta
    if not rows[index]or not rows[next_index]then return false end
    rows[index],rows[next_index]=rows[next_index],rows[index]
    if not persist()then rows[index],rows[next_index]=rows[next_index],rows[index];return false end
    P.cursor=next_index
    return true
end
function P.set_option(option,value)
    if option~='continuous'and option~='resume_on_login'and option~='start_delay' then
        return false,'Неизвестный параметр'end
    local s=settings();local before=s[option]
    s[option]=option=='start_delay' and (num(value,10,120)or 20)or(value==true)
    if not persist()then s[option]=before;return false,'Настройки не сохранены'end
    return true
end
function P.steps()
    local rows={}
    for idx,t in ipairs(settings().templates)do
        if t.auto then
            for line_no,cmd in ipairs(P.lines(t.text or''))do
                local ok=P.validate(cmd)
                if ok then rows[#rows+1]={index=idx,line=line_no,command=cmd,
                    interval=num(t.interval,P.MIN_INTERVAL,3600)or 180,
                    name=t.name}end
            end
        end
    end
    return rows
end
function P.start(now)
    if #P.steps()==0 then return false,'Добавь и включи хотя бы одну строку'end
    local s=settings()
    if not s.continuous and P.session_count>=P.MAX_SESSION then
        return false,'Достигнут лимит 12 строк за сессию'
    end
    P.running=true;P.pause_reason=nil;P.last_error=nil
    P.cursor=1
    P.next_at=(now or os.time())+s.start_delay
    P.started=now or os.time();P.was_online=false
    s.enabled=true
    if not persist()then
        P.running=false;s.enabled=false
        return false,'Не удалось сохранить режим'
    end
    return true
end
function P.stop()
    P.running=false;P.pause_reason=nil
    settings().enabled=false
    persist()
end
function P.bootstrap(now)
    local s=settings()
    -- Persisted template flags do not implicitly authorize unattended posting.
    P.running=false;P.pause_reason=nil;P.was_online=false
    P.session_count=0;P.cursor=1;P.next_at=0;P.last_sent=0
    if s.resume_on_login and s.enabled and #P.steps()>0 then
        P.running=true
        P.next_at=(now or os.time())+s.start_delay
        P.pause_reason='Ожидание подключения'
    end
end
function P.send_once(index,at,send,connected)
    at=at or os.time()
    local t=settings().templates[index]
    if not t then return false,'Строка не найдена'end
    local ok,err=P.validate(t.text);if not ok then return false,err end
    local lines=P.lines(t.text)
    if #lines==0 then return false,'Пустая строка'end
    if P.last_sent>0 and at-P.last_sent<P.MIN_INTERVAL then
        return false,'Пауза до следующей отправки'end
    if connected==nil then connected=online()end
    if not connected then return false,'Нет подключения к игре'end
    local i=((num(t.line_index,0,1000)or 0)%#lines)+1
    local resolved,why=P.expand(lines[i])
    if not resolved then return false,why end
    if #resolved>P.MAX_STEP_BYTES then return false,'После подстановки текст длиннее 200 байт'end
    local sender=send or sampSendChat
    if type(sender)~='function'then return false,'Отправка чата недоступна'end
    local success,outcome=pcall(sender,resolved)
    if not success or outcome==false then return false,'Отправка не удалась'end
    P.last_sent=at;P.session_count=P.session_count+1
    t.last_sent=at;t.line_index=i
    P.last_command=resolved;P.last_error=nil
    return true
end
function P.tick(at,send,connected)
    if not P.running then return false end
    local s=settings();at=at or os.time()
    if connected==nil then connected=online()end
    if not connected then
        P.pause_reason='Нет соединения: отправка приостановлена'
        P.was_online=false
        return false
    end
    if not P.was_online then
        P.was_online=true
        P.next_at=math.max(P.next_at,at+s.start_delay)
        P.pause_reason='Ожидание после входа'
        return false
    end
    local steps=P.steps()
    if #steps==0 then P.running=false;P.pause_reason='Нет включённых строк';return false end
    if not s.continuous and P.session_count>=P.MAX_SESSION then
        P.running=false;P.pause_reason='Лимит 12 сообщений за сессию'
        s.enabled=false;persist();return false
    end
    if at<(P.next_at or 0)then return false end
    if P.last_sent>0 and at-P.last_sent<P.MIN_INTERVAL then
        P.next_at=P.last_sent+P.MIN_INTERVAL
        return false
    end
    local index=((P.cursor-1)%#steps)+1
    local step=steps[index]
    local ok,why=P.send_once(step.index,at,send,connected)
    if not ok then
        P.last_error=why;P.pause_reason=why
        P.next_at=at+math.max(P.MIN_INTERVAL,step.interval)
        return false
    end
    P.pause_reason=nil
    P.cursor=index%#steps+1
    if P.cursor==1 then P.cycle_count=(P.cycle_count or 0)+1 end
    P.next_at=at+math.max(P.MIN_INTERVAL,step.interval)
    if not s.continuous and P.session_count>=P.MAX_SESSION then
        P.running=false;P.pause_reason='Лимит отправок исчерпан'
        s.enabled=false;persist()
    end
    return true
end
-- Preserve Palatka's original background thread; replace only the scheduler.
local previous_install=P.install
function P.install()
    if P.installed then return end
    previous_install()
    P.bootstrap(os.time())
end
return true

end
__mod_49a_promo_universal()

local function __mod_50_overlay()
-- 50_overlay.lua
-- v1.2 overlay windows: trade eval + shop scan + crlog mini-window.
-- All colors now flow from DSP.theme so the overlay respects the active
-- theme + opacity slider.

DSP.overlay = DSP.overlay or {}
DSP.overlay.shop_tab = 1
DSP.overlay.trade_closed = 0
DSP.overlay.shop_closed = 0
DSP.overlay.focus_trade = 0
DSP.overlay.focus_shop = 0

if DSP.settings.overlay_shop == nil then DSP.settings.overlay_shop = true end
if DSP.settings.overlay_trade == nil then DSP.settings.overlay_trade = true end
if DSP.settings.overlay_top == nil then DSP.settings.overlay_top = true end

DSP.settings.ui_windows=DSP.settings.ui_windows or {}
local function load_overlay_state(key)
    local v=DSP.settings.ui_windows[key]
    if type(v)=='table' and tonumber(v.x) and tonumber(v.y) then
        return {x=tonumber(v.x),y=tonumber(v.y),w=tonumber(v.w),h=tonumber(v.h)}
    end
end
DSP.overlay.trade_pos=DSP.overlay.trade_pos or load_overlay_state('overlay_trade')
DSP.overlay.shop_pos=DSP.overlay.shop_pos or load_overlay_state('overlay_shop')
local function save_overlay_state(key,state_key)
    local st=DSP.overlay[state_key];if type(st)~='table'then return end
    local prev=DSP.settings.ui_windows[key] or {}
    if math.abs((tonumber(prev.x)or-99999)-(tonumber(st.x)or 0))>.5 or math.abs((tonumber(prev.y)or-99999)-(tonumber(st.y)or 0))>.5
        or math.abs((tonumber(prev.w)or-99999)-(tonumber(st.w)or 0))>.5 or math.abs((tonumber(prev.h)or-99999)-(tonumber(st.h)or 0))>.5 then
        DSP.settings.ui_windows[key]={x=st.x,y=st.y,w=st.w,h=st.h}
        if DSP.mobile and DSP.mobile.defer_save then DSP.mobile.defer_save() end
    end
end
local function capture_overlay(key,state_key)
    if not(imgui.GetWindowPos and imgui.GetWindowSize)then return end
    local wh=imgui.GetWindowSize();local st=DSP.overlay[state_key]
    if not st then local p=imgui.GetWindowPos();st={x=p.x,y=p.y};DSP.overlay[state_key]=st end
    st.w,st.h=wh.x,wh.y;save_overlay_state(key,state_key)
end

local function d()
    return tonumber(DSP.ui and DSP.ui.d) or tonumber(DSP.settings.dpi) or 1.25
end

local function col(r, g, b, a)
    return imgui.ImVec4(r, g, b, a or 1)
end

local function u(s)
    return DSP.utf8(s)
end

-- Theme-backed semantic colors (still cache locals for hot path speed).
local GREEN, YELLOW, RED, GRAY, BLUE
local function refresh_palette()
    GREEN  = DSP.theme.col('good', 1)
    YELLOW = DSP.theme.col('warn', 1)
    RED    = DSP.theme.col('bad',  1)
    GRAY   = DSP.theme.col('muted',1)
    BLUE   = DSP.theme.col('accent', 1)
end

local function base_label()
    local sid = tonumber(DSP.db.sid) or 0
    local cur = tonumber(DSP.market.state and DSP.market.state.sid) or 0
    local fresh = DSP.db.freshness()
    if sid > 0 and cur > 0 and sid ~= cur then
        return 'M' .. sid .. ' (текущий M' .. cur .. ')'
    end
    return sid > 0 and ('M' .. sid .. ' ' .. fresh) or fresh
end

local function item_price(it)
    local e = DSP.db.get(it.name, it.ench)
    if not e or not e.sell or not e.sell.min or e.sell.min <= 0 then return nil end
    return e.sell.min
end

function DSP.overlay.trade_sum()
    local t = DSP.live.trade
    local get_v, give_v, miss_get, miss_give = 0, 0, 0, 0
    for _, it in ipairs(t.get or {}) do
        local p = item_price(it)
        if p then get_v = get_v + p * (it.qty or 1) else miss_get = miss_get + 1 end
    end
    for _, it in ipairs(t.give or {}) do
        local p = item_price(it)
        if p then give_v = give_v + p * (it.qty or 1) else miss_give = miss_give + 1 end
    end
    local total_get = get_v + (t.money_get or 0)
    local total_give = give_v + (t.money_give or 0)
    local delta = total_get - total_give
    local pct = total_give > 0 and (delta / total_give * 100) or 0
    return total_get, total_give, delta, pct, miss_get, miss_give, get_v, give_v
end

function DSP.overlay.trade_ratio()
    local t = DSP.live.trade
    local _, _, _, _, _, _, get_v, give_v = DSP.overlay.trade_sum()
    local mg, mr = t.money_give or 0, t.money_get or 0
    if mr > 0 and mg == 0 and give_v > 0 then return mr / give_v, 'sale' end
    if mg > 0 and mr == 0 and get_v > 0 then return mg / get_v, 'buy' end
    local total_get = get_v + mr
    local total_give = give_v + mg
    if total_give > 0 then return total_get / total_give, 'swap' end
    return nil, 'none'
end

function DSP.overlay.show_trade()
    if DSP.settings.fps_saver then return false end
    if DSP.settings.overlay_trade == false then return false end
    local t = DSP.live.trade
    if not t or (t.opened or 0) == 0 then return false end
    local age = DSP.live.trade_age()
    if t.complete and age > 60 then return false end
    if age > 600 then return false end
    if DSP.overlay.trade_closed == t.opened then return false end
    return (#(t.give or {}) > 0 or #(t.get or {}) > 0
        or (t.money_give or 0) > 0 or (t.money_get or 0) > 0)
end

function DSP.overlay.show_shop()
    if DSP.settings.fps_saver then return false end
    if DSP.settings.overlay_shop == false then return false end
    local s = DSP.live.shop
    if not s or (s.opened or 0) == 0 then return false end
    if DSP.overlay.shop_closed == s.opened then return false end
    if (s.menu_closed or 0) > 0 then return false end
    if DSP.live.shop_age() > 300 then return false end
    return #(s.sell or {}) > 0 or #(s.buy or {}) > 0
end

-- Allow dragging overlays ONLY by their header, never by the content.
-- The fixed screen coordinates are clamped to keep the close button reachable.
local function overlay_drag_bar(label,id,width,height,state_key)
    imgui.PushStyleColor(imgui.Col.Button,imgui.ImVec4(0,0,0,0))
    imgui.PushStyleColor(imgui.Col.ButtonHovered,imgui.ImVec4(0,0,0,.08))
    imgui.PushStyleColor(imgui.Col.ButtonActive,imgui.ImVec4(0,0,0,.12))
    imgui.PushStyleColor(imgui.Col.Text,BLUE)
    imgui.Button(u(label)..'##drag_overlay_'..id,imgui.ImVec2(math.max(55,width),height or 42))
    local active=imgui.IsItemActive()
    imgui.PopStyleColor(4)
    local io=imgui.GetIO()
    if active and io and io.MouseDelta and imgui.GetWindowPos and imgui.GetWindowSize then
        local dx,dy=io.MouseDelta.x or 0,io.MouseDelta.y or 0
        if dx~=0 or dy~=0 then
            local pos,wh=imgui.GetWindowPos(),imgui.GetWindowSize()
            DSP.overlay[state_key]={
                x=math.max(0,math.min(pos.x+dx,math.max(0,io.DisplaySize.x-wh.x))),
                y=math.max(0,math.min(pos.y+dy,math.max(0,io.DisplaySize.y-wh.y))),
                w=wh.x,h=wh.y }
            save_overlay_state(state_key=='trade_pos' and 'overlay_trade' or 'overlay_shop',state_key)
        end
    end
end
local function overlay_next_pos(key,default_x,default_y,pivot,sw,sh,w,h)
    local pos=DSP.overlay[key]
    if pos then
        -- For auto-sized trade overlays use the real measured window size,
        -- not a large estimate that makes the window jump on the next frame.
        local measured_w=tonumber(pos.w) or w
        local measured_h=tonumber(pos.h) or h
        local x=math.max(0,math.min(pos.x,math.max(0,sw-measured_w)))
        local y=math.max(0,math.min(pos.y,math.max(0,sh-measured_h)))
        pos.x,pos.y=x,y
        imgui.SetNextWindowPos(imgui.ImVec2(x,y),imgui.Cond.Always)
    else
        imgui.SetNextWindowPos(imgui.ImVec2(default_x,default_y),imgui.Cond.FirstUseEver,pivot)
    end
end

local function close_btn(id)
    imgui.SameLine(0, 8 * d())
    if imgui.Button('X##' .. id, imgui.ImVec2(64, 56)) then return true end
    return false
end

local function trade_item_row(it, kind)
    local e = DSP.db.get(it.name, it.ench)
    local qty = it.qty or 1
    local disp = DSP.item_name(it.name, it.ench)
    if imgui.TextWrapped then imgui.TextWrapped(u(disp .. '  x' .. tostring(qty)))
    else imgui.Text(u(disp .. '  x' .. tostring(qty))) end
    if not e or not e.sell or not e.sell.min or e.sell.min <= 0 then
        imgui.TextColored(GRAY, u('нет базы'))
        return
    end
    local unit = e.sell.min
    local sum = unit * qty
    imgui.TextColored(BLUE, u(DSP.money(unit)))
    imgui.SameLine(0, 6 * d())
    imgui.TextColored(GRAY, u('=' .. DSP.money(sum)))
    if kind == 'get' then
        imgui.SameLine(0, 6 * d())
        imgui.TextDisabled(u('рынок ' .. DSP.money(e.sell.med or unit)))
    end
end

function DSP.overlay.draw_trade()
    refresh_palette()
    local t = DSP.live.trade
    local sw, sh = imgui.GetIO().DisplaySize.x, imgui.GetIO().DisplaySize.y
    local saved=DSP.overlay.trade_pos
    local w = math.min(sw-16,math.max(250,tonumber(saved and saved.w) or math.min(sw*.38,540*d())))
    local hh=math.min(sh-16,math.max(180,tonumber(saved and saved.h) or math.max(270,sh*.57)))
    overlay_next_pos('trade_pos',sw-8*d(),76*d(),imgui.ImVec2(1,0),sw,sh,w,hh)
    imgui.SetNextWindowSize(imgui.ImVec2(w,hh),imgui.Cond.FirstUseEver)
    if DSP.settings.overlay_top ~= false then imgui.SetNextWindowFocus() end
    imgui.SetNextWindowBgAlpha(DSP.theme.opacity)
    local ncol = DSP.theme.push_overlay(0.95)
    local open = imgui.new.bool(true)
    local flags = imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoMove
        + imgui.WindowFlags.NoSavedSettings
        + imgui.WindowFlags.NoFocusOnAppearing + imgui.WindowFlags.NoNav
    if imgui.Begin('##dsp_trade_overlay', open, flags) then
        local top_width=math.max(1,imgui.GetContentRegionAvail().x)
        overlay_drag_bar('ТРЕЙД  ' .. (t.partner ~= '' and t.partner or '?'),
            'trade',math.max(55,top_width-80*d()),44,'trade_pos')
        if close_btn('dsp_trade_close') then DSP.overlay.trade_closed = t.opened end
        imgui.TextDisabled(u('база: ' .. base_label()))
        imgui.Separator()

        local total_get, total_give, delta, pct, miss_get, miss_give, get_v, give_v = DSP.overlay.trade_sum()
        local ratio, mode = DSP.overlay.trade_ratio()
        local vc, vt = YELLOW, 'НОРМ'
        if miss_get + miss_give > 0 and total_get == 0 and total_give == 0 then
            vc, vt = GRAY, 'НЕТ БАЗЫ'
        elseif miss_get + miss_give > 0 and total_get == 0 then
            vc, vt = GRAY, 'НЕТ ЦЕНЫ ПОЛУЧАЕМОГО'
        elseif ratio then
            if ratio >= 1.10 then vc, vt = GREEN, 'ВЫГОДНО'
            elseif ratio < 0.90 then vc, vt = RED, 'НЕВЫГОДНО' end
        end
        imgui.TextColored(vc, u(vt .. (ratio and string.format('  %.0f%% рынка', ratio * 100) or '')))
        imgui.Text(u('Получаете: ' .. DSP.money(total_get) .. '   Отдаёте: ' .. DSP.money(total_give)))
        imgui.TextColored(delta >= 0 and GREEN or RED,
            u('Итог: ' .. (delta >= 0 and '+' or '') .. DSP.money(delta) .. string.format('  (%+.0f%%)', pct)))
        if (t.money_get or 0) > 0 and (t.money_give or 0) == 0 and give_v > 0 then
            local r = (t.money_get or 0) / give_v
            local c, s
            if r < 0.85 then c, s = RED, 'СКУП НИЖЕ РЫНКА'
            elseif r <= 1.10 then c, s = YELLOW, 'НОРМ ЦЕНА'
            else c, s = GREEN, 'ОВЕР - ВЫГОДНО ВАМ' end
            imgui.TextColored(c, u(string.format('Скуп: %.0f%% рынка - %s', r * 100, s)))
        elseif (t.money_give or 0) > 0 and (t.money_get or 0) == 0 and get_v > 0 then
            local r = (t.money_give or 0) / get_v
            local c, s
            if r < 0.85 then c, s = GREEN, 'ДЕШЕВО - БРАТЬ'
            elseif r <= 1.10 then c, s = YELLOW, 'НОРМ ЦЕНА'
            else c, s = RED, 'ОВЕР - ПЕРЕПЛАТА' end
            imgui.TextColored(c, u(string.format('Покупка: %.0f%% рынка - %s', r * 100, s)))
        end
        imgui.Separator()

        local avail=imgui.GetContentRegionAvail()
        local narrow=avail.x<440
        local half=math.max(55,math.floor((avail.x-8*d())/2))
        local child_width=narrow and -1 or half
        local h=math.max(70,math.min(230*d(),math.max(90,avail.y-(narrow and 100 or 55))))
        if narrow then h=math.max(70,math.floor(h*.54))end
        imgui.BeginChild('##dsp_trade_give', imgui.ImVec2(child_width, h), true)
        imgui.TextColored(RED, u('ВЫ ОТДАЁТЕ'))
        for _, it in ipairs(t.give or {}) do trade_item_row(it, 'give') end
        if (t.money_give or 0) > 0 then imgui.TextColored(RED, u('Деньги: -' .. DSP.money(t.money_give))) end
        if #(t.give or {}) == 0 and (t.money_give or 0) == 0 then imgui.TextDisabled(u('—')) end
        imgui.EndChild()
        if not narrow then imgui.SameLine(0, 8 * d())end
        imgui.BeginChild('##dsp_trade_get', imgui.ImVec2(child_width, h), true)
        imgui.TextColored(GREEN, u('ВЫ ПОЛУЧАЕТЕ'))
        for _, it in ipairs(t.get or {}) do trade_item_row(it, 'get') end
        if (t.money_get or 0) > 0 then imgui.TextColored(GREEN, u('Деньги: +' .. DSP.money(t.money_get))) end
        if #(t.get or {}) == 0 and (t.money_get or 0) == 0 then imgui.TextDisabled(u('—')) end
        imgui.EndChild()
        if miss_get + miss_give > 0 then
            imgui.TextColored(YELLOW, u('Нет базы: ' .. tostring(miss_get + miss_give) .. ' поз. - обнови рынок'))
        end
        if imgui.SmallButton(u('ОБНОВИТЬ БАЗУ##dsp_trade_refresh')) then
            DSP.market.pull(DSP.market.state.sid)
        end
    end
    capture_overlay('overlay_trade','trade_pos')
    imgui.End()
    imgui.PopStyleColor(ncol)
    if not open[0] then DSP.overlay.trade_closed = t.opened end
end

-- Only compare against OTHER shops. The current quote being included in
-- the market minimum caused false 'cheap at market price' endorsements.
-- Cache per live market snapshot and opened stall: never request network or
-- sort offers in each ImGui frame.
local quote_cache={}
function DSP.overlay.shop_market_reference(name,ench,shop_num,side)
    local st=DSP.market and DSP.market.state or {}
    local sid=tonumber(st.sid) or 0
    if sid<=0 or sid~=tonumber(DSP.settings.server) or st.status=='loading' then return nil end
    local snapshot=tostring(sid)..':'..tostring(st.version)..':'..tostring(DSP.live.shop.opened)..':'..tostring(math.floor(os.time()/60))
    if quote_cache.snapshot~=snapshot then quote_cache={snapshot=snapshot} end
    local item_key=DSP.item_key and DSP.item_key(name,ench) or tostring(name)..'|'..tostring(ench)
    local key=tostring(shop_num)..':'..tostring(side)..':'..item_key
    if quote_cache[key]~=nil then return quote_cache[key] or nil end
    local row=st.by_key and st.by_key[item_key]
    local offers=row and row[side] and row[side].offers or {}
    local prices,shops={},{}
    local now=os.time()
    local latest=0
    for _,o in ipairs(offers)do
        local t=tonumber(o.ts) or 0
        local price=tonumber(o.price) or 0
        if tostring(o.shop)~=tostring(shop_num) and price>0
            and t>0 and t<=now+60 and now-t<=600 then
            prices[#prices+1]=price;shops[tostring(o.shop)]=true
            if t>latest then latest=t end
        end
    end
    if #prices==0 then quote_cache[key]=false;return nil end
    table.sort(prices)
    local unique=0;for _ in pairs(shops)do unique=unique+1 end
    local n=#prices
    local median=n%2==1 and prices[(n+1)/2]
        or (prices[n/2]+prices[n/2+1])/2
    local reference={low=prices[1],high=prices[n],med=median,n=n,
        shops=unique,updated=latest}
    quote_cache[key]=reference
    return reference
end
local function evaluate_lavka(price,reference,side)
    if not reference then return GRAY,'НЕТ СВЕЖИХ ЧУЖИХ ЦЕН' end
    local median=reference.med or 0
    if median<=0 then return GRAY,'НЕТ СРАВНЕНИЯ' end
    if reference.shops<2 then
        return YELLOW,'МАЛО ДАННЫХ (1 ЛАВКА)'
    end
    -- Demand and supply are DIFFERENT quote series. Never treat one as a
    -- completed trade, or a favorable price as guaranteed stock/demand.
    if side=='sell' then
        if price<=median*.95 then return GREEN,'НИЖЕ ДРУГИХ >=5%'end
        if price<=median*1.05 then return YELLOW,'НА УРОВНЕ РЫНКА'end
        return RED,'ДОРОЖЕ ДРУГИХ'
    end
    if price>=median*1.05 then return GREEN,'СКУПАЕТ ДОРОЖЕ ДРУГИХ'end
    if price>=median*.95 then return YELLOW,'НА УРОВНЕ СКУПКИ'end
    return RED,'СКУПАЕТ ДЕШЕВЛЕ ДРУГИХ'
end
-- Receipt and recommendations are refreshed only when market evidence changes.
local shop_footer_cache={}
function DSP.overlay.shop_scan_footer(shop)
    local arb=DSP.local_arb
    local scan=DSP.live and DSP.live.auto_scan or {}
    local timestamp=os.time()
    local valid=tonumber(shop.num) and tostring(scan.shop)==tostring(shop.num)
        and tonumber(scan.server)==tonumber(shop.server)
        and tonumber(scan.generation)==tonumber(shop.generation)
        and tonumber(scan.at or 0)>=tonumber(shop.opened or math.huge)
    local scan_state,observed=DSP.live and DSP.live.scan_state and DSP.live.scan_state(shop)
    imgui.Separator()
    if valid and scan_state=='saved' then
        imgui.TextColored(GREEN,u('СКАН: УСПЕШНО  #'..tostring(shop.num)))
        imgui.TextDisabled(u('Продажа: '..tostring(scan.sell or 0)..' · Скупка: '..tostring(scan.buy or 0)))
        if arb and arb._dirty then
        imgui.TextDisabled(u('Ожидает записи базы на диск'))
        end
    elseif scan_state and scan_state~='pending' and scan_state~='saved' then
        local messages={
            disabled='Автоскан выключен. Включи его в «Мои сканы».',
            empty='Нет распознанных товаров в открытой лавке.',
            server='Сервер лавки не совпал с текущим сервером.',
            number='Товары прочитаны, но игра не передала номер лавки. В базу не сохранено.',
            owner='Номер есть, но имя владельца не распознано. В базу не сохранено.',
            error='Ошибка сохранения скана. Проверь standalone.log.',
            not_saved='Скан пока не подтверждён.',
        }
        imgui.TextDisabled(u(messages[scan_state] or messages.not_saved))
        imgui.TextDisabled(u('Распознано сейчас: '..tostring(observed or 0)))
    elseif DSP.settings.auto_shop_scan==false then
        imgui.TextDisabled(u('Автоскан выключен'))
    elseif DSP.live and DSP.live._auto_scan_pending then
        imgui.TextDisabled(u('Скан: получение товаров...'))
    else
        imgui.TextDisabled(u('Скан: нет подтверждения сохранения'))
    end
    local stats=arb and arb.stats and arb.stats(timestamp) or {shops=0,offers=0,server=0}
    imgui.TextDisabled(u('Мои сканы: '..tostring(stats.shops)..' лавок · '..tostring(stats.offers)..' предложений'))
    if scan_state~='saved' or not arb or not arb.routes then return end
    local sig=table.concat({tostring(stats.server),tostring(arb.revision or 0),
        tostring(math.floor(timestamp/30)),tostring(DSP.settings.tax_bp or 200),
        tostring(DSP.market and DSP.market.missing_revision or 0),tostring(shop.num)},':')
    if shop_footer_cache.sig~=sig then
        shop_footer_cache={sig=sig}
        for _,r in ipairs(arb.routes(timestamp))do
            if tostring(r.seller_shop)==tostring(shop.num)
                and (not shop_footer_cache.buy or r.profit_unit>shop_footer_cache.buy.profit_unit)then
                shop_footer_cache.buy=r
            end
            if tostring(r.buyer_shop)==tostring(shop.num)
                and (not shop_footer_cache.sell or r.profit_unit>shop_footer_cache.sell.profit_unit)then
                shop_footer_cache.sell=r
            end
        end
    end
    if shop_footer_cache.buy then
        local r=shop_footer_cache.buy
        imgui.TextColored(GREEN,u('Купить: '..tostring(r.name or ('ID '..tostring(r.id)))..
            ' · ~ +'..DSP.money(r.profit_unit)..'/шт. to #'..tostring(r.buyer_shop)))
    end
    if shop_footer_cache.sell then
        local r=shop_footer_cache.sell
        imgui.TextColored(GREEN,u('Продать: '..tostring(r.name or ('ID '..tostring(r.id)))..
            ' · ~ +'..DSP.money(r.profit_unit)..'/шт. from #'..tostring(r.seller_shop)))
    end
    if not shop_footer_cache.buy and not shop_footer_cache.sell then
        imgui.TextDisabled(u('Выгодных локальных связок пока нет'))
    end
    imgui.TextDisabled(u('Прогноз, не гарантированная прибыль'))
end
function DSP.overlay.draw_shop()
    refresh_palette()
    local s=DSP.live.shop
    local sw,sh=imgui.GetIO().DisplaySize.x,imgui.GetIO().DisplaySize.y
    local saved=DSP.overlay.shop_pos
    local w=math.min(sw-16,math.max(math.min(sw*.53,590*d()),math.min(sw-16,tonumber(saved and saved.w) or 340*d())))
    local h=math.min(sh-16,math.max(180,tonumber(saved and saved.h) or math.max(sh*.61,310*d())))
    overlay_next_pos('shop_pos',sw-10*d(),sh*.09,imgui.ImVec2(1,0),sw,sh,w,h)
    imgui.SetNextWindowSize(imgui.ImVec2(w,h),imgui.Cond.FirstUseEver)
    imgui.SetNextWindowBgAlpha(DSP.theme.opacity)
    local ncol=DSP.theme.push_overlay(.9)
    local open=imgui.new.bool(true)
    -- Window scroll remains enabled; resizing must never permanently hide controls.
    local flags=imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoMove
        +imgui.WindowFlags.NoSavedSettings+imgui.WindowFlags.NoFocusOnAppearing
    if imgui.Begin('##dsp_shop_overlay',open,flags)then
        local width=math.max(1,imgui.GetContentRegionAvail().x)
        local compact=width<430
        local close_width=compact and 60 or 130
        overlay_drag_bar('ЛАВКА #'..tostring(s.num or '?')..'  '..tostring(s.owner or '?'),
            'shop',math.max(55,width-close_width-12),44,'shop_pos')
        imgui.SameLine(0,8)
        if imgui.Button(u((compact and 'X' or 'ЗАКРЫТЬ X')..'##shop_close_big'),imgui.ImVec2(close_width,44))then
            DSP.overlay.shop_closed=s.opened
        end
        imgui.Separator()
        local sell_n,buy_n=#(s.sell or{}),#(s.buy or{})
        local bw=math.max(50,math.floor((imgui.GetContentRegionAvail().x-8)/2))
        if imgui.Button(u('ПРОДАЮТ ('..sell_n..')##shop_sell'),imgui.ImVec2(bw,54))then
            DSP.overlay.shop_tab=1;DSP.overlay.shop_page=1
        end
        imgui.SameLine(0,8)
        if imgui.Button(u('СКУПАЮТ ('..buy_n..')##shop_buy'),imgui.ImVec2(bw,54))then
            DSP.overlay.shop_tab=2;DSP.overlay.shop_page=1
        end
        imgui.TextDisabled(u('Снимок API не равен остатку в игре. Сравнение только с другими лавками.'))
        local list=DSP.overlay.shop_tab==1 and (s.sell or{})or(s.buy or{})
        if DSP.overlay.shop_last_open~=s.opened then
            DSP.overlay.shop_last_open=s.opened;DSP.overlay.shop_page=1
        end
        -- Cards have a predictable height; a page must not contain items
        -- hidden below the small child scroll region on a compact phone.
        local measured=imgui.GetWindowSize and imgui.GetWindowSize() or {x=w,y=h}
        local body=imgui.GetContentRegionAvail()
        -- Reserve screen space for navigation and receipt, with outer window scroll
        -- as a fallback on phones too small to display everything at once.
        local reserved=compact and 220 or 200
        local list_h=math.max(65,math.min(340*d(),measured.y*.43,math.max(75,body.y-reserved)))
        local per_page=math.max(1,math.floor(list_h/(compact and 136*d() or 114*d())))
        local pages=math.max(1,math.ceil(#list/per_page))
        DSP.overlay.shop_page=math.max(1,math.min(pages,DSP.overlay.shop_page or 1))
        if imgui.BeginChild('##dsp_shop_cards',imgui.ImVec2(-1,list_h),true)then
            if #list==0 then imgui.TextDisabled(u('Нет наблюдаемых позиций'))end
            for i=(DSP.overlay.shop_page-1)*per_page+1,math.min(#list,DSP.overlay.shop_page*per_page)do
                local it=list[i]
                local side=DSP.overlay.shop_tab==1 and 'sell'or'buy'
                local ref=DSP.overlay.shop_market_reference(it.name,it.ench,s.num,side)
                local color,verdict=evaluate_lavka(tonumber(it.price)or 0,ref,side)
                imgui.TextColored(color,u(verdict))
                local quantity=(it.qty_known==false or it.qty==nil)
                    and '  · кол-во неизвестно' or '  x'..tostring(it.qty)
                local name=u(DSP.item_name(it.name,it.ench)..quantity)
                if imgui.TextWrapped then imgui.TextWrapped(name)else imgui.Text(name)end
                imgui.TextColored(BLUE,u((side=='sell'and 'Вы покупаете: 'or'Вы продаёте: ')
                    ..DSP.money(it.price)..'/шт.'))
                if ref then
                    imgui.TextDisabled(u('Другие лавки: '..DSP.money(ref.low)..'–'..DSP.money(ref.high)
                        ..' · медиана '..DSP.money(ref.med)..' · '..ref.shops..' лавок'))
                else
                    imgui.TextDisabled(u('Свежих предложений других лавок нет'))
                end
                imgui.Separator()
            end
        end
        imgui.EndChild()
        if imgui.Button(u('<  НАЗАД##shop_page_prev'),imgui.ImVec2(bw,54))then
            DSP.overlay.shop_page=math.max(1,DSP.overlay.shop_page-1)
        end
        imgui.SameLine(0,8)
        if imgui.Button(u('ВПЕРЁД  >##shop_page_next'),imgui.ImVec2(bw,54))then
            DSP.overlay.shop_page=math.min(pages,DSP.overlay.shop_page+1)
        end
        imgui.TextDisabled(u('Страница '..DSP.overlay.shop_page..' / '..pages))
        if imgui.SmallButton(u('Обновить рынок##dsp_shop_refresh'))then
            DSP.market.pull(DSP.market.state.sid)
        end
        DSP.overlay.shop_scan_footer(s)
    end
    capture_overlay('overlay_shop','shop_pos')
    imgui.End()
    imgui.PopStyleColor(ncol)
    if not open[0]then DSP.overlay.shop_closed=s.opened end
end

function DSP.overlay.install()
    if DSP.overlay.installed then return end
    DSP.overlay.installed = true
    imgui.OnFrame(function()
        return DSP.overlay.show_trade() or DSP.overlay.show_shop()
    end, function()
        -- v1.2 hotfix: pcall so a bad imgui call doesn't crash the game.
        local ok, err = pcall(function()
            if DSP.overlay.show_trade() then DSP.overlay.draw_trade() end
            if DSP.overlay.show_shop() then DSP.overlay.draw_shop() end
        end)
        if not ok then
            if DSP and DSP.flog then
                DSP.flog('overlay frame error: ' .. tostring(err))
            end
        end
    end)
end

end
__mod_50_overlay()

local function __mod_54_payday_parse()
-- Conservative PayDay fields. A bank/deposit balance is evidence, never salary.
local function lower(s)return(DSP.lower or string.lower)(s)end
function DSP.payday_part(text)
    text=tostring(text or '')
    if text:find('%[%d+%]:')or text:match('^%s*%[')then return nil end
    local s=lower(text)
    local function has(word)return s:find(lower(word),1,true)end
    local metric=has('сумма в банке')and'bank'or has('сумма на депозите')and'deposit'
    if metric then
        local gain=text:match('%(%+%$?([%d%., ]+)%)')
        return{raw=text,amount=0,direction='meta',metric=metric,
            reported_gain=gain and tonumber((gain:gsub('[^%d]','')))or nil}
    end
    local expense=has('налог')or has('списано')or has('удержано')
    local income=has('зарплат')or has('заработная плата')or has('премия')or has('пенсия')or has('начислено')
    if not expense and not income then return nil end
    local raw=text:match('%$%s*([%d%., ]+)')or text:match('([%d][%d%., ]*)%s*%$')
    local amount=raw and tonumber((raw:gsub('[^%d]','')))
    if not amount then return nil end
    return{raw=text,amount=amount,direction=expense and'expense'or'income',metric=expense and'expense'or'salary'}
end

-- Explicit deposit growth is independent income; the bank gain mirrors salary.
function DSP.payday_contribution(part)
    part=part or {}
    if part.metric=='bank' then return 0,0 end
    if part.metric=='deposit' and part.direction=='meta' then
        return math.max(0,tonumber(part.reported_gain) or 0),0
    end
    local amount=tonumber(part.amount) or 0
    if part.direction=='income' then return amount,0 end
    if part.direction=='expense' then return 0,amount end
    return 0,0
end

-- Recalculate derived fields of legacy inline evidence without changing any detail.
function DSP.payday_restore(row)
    if not row.details or #row.details==0 then return row end
    local incoming,outgoing=0,0
    for _,part in ipairs(row.details) do
        local credited,debited=DSP.payday_contribution(part)
        incoming,outgoing=incoming+credited,outgoing+debited
    end
    row.income,row.expense=incoming,outgoing
    row.amount=incoming-outgoing
    return row
end

end
__mod_54_payday_parse()

local function __mod_55_craglog()
DSP.craglog = {ring={},ring_cap=300,ring_head=1,ring_count=0,scroll=0}
local C=DSP.craglog;C.session_started=(DSP.logs and DSP.logs.session_started) or os.time()
local revision, summary_cache=0,{}
local function settings()
    DSP.settings.craglog=DSP.settings.craglog or {open=false,pinned=false,minimized=false,filter='all'}
    return DSP.settings.craglog
end
local function persist() return DSP.save_settings() end
function C.clear_ring()
    C.ring,C.ring_head,C.ring_count,C.scroll={},1,0,0
    C.counters={trades=0,sales=0,buys=0,crates=0,profit=0}
end
C.clear_ring()
function C.ring_push(entry)
    if type(entry)~='table' then return end
    C.ring[C.ring_head]=entry
    C.ring_head=C.ring_head%C.ring_cap+1
    C.ring_count=math.min(C.ring_count+1,C.ring_cap)
end
function C.ring_recent(n)
    n=math.max(0,math.min(C.ring_count,math.floor(tonumber(n) or C.ring_count)))
    local out={}
    for i=0,n-1 do out[#out+1]=C.ring[(C.ring_head-n+i-1)%C.ring_cap+1] end
    return out
end
local function category(e)
    if e.type=='payday' or e.kind=='payday' then return 'payday' end
    if e.type=='market' then return e.direction=='sell' and 'sales' or 'buys' end
    if e.kind=='income' or e.type=='income' then return 'income' end
    if e.kind=='cash' then return 'income' end
    if e.kind=='item' or e.kind=='opening' or e.kind=='unknown' or e.type=='crate' then return 'loot' end
    if (tonumber(e.money_get) or 0)>0 and (tonumber(e.money_give) or 0)==0 then return 'sales' end
    if (tonumber(e.money_give) or 0)>0 and (tonumber(e.money_get) or 0)==0 then return 'buys' end
    return 'other'
end
function C.filtered(filter)
    local out={}
    for _,e in ipairs(C.ring_recent(C.ring_count)) do
        if (not C.event_visible or C.event_visible(e)) and (filter=='all' or category(e)==filter or (filter=='loot' and e.kind=='cash')) then out[#out+1]=e end
    end
    return out
end
local function append(path,line)
    DSP.mkdir_p(DSP.dir..'/logs')
    local f,err=io.open(path,'a')
    if not f then C.last_error=err; DSP.add_log('Журнал: '..tostring(err),'error'); return false,err end
    local wrote,write_err=f:write(line..'\n')
    local closed,close_err=f:close()
    if not wrote or not closed then
        C.last_error=write_err or close_err; DSP.add_log('Журнал: '..tostring(C.last_error),'error')
        return false,C.last_error
    end
    C.last_error=nil
    return true
end
function C.describe(e)
    if e.kind=='item' or e.type=='crate' then
        local value=(e.price_known and not (DSP.rewards and DSP.rewards.is_temporary and DSP.rewards.is_temporary(e))) and DSP.money(e.estimated_value or 0) or 'нет цены'
        local name=tostring(e.item_name or e.item or '?')
        if (tonumber(e.ench) or 0)>0 and not name:find('%(%+%d+%)$') then name=name..' (+'..e.ench..')' end
        return name..' x'..tostring(e.qty or e.count or 1)..' | Оценка: '..value
    elseif e.kind=='cash' then return 'Деньги: +'..DSP.money(e.cash or 0)
    elseif e.kind=='opening' then return 'Открытие: '..tostring(e.source or '?')
    elseif e.kind=='unknown' then return 'Награда: неизвестный тип | '..tostring(e.raw or '')
    elseif e.type=='payday' then return 'PayDay | '..(e.amount and ('Распознано: '..DSP.money(e.amount)) or 'Начисления не распознаны')
    elseif e.type=='income' then return tostring(e.label or 'Доход')..': +'..DSP.money(e.amount or 0)
    elseif e.type=='market' then
        return (e.direction=='sell' and 'Продажа: ' or 'Покупка: ')..tostring(e.item_name or '?')..' | '..(e.direction=='sell' and 'Выручка: +' or 'Расход: -')..DSP.money(e.amount or 0) end
    local parts={}
    for _,side in ipairs({{'items_give','Отдано'},{'items_get','Получено'}}) do
        for _,it in ipairs(e[side[1]] or {}) do parts[#parts+1]=side[2]..': '..tostring(it.name)..' x'..tostring(it.qty or 1) end
    end
    return tostring(e.partner or '?')..' | '..(#parts>0 and table.concat(parts,'; ')..' | ' or '')..(e.profit_estimated==false and 'Денежный итог: ' or 'Оценка обмена: ')..DSP.money(e.profit or 0)
end
local function store_event(e)
    if not e.id and e.type~='payday_detail' and C.new_event_id then e.id=C.new_event_id(e.ts) end
    DSP.mkdir_p(DSP.dir..'/logs')
    local ok,encoded=pcall(encodeJson,e)
    if not ok or type(encoded)~='string' then C.last_error='JSON encoding error';return false,C.last_error end
    local saved,err=append(DSP.events_log_path,'\n'..encoded)
    if saved then revision=revision+1; summary_cache={} end
    return saved,err
end
function C.log_trade(e)
    if type(e)~='table' then return false,'нет записи' end
    C.ring_push(e); C.counters.trades=C.counters.trades+1
    C.counters.profit=C.counters.profit+(tonumber(e.profit) or 0)
    local key=category(e); if C.counters[key] then C.counters[key]=C.counters[key]+1 end
    local ok,err=append(DSP.trades_log_path,os.date('%Y-%m-%d %H:%M:%S',e.ts or os.time())..' '..C.describe(e))
    local stored,store_err=store_event(e)
    if not ok then C.last_error=err;return false,err end
    return stored,store_err
end
function C.log_crate(e)
    if type(e)~='table' then return false,'нет записи' end
    if e.id then
        for _,row in ipairs(C.ring_recent(C.ring_count)) do if row.id==e.id then return true end end
    end
    local row={type='crate',kind='item',ts=e.ts or os.time(),id=e.id,
        item_name=e.item_name or e.item,ench=e.ench,qty=e.qty or e.count or 1,source=e.source or e.crate_type,
        price_known=e.price_known or (tonumber(e.price) or 0)>0,unit_price=e.unit_price or e.price,
        estimated_value=e.estimated_value or ((tonumber(e.price) or 0)*(tonumber(e.qty or e.count) or 1))}
    C.ring_push(row); C.counters.crates=C.counters.crates+1
    return append(DSP.crates_log_path,os.date('%Y-%m-%d %H:%M:%S',row.ts)..' '..C.describe(row))
end
local function payday_part(text)
    if DSP.payday_part then return DSP.payday_part(text)end
    local lower=DSP.lower or string.lower;local s=lower(text or '')
    local expense=s:find(lower('налог'),1,true) or s:find(lower('списано'),1,true) or s:find(lower('удержано'),1,true)
    local income=s:find(lower('зарплат'),1,true) or s:find(lower('заработная плата'),1,true) or s:find(lower('премия'),1,true)
        or s:find(lower('пенсия'),1,true) or s:find(lower('начислено'),1,true)
    if not expense and not income then return nil end
    local amount=s:match('%$%s*([%d%., ]+)') or s:match('([%d][%d%., ]*)%s*%$')
    amount=amount and tonumber((amount:gsub('[^%d]','')));if not amount then return nil end
    return {raw=text,amount=amount,direction=expense and 'expense' or 'income'}
end
local function apply_detail(row,part)
    row.details=row.details or {};row.details[#row.details+1]=part
    if DSP.payday_restore then DSP.payday_restore(row);return end
    row[part.direction]=(row[part.direction] or 0)+part.amount
    row.amount=(row.income or 0)-(row.expense or 0)
end
function C.log_payday(summary,raw)
    summary=summary or {};local ts=os.time()
    local row={type='payday',kind='payday',id=C.new_event_id and C.new_event_id(ts) or ('payday-'..ts..'-'..tostring(revision)),ts=ts,
        profit=summary.profit or 0,count=summary.count or 0,raw=raw,details={}}
    local part=payday_part(raw)
    if part then apply_detail(row,part) end
    C.ring_push(row);C.active_payday=row
    return store_event(row)
end
function C.observe_payday(text)
    local row=C.active_payday
    if not row or os.time()-row.ts>12 then return false end
    if row.raw==text then return false end
    local part=payday_part(text)
    if not part then return false end
    for _,old in ipairs(row.details or {}) do if old.raw==part.raw then return true end end
    local saved=store_event({type='payday_detail',payday_id=row.id,ts=os.time(),detail=part})
    if saved then apply_detail(row,part) end
    return true
end
function C.log_income(label,amount,raw)
    amount=math.floor(tonumber(amount) or 0)
    if amount <= 0 then return false,'сумма должна быть положительной' end
    local row={type='income',kind='income',ts=os.time(),amount=amount,label=label or 'Доход',raw=raw}
    C.ring_push(row)
    return store_event(row)
end
function C.log_market(direction,item,amount,raw)
    if direction~='sell' and direction~='buy' then return false,'сторона' end
    amount=math.floor(tonumber(amount) or 0)
    if amount<=0 then return false,'сумма' end
    local row={type='market',kind='market',ts=os.time(),direction=direction,
        item_name=item or '?',amount=amount,raw=raw}
    C.ring_push(row)
    return store_event(row)
end
function C.summary(period,now_ts)
    period=period or 'day';now_ts=now_ts or os.time()
    local from=period=='session' and C.session_started or 0
    if period=='day' then
        local date=os.date('*t',now_ts);date.hour,date.min,date.sec=0,0,0;from=os.time(date)
    end
    local key=period..':'..from..':'..revision..':'..tostring(C.visibility_revision or 0)..':'..tostring(DSP.logs and DSP.logs.revision or 0)..':'..tostring(DSP.rewards and DSP.rewards.sequence or 0)
    if summary_cache[key] then return summary_cache[key] end
    local out={count=0,income=0,expense=0,net=0,trade_profit=0,reward_cash=0,
        reward_estimated=0,unknown_items=0,payday_income=0,payday_expense=0,other_income=0}
    local f=io.open(DSP.events_log_path,'r')
    if f then
        for line in f:lines() do
            local ok,e=pcall(decodeJson,line)
            if ok and type(e)=='table' and (tonumber(e.ts) or 0)>=from and (not C.event_visible or C.event_visible(e)) then
                local incoming,outgoing=0,0
                if e.type=='market' then
                    if e.direction=='sell' then incoming=e.amount or 0 else outgoing=e.amount or 0 end
                elseif e.type=='income' then incoming=e.amount or 0;out.other_income=out.other_income+incoming
                elseif e.type=='payday' then
                    if DSP.payday_restore then DSP.payday_restore(e) end
                    incoming=e.income or 0;outgoing=e.expense or 0
                elseif e.type=='payday_detail' then
                    local part=e.detail or {}
                    if DSP.payday_contribution then incoming,outgoing=DSP.payday_contribution(part)
                    elseif part.direction=='income' then incoming=part.amount or 0
                    elseif part.direction=='expense' then outgoing=part.amount or 0 end
                end
                if e.type=='payday' or e.type=='payday_detail' then
                    out.payday_income=out.payday_income+incoming;out.payday_expense=out.payday_expense+outgoing
                end
                if e.type~='trade' and e.type~='payday_detail' then out.count=out.count+1 end
                out.income=out.income+incoming;out.expense=out.expense+outgoing
            end
        end
        f:close()
    end
    local trades=C.visible_trades and C.visible_trades(period,from) or (DSP.logs and DSP.logs.profit_summary and DSP.logs.profit_summary(period))
    if trades then
        out.count=out.count+trades.count;out.trade_profit=trades.profit
        out.income=out.income+(trades.cash_get or 0);out.expense=out.expense+(trades.cash_give or 0)
    end
    if DSP.rewards and DSP.rewards.summary then
        local rewards=DSP.rewards.summary({from_ts=from})
        out.reward_cash=rewards.cash;out.reward_estimated=rewards.estimated_value;out.unknown_items=rewards.unknown_items
        out.income=out.income+rewards.cash;out.count=out.count+(rewards.events or 0)
    end
    out.net=out.income-out.expense;summary_cache[key]=out
    return out
end
function C.visible() return settings().open==true end
function C.toggle() local s=settings(); s.open=not s.open; persist() end
function C.set_pinned(value)
    local s=settings(); s.pinned=value==true
    if s.pinned then s.open=true end
    persist()
end
function C.set_minimized(value) settings().minimized=value==true; persist() end
function C.set_anchor(x,y) local s=settings();s.x,s.y=tonumber(x) or 20,tonumber(y) or 120;persist() end
function C.drag(dx,dy)
    local s=settings(); if s.pinned then return false end
    local g=C.active_geometry
    s.x,s.y=(g and g.x or s.x or 24)+dx,(g and g.y or s.y or 120)+dy
    if g then s.x=math.max(8,math.min(s.x,g.max_x)); s.y=math.max(8,math.min(s.y,g.max_y)) end
    C.drag_dirty=true
    return true
end
function C.end_drag() if C.drag_dirty then persist(); C.drag_dirty=false end end
function C.geometry(sw,sh)
    local s=settings()
    local default_w=math.min(700,sw*.45)
    local default_h=math.min(620,sh*.69)
    local w=math.max(360,math.min(tonumber(s.w) or default_w,math.max(360,sw-16)))
    local expanded=math.max(280,math.min(tonumber(s.h) or default_h,math.max(280,sh-16)))
    local x=math.max(8,math.min(tonumber(s.x) or 24,math.max(8,sw-w-8)))
    local y=math.max(8,math.min(tonumber(s.y) or 120,math.max(8,sh-expanded-8)))
    return {x=x,y=y,w=w,h=s.minimized and 84 or expanded,touch=54,
        max_x=math.max(8,sw-w-8),max_y=math.max(8,sh-expanded-8)}
end
function C.remember_size(w,h)
    local s=settings(); if s.minimized then return false end
    w=math.floor((tonumber(w) or 0)+0.5);h=math.floor((tonumber(h) or 0)+0.5)
    if w<360 or h<280 then return false end
    if math.abs((tonumber(s.w) or 0)-w)<1 and math.abs((tonumber(s.h) or 0)-h)<1 then return false end
    s.w,s.h=w,h;C.size_dirty=true;return true
end
function C.end_resize()
    if C.size_dirty and not imgui.GetIO().WantCaptureMouse then
        -- Some MonetLoader builds clear WantCaptureMouse one frame after release.
        persist();C.size_dirty=false
    elseif C.size_dirty and not imgui.IsMouseDown(0) then
        persist();C.size_dirty=false
    end
end
if DSP.rewards and not DSP.rewards._mini_wrapped then
    local record=DSP.rewards.record
    DSP.rewards.record=function(row)
        local saved,err=record(row)
        if saved then
            local C=DSP.craglog
            revision=revision+1;summary_cache={}
            if row.kind=='association' then
                local ids={}; for _,id in ipairs(row.item_ids or {}) do ids[id]=true end
                for _,entry in ipairs(C.ring_recent(C.ring_count)) do
                    if ids[entry.id] then
                        entry.source,entry.association,entry.opening_id=row.source,'inferred',row.opening_id
                    end
                end
            elseif not row.legacy_id then
                local copy={}; for k,v in pairs(row) do copy[k]=v end
                C.ring_push(copy)
            end
        end
        return saved,err
    end
    DSP.rewards._mini_wrapped=true
end
function C.install()
    if C.installed then return end
    C.installed=true;local restored={}
    local f=io.open(DSP.events_log_path,'r')
    if f then local history={}
        for line in f:lines() do
            if line~='' then
                local ok,row=pcall(decodeJson,line)
                if ok and type(row)=='table' and row.type and row.type~='journal_deleted' then
                    history[#history+1]=row
                    if #history>C.ring_cap then table.remove(history,1) end
                end
            end
        end
        f:close()
        local markers={}
        for _,e in ipairs(history) do
            if e.type=='payday_detail' then
                if markers[e.payday_id] and e.detail then apply_detail(markers[e.payday_id],e.detail) end
            else
                if e.type=='payday' and DSP.payday_restore then DSP.payday_restore(e) end
                restored[#restored+1]=e
                if e.type=='payday' and e.id then markers[e.id]=e end
            end
        end
    end
    if DSP.rewards and DSP.rewards.query then
        local result=DSP.rewards.query({page_size=80})
        for i=#result.entries,1,-1 do restored[#restored+1]=result.entries[i] end
    end
    table.sort(restored,function(a,b) return (tonumber(a.ts) or 0)<(tonumber(b.ts) or 0) end)
    for _,e in ipairs(restored) do C.ring_push(e) end
    if sampRegisterChatCommand then sampRegisterChatCommand('crlog',C.toggle) end
    imgui.OnFrame(C.visible,function()
        local ok,err=pcall(C.draw)
        if not ok then
            C.last_error=tostring(err); DSP.flog('mini journal: '..tostring(err))
