local function u(s)return DSP.utf8(tostring(s or ''))end
-- Keep controls from escaping the right side of narrow windows. A SameLine
-- is only allowed if there is room for the next touch target.
function V.inline(gap,next_width)
    local room=imgui.GetContentRegionAvail and imgui.GetContentRegionAvail().x or 9999
    if room >= (next_width or 100) then imgui.SameLine(0,gap or 6) end
end
function V.compact(width) return (tonumber(width) or (imgui.GetContentRegionAvail().x)) < 430 end
-- Responsive action flow; prevents the buttons in toolbars disappearing offscreen.
function V.actions(items)
    local total=math.max(1,imgui.GetContentRegionAvail().x)
    local room,first=total,true
    local result={}
    for i,a in ipairs(items) do
        local desired=a.width or 110
        local width=math.max(60,math.min(desired,total))
        if not first and room < width+8 then
            room=total
        elseif not first then
            imgui.SameLine(0,6)
        end
        local hit=V.button(a.label,a.id,width,a.active,a.primary,a.height)
        if hit then result[a.id]=true end
        room=math.max(0,imgui.GetContentRegionAvail().x)
        first=false
    end
    return result
end
function V.text(s)imgui.Text(u(s))end
function V.muted(s)imgui.TextDisabled(u(s))end
function V.green(s)imgui.TextColored(DSP.theme.col('good',1),u(s))end
function V.red(s)imgui.TextColored(DSP.theme.col('bad',1),u(s))end
-- Measure overflowing text with binary search, not one full ImGui text
-- measurement per removed character on every frame. A bounded cache is
-- keyed by font size and available width for rotation/theme changes.
local fit_cache,fit_cache_size={},0
function V.fit(s,width)
    s=tostring(s or '')
    if not imgui.CalcTextSize then return s end
    width=math.max(1,tonumber(width) or 1)
    local font=imgui.GetFontSize and imgui.GetFontSize() or (V.font_pixels or 18)
    local key=s..'\0'..tostring(math.floor(width*10))..':'..tostring(math.floor(font*10))
    local hit=fit_cache[key]
    if hit~=nil then return hit end
    local result=s
    if imgui.CalcTextSize(u(s)).x>width then
        local lo,hi=0,#s
        while lo<hi do
            local mid=math.floor((lo+hi+1)/2)
            if imgui.CalcTextSize(u(s:sub(1,mid)..'...')).x<=width then lo=mid
            else hi=mid-1 end
        end
        result=s:sub(1,lo)..'...'
    end
    if fit_cache_size>=256 then fit_cache={};fit_cache_size=0 end
    fit_cache[key]=result;fit_cache_size=fit_cache_size+1
    return result
end
function V.button(label,id,width,active,primary,height)
    if active or primary then imgui.PushStyleColor(imgui.Col.Button,DSP.theme.col('accent',primary and 1 or .30))end
    if primary then imgui.PushStyleColor(imgui.Col.Text,DSP.theme.col('bg',1))end
    local avail=imgui.GetContentRegionAvail().x
    local w=width or -1
    if w>0 then w=math.max(1,math.min(w,avail)) end
    local visible=label
    if w>0 then visible=V.fit(label,math.max(1,w-16))end
    local hit=imgui.Button(u(visible)..'##v22_'..id,imgui.ImVec2(w,height or 42))
    if primary then imgui.PopStyleColor(1)end
    if active or primary then imgui.PopStyleColor(1)end
    -- A finger that moved to scroll must not activate the row on release.
    return hit and not V.dragged
end
function V.text_button(label,id,width,active,height)
    imgui.PushStyleColor(imgui.Col.Button,imgui.ImVec4(0,0,0,0))
    imgui.PushStyleVarVec2(imgui.StyleVar.ButtonTextAlign,imgui.ImVec2(.02,.5))
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding,imgui.ImVec2(8,0))
    local hit=V.button(label,id,width,active,false,height)
    imgui.PopStyleVar(2);imgui.PopStyleColor(1)
    return hit
end
function V.apply_font(pixels)
    if not imgui.SetWindowFontScale then return end
    -- A child inherits its ancestors' scales in native ImGui. Reset its local
    -- multiplier, measure that inherited size, then apply only the missing ratio.
    imgui.SetWindowFontScale(1)
    local inherited=imgui.GetFontSize and imgui.GetFontSize()or 16
    imgui.SetWindowFontScale((pixels or V.font_pixels or 18)/math.max(1,inherited))
end
function V.heading(title,right,width)
    local x,y=imgui.GetCursorPosX(),imgui.GetCursorPosY()
    local avail=imgui.GetContentRegionAvail().x
    V.apply_font((V.font_pixels or 18)*1.13)
    V.text(title)
    V.apply_font()
    local second=right and avail<(width or 0)+128
    if right then
        V.at(second and x or x+math.max(0,avail-(width or 0)),second and y+43 or y)
        right()
    end
    V.at(x,y+(second and 91 or 46))
end
function V.search(key,hint,width)
    local b=V.searches[key]
    if not b then b=imgui.new.char[160]();V.searches[key]=b end
    imgui.SetNextItemWidth(width or -1)
    local edited=imgui.InputTextWithHint('##v22_query_'..key,u(hint),b,160)
    if edited then V.reset_list(key)end
    return DSP.trim(DSP.to_cp(ffi.string(b))),edited
end
function V.memo(key,signature,build)
    local c=V.cache[key]
    if not c or c.signature~=signature then c={signature=signature,value=build()};V.cache[key]=c end
    return c.value
end
function V.reset_list(key)V.scrolls[key]={pending=0,reset=true,y=0}end
function V.queue_scroll(key,direction,height)
    local s=V.scrolls[key] or {y=0};V.scrolls[key]=s
    s.pending=(s.pending or 0)+direction*math.max(96,math.floor((height or s.height or 260)*.75))
end
local function arrow(key,up)
    local p=imgui.GetCursorScreenPos and imgui.GetCursorScreenPos()
    local draw=p and imgui.GetWindowDrawList and imgui.GetColorU32
    local hit=V.button(draw and '' or (up and '^' or 'v'),(up and 'scroll_up_'or'scroll_down_')..key,60)
    if draw then
        local x,y=p.x+30,p.y+21;local d=up and -1 or 1
        imgui.GetWindowDrawList():AddTriangleFilled(imgui.ImVec2(x-8,y-d*4),
            imgui.ImVec2(x+8,y-d*4),imgui.ImVec2(x,y+d*7),imgui.GetColorU32(imgui.Col.Text))
    end
    return hit
end
function V.scroll_buttons(key)
    local s=V.scrolls[key] or {}
    if imgui.PushButtonRepeat then imgui.PushButtonRepeat(true)end
    if arrow(key,true)then V.queue_scroll(key,-1,s.height)end
    V.inline()
    if arrow(key,false)then V.queue_scroll(key,1,s.height)end
    if imgui.PopButtonRepeat then imgui.PopButtonRepeat()end
end

function V.visible_range(count,row_height,scroll,height)
    local first=math.max(1,math.floor(scroll/row_height))
    return first,math.min(count,math.ceil((scroll+height)/row_height)+2)
end
function V.list(key,draw,options)
    V.track_touch(imgui.GetIO())
    local o=options or {};local footer=o.footer~=false
    local avail=imgui.GetContentRegionAvail()
    local reserved=footer and (o.footer_height or 50) or 0
    local max_height=math.max(30,avail.y-reserved)
    local h=o.height and o.height>0 and math.min(o.height,max_height) or max_height
    local s=V.scrolls[key] or {pending=0,y=0};V.scrolls[key]=s;s.height=h
    local flags=imgui.WindowFlags.NoScrollbar
    if imgui.BeginChild('##v22_list_'..key,imgui.ImVec2(0,h),false,flags)then
        V.apply_font()
        if s.reset then imgui.SetScrollY(0);s.reset=false end
        if (s.pending or 0)~=0 then
            imgui.SetScrollY(DSP.clamp((imgui.GetScrollY()or 0)+s.pending,0,imgui.GetScrollMaxY()or 0));s.pending=0
        end
        s.y=imgui.GetScrollY()or 0
        local ok,err=xpcall(function()draw(imgui.GetContentRegionAvail().x,h,s.y)end,debug.traceback)
        if not ok then imgui.EndChild();error(err,0)end
        if M.touch_scroll then M.touch_scroll(imgui.GetIO(),'v22_'..key)end
    end
    imgui.EndChild()
    if footer then
        imgui.Separator()
        if o.toolbar then o.toolbar(key)else
            V.scroll_buttons(key)
            if type(o.footer)=='function'then V.inline();o.footer()
            elseif o.count then V.inline();V.muted(tostring(o.count)..' записей')end
        end
    end
end
function V.list_rows(key,rows,row_height,draw,options)
    V.list(key,function(w,h,y)
        local first,last=V.visible_range(#rows,row_height,y,h)
        local start=imgui.GetCursorPosY()
        -- Cursor positioning preserves a full virtual extent without drawing hidden rows.
        for i=first,last do
            imgui.SetCursorPosY(start+(i-1)*row_height)
            draw(rows[i],i,w)
        end
        imgui.SetCursorPosY(start+#rows*row_height)
        imgui.Dummy(imgui.ImVec2(1,1))
        if #rows==0 then imgui.SetCursorPosY(start);V.muted('Нет записей')end
    end,options)
end
function V.row(id,height,draw)
    local x,y=imgui.GetCursorPosX(),imgui.GetCursorPosY()
    local w=imgui.GetContentRegionAvail().x
    if imgui.GetWindowDrawList and imgui.GetCursorScreenPos and imgui.GetColorU32 then
        local p=imgui.GetCursorScreenPos()
        local custom=DSP.carbon_draw and DSP.carbon_draw.row and DSP.carbon_draw.row(p.x,p.y,w,height-4)
        if not custom then
            local dl=imgui.GetWindowDrawList()
            dl:AddRectFilled(p,imgui.ImVec2(p.x+w,p.y+height-4),imgui.GetColorU32(imgui.Col.FrameBg),6)
            if dl.AddRect then dl:AddRect(p,imgui.ImVec2(p.x+w,p.y+height-4),imgui.GetColorU32(imgui.Col.Border),6)end
        end
    end
    imgui.PushIDStr(id);imgui.SetCursorPos(imgui.ImVec2(x+8,y+5))
    local ok,err=xpcall(function()draw(w-16,x+8,y+5)end,debug.traceback)
    imgui.PopID();if not ok then error(err,0)end;imgui.SetCursorPos(imgui.ImVec2(x,y+height))
end
function V.at(x,y)imgui.SetCursorPos(imgui.ImVec2(x,y))end
-- One consistent window chrome for every modal: close at the top-right.
-- A modal can always be dismissed without traversing a sequence of Back buttons.
-- Keep the native ImGui resize grip enabled (NoResize is intentionally absent).
V.popup_positions=V.popup_positions or {}
function V.popup(title,id,draw,size)
    size=size or {}
    local io=imgui.GetIO()
    local sz=io.DisplaySize
    DSP.settings.ui_windows=DSP.settings.ui_windows or {}
    V.popup_sizes=V.popup_sizes or {}
    local saved=DSP.settings.ui_windows[id]
    local current=V.popup_positions[id]
    if not current and type(saved)=='table' and tonumber(saved.x) and tonumber(saved.y) then
        current={x=tonumber(saved.x),y=tonumber(saved.y)}
        V.popup_positions[id]=current
        if tonumber(saved.w) and tonumber(saved.h) then V.popup_sizes[id]={w=tonumber(saved.w),h=tonumber(saved.h)} end
    end
    if current then
        -- Keep a dragged popup visible after resolution/orientation changes.
        local live=V.popup_sizes and V.popup_sizes[id] or nil
        local w=math.min((live and live.w) or size.w or 620,sz.x-16)
        local h=math.min((live and live.h) or size.h or 410,sz.y-16)
        current.x=DSP.clamp(current.x,0,math.max(0,sz.x-w))
        current.y=DSP.clamp(current.y,0,math.max(0,sz.y-h))
        imgui.SetNextWindowPos(imgui.ImVec2(current.x,current.y),imgui.Cond.Always)
    else
        imgui.SetNextWindowPos(imgui.ImVec2(sz.x*.5,sz.y*.5),imgui.Cond.Appearing,imgui.ImVec2(.5,.5))
    end
    local remembered=V.popup_sizes[id]
    local initial_w=math.min((remembered and remembered.w) or size.w or 620,sz.x-24)
    local initial_h=math.min((remembered and remembered.h) or size.h or 410,sz.y-24)
    imgui.SetNextWindowSize(imgui.ImVec2(initial_w,initial_h),imgui.Cond.Appearing)
    -- Native overflow scrolling stays enabled, including on resized small
    -- popups. Window motion itself is still restricted to the title strip.
    if imgui.SetNextWindowSizeConstraints then
        imgui.SetNextWindowSizeConstraints(imgui.ImVec2(math.min(230,sz.x-16),math.min(165,sz.y-16)),
            imgui.ImVec2(math.max(230,sz.x-8),math.max(165,sz.y-8)))
    end
    local flags=imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoMove
    if imgui.BeginPopupModal(u(title)..'##v22_'..id,nil,flags)then
        if imgui.GetWindowSize then
            local actual=imgui.GetWindowSize()
            local native=imgui.GetWindowPos and imgui.GetWindowPos() or current
            V.popup_sizes[id]={w=actual.x,h=actual.y}
            if native and not V.popup_positions[id] then V.popup_positions[id]={x=native.x,y=native.y} end
            local pos=V.popup_positions[id] or native
            if pos then
                local prev=DSP.settings.ui_windows[id] or {}
                if math.abs((tonumber(prev.x)or-99999)-pos.x)>.5 or math.abs((tonumber(prev.y)or-99999)-pos.y)>.5
                    or math.abs((tonumber(prev.w)or-99999)-actual.x)>.5 or math.abs((tonumber(prev.h)or-99999)-actual.y)>.5 then
                    DSP.settings.ui_windows[id]={x=pos.x,y=pos.y,w=actual.x,h=actual.y}
                    if M and M.defer_save then M.defer_save() end
                end
            end
        end
        V.apply_font()
        local x,y=imgui.GetCursorPosX(),imgui.GetCursorPosY()
        local avail=imgui.GetContentRegionAvail().x
        -- Only this title strip can drag the popup. The invisible/native
        -- window drag mechanism stays disabled via NoMove.
        V.text_button(V.fit(title,math.max(60,avail-60)),'modal_drag_'..id,math.max(60,avail-52),false,36)
        if imgui.IsItemActive() and io.MouseDelta and imgui.GetWindowPos and imgui.GetWindowSize then
            local d=io.MouseDelta
            if d.x~=0 or d.y~=0 then
                local pos,wh=imgui.GetWindowPos(),imgui.GetWindowSize()
                V.popup_positions[id]={
                    x=DSP.clamp(pos.x+d.x,0,math.max(0,sz.x-wh.x)),
                    y=DSP.clamp(pos.y+d.y,0,math.max(0,sz.y-wh.y))}
            end
        end
        -- Position independent of the previous widgets; old 'Закрыть' buttons remain
        -- for compatibility, but every modal gets exactly the same close affordance.
        V.at(x+math.max(0,avail-42),y)
        local close=V.button('X','modal_x_'..id,40,false,false,34)
        V.at(x,y+39)
        imgui.Separator()
        if close then
            imgui.CloseCurrentPopup()
        elseif size.resizable then
            V.list('modal_'..id,function()draw()end,{footer=true})
        else
            draw()
        end
        imgui.EndPopup()
    end
end
function V.open_popup(title,id)
    -- Open and Begin must share an ImGui ID stack, even for a row inside a child.
    V.popup_pending={title=title,id=id}
end
function V.cancel(id)
    if V.button('Отмена','cancel_'..id,120)then imgui.CloseCurrentPopup()end
end
function V.geometry(sw,sh)
    local p=DSP.settings.mobile_window or {}
    local w=DSP.clamp(tonumber(p.w)or math.min(sw*.93,1120),math.min(sw,380),sw)
    local h=DSP.clamp(tonumber(p.h)or sh*.88,math.min(sh,275),sh)
    return {w=w,h=h,x=DSP.clamp(tonumber(p.x)or (sw-w)*.5,0,math.max(0,sw-w)),
        y=DSP.clamp(tonumber(p.y)or (sh-h)*.35,0,math.max(0,sh-h))}
end
local nav={{'palatka','Торговля'},{'lavki','Лавки'},{'storage','Хранилища'},
 {'arbitrage','Арбитраж'},{'resale','Перепродажа'},{'promo','Автопиар'},
 {'scan','Скан лавки'},{'search','Поиск товара'},{'calculator','Калькулятор'},
 {'logs','Журнал'},{'stats','Статистика'},{'notes','Заметки'},
 {'market','Рынок'},{'lombard','Ломбард'},{'history','История'},{'settings','Настройки'}}
function V.set_screen(id)
    if U._notes_dirty and M.save_notes and not M.save_notes()then return false end
    if id=='storage' then
        -- Never strand the user on the legacy manual "Save" page on entry.
        V.storage_tab='scan'
        V.storage_scan_mode=V.storage_scan_mode or 'trunk'
        V.reset_list('storage_scan_panel')
    end
    V.screen=id;V.nav=false
    if DSP.screens and DSP.screens.set then DSP.screens.set(id)end
end
local function header(g,io)
    local x0,y0=imgui.GetCursorPosX(),imgui.GetCursorPosY()
    -- Absolute positions: the global X never escapes the right edge, even when
    -- the server label becomes long or the user narrows the window.
    local close_x=g.w-56
    local menu_x=close_x-85
    if V.button('P','carbon_brand',40,false,true,36)then V.set_screen('home')end
    V.at(x0+47,y0)
    local title_width=math.max(65,math.min(155,menu_x-(x0+47)-8))
    if V.text_button(g.w<540 and 'AI / MOVE' or 'PALATKA AI / MOVE','carbon_title',title_width,false,36)then V.set_screen('home')end
    if imgui.IsItemActive() and io.MouseDelta then
        local d=io.MouseDelta
        if d.x~=0 or d.y~=0 then
            DSP.settings.mobile_window={x=DSP.clamp(g.x+d.x,0,io.DisplaySize.x-g.w),
                y=DSP.clamp(g.y+d.y,0,io.DisplaySize.y-g.h),w=g.w,h=g.h}
            M.defer_save()
        end
    end
    if g.w>=630 then V.at(x0+207,y0+11);V.muted('v'..tostring(DSP.version or '2.2'))end
    if g.w>850 then
        V.at(math.max(x0+240,menu_x-244),y0+11)
        V.muted(V.fit('Arizona #'..tostring(DSP.market.state.sid or '?')..' · '..DSP.market.freshness(),230))
    end
    V.at(menu_x,y0)
    if V.button('Меню','menu',78,V.nav,false,36)then V.nav=not V.nav end
    V.at(close_x,y0)
    if V.button('X','close',40,false,false,36)then
        U.set_open(false)
    end
    V.at(x0,y0+44)
end
-- A real bottom-right drag handle: unlike the old top-bar [] button, it follows
-- the edge being resized. No native overlay, no FFI pointer arithmetic.
function V.resize_grip(g,io)
    local x,y=g.w-46,g.h-44
    V.at(x,y)
    local pos=imgui.GetCursorScreenPos and imgui.GetCursorScreenPos()
    V.button(' ','global_resize_grip',32,false,false,31)
    if pos and imgui.GetWindowDrawList and imgui.GetColorU32 then
        local dl=imgui.GetWindowDrawList()
        local col=imgui.GetColorU32(imgui.Col.Text)
        for i=0,2 do
            dl:AddLine(imgui.ImVec2(pos.x+15+i*5,pos.y+25),
                imgui.ImVec2(pos.x+27,pos.y+13+i*5),col,1.6)
        end
    end
    if imgui.IsItemActive() and io.MouseDelta then
        local d=io.MouseDelta
        if d.x~=0 or d.y~=0 then
            local w=DSP.clamp(g.w+d.x,math.min(380,io.DisplaySize.x),io.DisplaySize.x-g.x)
            local h=DSP.clamp(g.h+d.y,math.min(275,io.DisplaySize.y),io.DisplaySize.y-g.y)
            DSP.settings.mobile_window={x=g.x,y=g.y,w=w,h=h}
            M.defer_save()
        end
    end
end
function V.track_touch(io)
    local frame=imgui.GetFrameCount and imgui.GetFrameCount()
    if frame and V.touch_frame==frame then return end
    V.touch_frame=frame
    local down=io.MouseDown and io.MouseDown[0]
    if down then
        if not V.was_down then V.travel=0;V.dragged=false end
        local delta=io.MouseDelta or {x=0,y=0}
        V.travel=(V.travel or 0)+math.abs(delta.y)+math.abs(delta.x)
        V.dragged=V.travel>10
    elseif not V.was_down then V.dragged=false end
    V.was_down=down
end
function V.font_scale_for(base,width,dpi)
    return 18*(tonumber(dpi)or 1.25)/1.25*math.min(1.35,math.max(.80,width/850))/math.max(1,base)
end
function U.draw()
    if DSP.carbon_draw then DSP.carbon_draw.begin_frame() end
    local io=imgui.GetIO();local sz=io.DisplaySize;local g=V.geometry(sz.x,sz.y)
    if not V.initialized then V.screen=(U.screen and U.screen~='palatka') and U.screen or 'home';V.initialized=true end
    V.track_touch(io)
    imgui.SetNextWindowPos(imgui.ImVec2(g.x,g.y),imgui.Cond.Always)
    imgui.SetNextWindowSize(imgui.ImVec2(g.w,g.h),imgui.Cond.Always)
    local colors=DSP.theme.push_window()
    imgui.SetNextWindowBgAlpha(DSP.theme.opacity or .97)
    if not V.style_reported and imgui.GetStyle then
        local c=imgui.GetStyle().Colors[imgui.Col.WindowBg]
        if c then DSP.flog(string.format('UI22 native bg %.3f %.3f %.3f %.3f colors=%d',c.x,c.y,c.z,c.w,colors or 0))end
        V.style_reported=true
    end
    imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding,imgui.ImVec2(9,7))
    imgui.PushStyleVarVec2(imgui.StyleVar.ItemSpacing,imgui.ImVec2(6,5))
    imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding,imgui.ImVec2(8,10))
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding,5)
    imgui.PushStyleVarFloat(imgui.StyleVar.FrameRounding,5)
    local flags=imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.NoMove+
        imgui.WindowFlags.NoSavedSettings+imgui.WindowFlags.NoScrollbar+(imgui.WindowFlags.NoScrollWithMouse or 0)
    M.flush_save(false)
    if imgui.Begin('##palatka_mobile',U.open_ref,flags)then
        -- Shared native atlases differ between loaders; normalize actual pixels.
        V.font_pixels=V.font_scale_for(1,g.w,U.d)
        V.apply_font()
        header(g,io);imgui.Separator()
        local wide=g.w>=650
        local show_side=V.nav or wide
        local drawer_only=V.nav and not wide
        if show_side then
            local h=math.max(30,imgui.GetContentRegionAvail().y-48)
            if imgui.BeginChild('##v22_carbon_nav',imgui.ImVec2(drawer_only and 0 or math.min(182,g.w*.25),h),true,imgui.WindowFlags.NoScrollbar)then
                V.apply_font()
                V.muted('НАВИГАЦИЯ')
                if V.button('Главная','carbon_home_nav',-1,V.screen=='home',V.screen=='home',43)then V.set_screen('home')end
                V.list_rows('navigation',nav,44,function(e,i)
                    local symbols={palatka='= ',lavki='# ',arbitrage='> ',resale='* ',promo='@ ',scan='[] ',
                        search='? ',calculator='+ ',logs='| ',stats='% ',notes='- ',storage='[] ',market='$ ',history=': ',settings=': '}
                    if V.button((symbols[e[1]] or ' ')..e[2],'nav_'..i,-1,V.screen==e[1],V.screen==e[1],42)then V.set_screen(e[1])end
                end,{height=math.max(70,imgui.GetContentRegionAvail().y-85),footer=true})
                if imgui.GetContentRegionAvail().y>25 then V.muted('  PALATKA AI · LIVE')end
            end
            imgui.EndChild()
            if not drawer_only then V.inline(4)end
        end
        if not drawer_only then
            -- Workspace and global footer are separate, as in the supplied Carbon HTML.
            if imgui.BeginChild('##v22_workspace',imgui.ImVec2(0,-48),false,0)then
                V.apply_font()
                local ok,err=xpcall(function()
                    if V.screen=='home'then V.home()
                    elseif V.screen=='storage'then V.storage_screen()
                    elseif V.screen=='scan'then V.shops_source='scan';V.shops()
                    elseif V.screen=='market'then V.shops_source='api';V.shops()
                    elseif V.screen=='history'then V.journal_mode='events';V.journal()
                    elseif V.screen=='palatka'then V.trade()
                    elseif V.screen=='lavki'then V.shops()
                    elseif V.screen=='arbitrage'then V.arbitrage()
                    elseif V.screen=='resale'then V.flip_screen()
                    elseif V.screen=='promo'then V.promo_screen()
                    elseif V.screen=='logs'then V.journal()
                    elseif V.screen=='calculator'then V.calculator()
                    elseif V.tools then V.tools(V.screen)
                    else DSP.screens.draw(V.screen)end
                end,debug.traceback)
                if not ok then
                    V.last_error=err
                    if V.errors[V.screen]~=err then DSP.flog('UI22 '..err)end
                    V.errors[V.screen]=err;V.red('Ошибка экрана. Подробности в standalone.log')
                end
            end
            imgui.EndChild()
            imgui.Separator()
            if V.button('Окна','carbon_windows',100,false,true,38)then V.nav=not V.nav end
            V.inline()
            local remain=imgui.GetContentRegionAvail().x
            V.muted(V.fit('Palatka AI · '..tostring(DSP.market.state.status or 'offline')..' · без автоматических сделок',math.max(40,remain-6)))
        end
        if V.popup_pending then
            local p=V.popup_pending;V.popup_pending=nil;imgui.OpenPopup(u(p.title)..'##v22_'..p.id)
        end
        if V.popups then V.popups()end
        V.resize_grip(g,io)
    end
    imgui.End();imgui.PopStyleVar(5)
    if colors and colors>0 then imgui.PopStyleColor(colors)end
    if U.open_ref and not U.open_ref[0]then M.flush_save(true);U.open=false end
end
-- Compatibility entry points preserve old commands and numbered screens.
local old_set=DSP.screens.set
DSP.screens.set=function(id)V.screen=id or 'palatka';return old_set(id)end
function V.selected_page(key,n,per)
    local max=math.max(1,math.ceil(n/per));local page=math.max(1,math.min(max,V.pages[key]or 1))
    V.pages[key]=page;return(page-1)*per+1,math.min(n,page*per),page,max
end

end
__mod_60_ui21_shell()

local function __mod_60a_carbon_home()
-- Carbon Trade 02: real landing screen with persistent sections and action tiles.
local V=DSP.ui21
local function metrics()
    local ok,r=pcall(function()return DSP.craglog.summary('day')end)
    return ok and type(r)=='table'and r or {}
end
function V.home()
    V.heading('Главная',function()
        if V.button('Обновить','carbon_refresh',126,false,true)then
            if DSP.market and DSP.market.state.status~='loading' then
                DSP.market.pull(DSP.detect_server() or DSP.market.state.sid or DSP.settings.server)
            end
        end
    end,130)
    V.list('carbon_home',function(w)
        V.muted('Обзор · данные игры и рынка; отсутствие источника не заменяется демонстрацией')
        local cw=math.max(90,(w-8)/3)
        if V.button('Найти сделку','carbon_quick_arb',cw,false,true)then V.set_screen('arbitrage')end
        V.inline(4)
        if V.button('Моя лавка','carbon_quick_shop',cw)then V.set_screen('lavki')end
        V.inline(4)
        if V.button('Сканировать','carbon_quick_storage',cw)then V.set_screen('scan')end
        imgui.Separator()
        local r=metrics()
        local cards={
            {'Денежный итог сегодня',r.net and DSP.money(r.net)or'Нет данных', 'из журнала'},
            {'Получено денег',r.income and DSP.money(r.income)or'Нет данных','это не прибыль'},
            {'Расходы',r.expense and DSP.money(r.expense)or'Нет данных','по журналу'},
            {'Рыночных позиций',tostring(#((DSP.market and DSP.market.state.rows)or{})),DSP.market.freshness()},
        }
        for i=1,4,2 do
            local cw2=math.max(90,(w-9)/2)
            for n=0,1 do
                local c=cards[i+n]
                if imgui.BeginChild('##carbon_metric_'..(i+n),imgui.ImVec2(cw2,91),true,imgui.WindowFlags.NoScrollbar)then
                    V.apply_font()
                    V.muted(V.fit(c[1],cw2-25))
                    V.green(V.fit(c[2],cw2-25))
                    V.muted(V.fit(c[3],cw2-25))
                    if imgui.GetWindowDrawList and imgui.GetWindowPos and imgui.GetColorU32 then
                        local dl=imgui.GetWindowDrawList()
                        local pos=imgui.GetWindowPos()
                        if dl and dl.AddLine then
                            dl:AddLine(imgui.ImVec2(pos.x+1,pos.y+1),imgui.ImVec2(pos.x+cw2-2,pos.y+1),
                                imgui.GetColorU32(imgui.Col.CheckMark),2)
                        end
                    end
                end
                imgui.EndChild()
                if n==0 then V.inline(8)end
            end
        end
        V.text('Быстрый доступ')
        local links={{'Арбитраж','arbitrage'},{'Продажа / скупка','palatka'},
            {'Скан лавки','scan'},{'Перепродажа','resale'},
            {'Авто-пиар','promo'},{'Журнал','logs'}}
        local cols=w>=560 and 3 or 2
        local cell=(w-8*(cols-1))/cols
        for i,entry in ipairs(links)do
            if V.button(entry[1],'carbon_link_'..i,cell)then V.set_screen(entry[2])end
            if i%cols~=0 and i<#links then V.inline(8)end
        end
        imgui.Separator()
        V.text('Последние события')
        local recent=DSP.craglog and DSP.craglog.ring_recent and DSP.craglog.ring_recent(4) or {}
        if #recent==0 then V.muted('Записей за сессию пока нет')end
        for j=#recent,1,-1 do
            local event=recent[j]
            if event then
                V.row('carbon_recent_'..j,43,function(ww,x,y)
                    V.at(x,y);V.muted(V.fit(os.date('%H:%M',event.ts or os.time())..' · '..
                        tostring((DSP.craglog.describe and DSP.craglog.describe(event)) or event.kind or 'Событие'),ww-12))
                end)
            end
        end
        imgui.Separator()
        V.text('Состояние системы')
        local st=DSP.market.state
        V.muted('API: '..tostring(st.status or '?')..' · Сервер: '..tostring(st.sid or '?'))
        V.muted('Данные могут устареть. Рыночная стоимость имущества не равна заработку.')
        if V.button('Цены / источники','carbon_link_prices',w)then V.set_screen('resale');V.flip_tab='prices'end
    end,{footer=function() V.muted('Carbon Trade · Главная · данные без вымысла')end})
end

end
__mod_60a_carbon_home()

local function __mod_60b_carbon_storage()
-- Safe container analyzer; cannot read bespoke game UIs without a packet parser.
local ffi=require('ffi')
local V,S,M=DSP.ui21,DSP.storage,DSP.mobile
V.storage_sort='value'
V.storage_selected=1
local function b(s,id,w,on,primary)return V.button(s,'storage_'..id,w,on,primary)end
-- One task per panel: scanner, snapshots, manual fallback. This avoids the
-- previous giant fixed header which pushed the item list off small screens.
function V.storage_screen()
    V.heading('Хранилища',function()
        if DSP.storage_beta_rollback and b('CRR ОТКАТ','beta_rollback',145,false,true) then
            V.open_popup('CRR откат','storage_beta_rollback')
        end
    end,DSP.storage_beta_rollback and 149 or 0)

    -- Old versions used "snapshots/manual". Collapse them into the two-task UI.
    if V.storage_tab=='snapshots' then V.storage_tab='library' end
    if V.storage_tab=='manual' then V.storage_tab='scan' end
    V.storage_tab=V.storage_tab or 'scan'
    V.storage_scan_mode=(V.storage_scan_mode=='inventory') and 'trunk' or (V.storage_scan_mode or 'trunk')
    V.storage_library_page=V.storage_library_page or 'list'

    local width=imgui.GetContentRegionAvail().x
    local tabw=math.max(120,(width-6)/2)
    for i,tab in ipairs({{'scan','СКАН'},{'library','МОИ ХРАНИЛИЩА'}})do
        if b(tab[2],'tab_'..tab[1],tabw,V.storage_tab==tab[1],V.storage_tab==tab[1])then
            V.storage_tab=tab[1]
            if tab[1]=='library' then V.storage_library_page='list' end
            V.reset_list('storage_scan_panel')
        end
        if i==1 then V.inline(6)end
    end
    imgui.Separator()

    if V.storage_tab=='scan' then
        V.list('storage_scan_panel',function(w)
            local options={{'trunk','Багажник'},{'cabinet','Шкаф'},{'warehouse','Склад'}}
            local bw=math.max(92,(w-12)/3)
            for i,item in ipairs(options)do
                if b(item[2],'choose_'..item[1],bw,V.storage_scan_mode==item[1],V.storage_scan_mode==item[1])then
                    if S.cancel_trunk_scan and V.storage_scan_mode=='trunk' and item[1]~='trunk' then
                        S.cancel_trunk_scan()
                    end
                    V.storage_scan_mode=item[1]
                    V.probe_error=nil
                    V.reset_list('storage_scan_panel')
                end
                if i<3 then V.inline(6)end
            end
            imgui.Separator()

            if V.storage_scan_mode~='trunk' then
                if V.storage_probe_panel then V.storage_probe_panel(w,V.storage_scan_mode)
                else V.red('Сканер этого хранилища недоступен.') end
                return
            end

            local t=(S.trunk_state and S.trunk_state()) or S.trunk or {}
            -- A review appears once per NEW completed 180-slot scan, and only
            -- when existing saved trunks share at least one item ID/enchant.
            if t.review_needed and t.review_generation
                and V.storage_match_generation~=t.review_generation
                and t.snapshot and t.status=='saved' and S.match_saved_trunks then
                V.storage_match_generation=t.review_generation
                local matches=S.match_saved_trunks(t.snapshot)
                if #matches>0 then
                    V.storage_match_review={
                        generation=t.review_generation, matches=matches, selected=1
                    }
                    V.open_popup('Похожий багажник','storage_match_confirm')
                else
                    t.review_needed=false
                end
            end
            local active=t.requested_at~=nil or t.status=='waiting_open' or
                t.status=='receiving' or t.status=='need_reopen'

            V.apply_font((V.font_pixels or 18)*1.18)
            V.text('НОВЫЙ СКАН БАГАЖНИКА')
            V.apply_font()

            if active then
                if t.status=='receiving' then
                    V.green('ПОЛУЧАЮ ДАННЫЕ: '..tostring(t.received or 0)..' / 180')
                    V.muted('Не закрывай багажник, пока не будет 180 / 180.')
                elseif t.status=='need_reopen' then
                    V.red('НУЖНО ЗАНОВО ОТКРЫТЬ БАГАЖНИК')
                    V.text('Закрой багажник полностью и открой его ещё раз.')
                    V.muted('Перемещение предметов внутри уже открытого багажника даёт только частичные изменения.')
                else
                    V.green('СКАН ЗАПУЩЕН')
                    V.text('Если багажник уже открыт — закрой его.')
                    V.text('Затем открой багажник заново обычным способом.')
                    V.muted('Жду полный снимок 180 / 180 слотов.')
                end
                V.muted('Получено: '..tostring(t.received or 0)..' / 180')
                if b('ОТМЕНИТЬ СКАН','cancel_trunk',math.min(w,240))then
                    S.cancel_trunk_scan()
                end
                V.muted('Предыдущий результат во время нового скана не показывается.')
                return
            end

            if t.status=='no_packets' or t.status=='incomplete' then
                V.red('НОВЫЙ СКАН НЕ ПОЛУЧЕН')
                V.text('Закрой багажник, нажми «Начать новый скан» и открой его заново.')
            elseif t.last_error and t.status~='saved' then
                V.red(V.fit(tostring(t.last_error),w))
            end

            if b('НАЧАТЬ НОВЫЙ СКАН','start_trunk',math.min(w,320),false,true)then
                S.begin_trunk_scan()
                V.storage_error=nil
                return
            end
            V.muted('Важно: скан запускается ДО повторного открытия багажника.')

            if t.snapshot and t.status=='saved' then
                imgui.Separator()
                V.green('ГОТОВО · 180 / 180')
                if t.last_warning then V.muted(V.fit(t.last_warning,w)) end
                V.text('Занято слотов: '..tostring(t.snapshot.occupied_slots or 0))
                V.text('Всего предметов: '..tostring(t.snapshot.count_known or 0))
                local sig=tostring(t.last_saved_at or t.snapshot.observed_at)..'/'..
                    tostring(DSP.market and DSP.market.state and DSP.market.state.version or '')
                local info=V.memo('storage_trunk_summary',sig,function()return S.evaluate(t.snapshot)end)
                if not info.cross_server then
                    V.green('Оценка скупки: '..DSP.money(info.sell_to_buyers))
                end

                if t.review_needed and V.storage_match_review
                    and V.storage_match_review.generation==t.review_generation then
                    if b('ПОХОЖИЕ БАГАЖНИКИ','show_matches',math.min(w,290),false,true)then
                        V.open_popup('Похожий багажник','storage_match_confirm')
                    end
                end
                local update_target=t.completed_update_target_id and S.find_snapshot(t.completed_update_target_id)
                if update_target then
                    V.text('Обновить: '..tostring(update_target.title))
                    if b('ПРИМЕНИТЬ К '..tostring(update_target.title),'apply_update',math.min(w,320),false,true)then
                        local ok,updated=S.apply_latest_to_saved(update_target.id)
                        if ok then
                            local _,idx=S.find_snapshot(updated.id)
                            V.storage_selected=idx or 1
                            V.storage_library_page='detail'
                            V.storage_tab='library'
                            return
                        else V.storage_error=tostring(updated) end
                    end
                    if b('СОХРАНИТЬ КАК НОВОЕ','save_update_new',math.min(w,290))then
                        V.storage_name_target=t.snapshot
                        V.storage_name_buf=imgui.new.char[128]()
                        V.storage_name_error=nil
                        V.open_popup('Сохранить багажник','storage_trunk_name')
                    end
                else
                    if b('СОХРАНИТЬ КАК НОВОЕ','save_new',math.min(w,290),false,true)then
                        V.storage_name_target=t.snapshot
                        V.storage_name_buf=imgui.new.char[128]()
                        V.storage_name_error=nil
                        V.open_popup('Сохранить багажник','storage_trunk_name')
                    end
                end
                if b('ОЧИСТИТЬ ПОСЛЕДНИЙ СКАН','clear_live',math.min(w,290))then
                    local ok,err=S.clear_live_snapshot()
                    if not ok then V.storage_error=tostring(err) end
                end
            end

            if V.storage_error then V.red(V.fit(V.storage_error,w)) end
            imgui.Separator()
            if b((t.autoscan_enabled and 'Автоскан: ВКЛ' or 'Автоскан: ВЫКЛ'),
                 'toggle_auto',math.min(w,210),t.autoscan_enabled)then
                local ok,err=S.set_trunk_autoscan(not t.autoscan_enabled)
                if not ok then V.storage_error=tostring(err) end
            end
            V.muted('Автоскан ловит полный снимок при открытии багажника. Он не угадывает машину по посадке в авто.')
        end,{footer=false})
        return
    end

    local snapshots=S.snapshots or {}
    local library=S.library and S.library() or {}

    if V.storage_library_page=='list' then
        V.apply_font((V.font_pixels or 18)*1.24)
        V.text('МОИ ХРАНИЛИЩА')
        V.apply_font()
        V.muted('Только сохранённые записи. Последний скан сюда не подмешивается.')
        if b('+ НОВЫЙ СКАН','library_new_scan',math.min(230,width),false,true)then
            V.storage_tab='scan'
            V.storage_scan_mode='trunk'
            S.begin_trunk_scan()
            V.reset_list('storage_scan_panel')
            return
        end
        V.muted('ПОИСК: по названию хранилища или предмета')
        local query=V.search and V.search('storage_all','Название или предмет...',math.min(380,width)) or ''
        query=DSP.lower(DSP.trim(query or ''))
        -- Search results are item-centric: show quantities of matched
        -- items per named container. Do NOT show the entire trunk count/value.
        if query~='' and S.search_library then
            local report=S.search_library(query)
            V.apply_font((V.font_pixels or 18)*1.12)
            V.text('НАЙДЕНО В '..tostring(report.storage_count)..' ХРАНИЛИЩАХ')
            V.apply_font()
            V.text('Подтверждено по запросу: '..tostring(report.known_qty)..' шт.')
            if report.unknown_slots>0 then
                V.red('Без точного количества: '..tostring(report.unknown_slots)..' слотов')
            end
            V.green('Оценка найденных предметов: '..DSP.money(report.priced_value))
            if report.unpriced_groups>0 then
                V.muted('Без цены: '..report.unpriced_groups..' видов предметов')
            end
            if report.different_server>0 then
                V.muted('С другого сервера: '..report.different_server..' хранилищ (без цены)')
            end
            V.muted('Сумма по сохранённым снимкам. Возможны повторные учёты.')
            local matches={}
            for _,entry in ipairs(report.results)do
                if entry.title_only then
                    matches[#matches+1]={entry=entry}
                else
                    for _,it in ipairs(entry.matched_items)do
                        matches[#matches+1]={entry=entry,item=it}
                    end
                end
            end
            if #matches==0 then
                V.muted('Таких предметов или хранилищ нет.')
                return
            end
            V.list_rows('storage_search_results',matches,136,function(match,i)
                local entry=match.entry
                local snap=entry.snapshot
                local it=match.item
                V.row('storage_result_'..i,136,function(rw,x,y)
                    V.at(x,y)
                    V.apply_font((V.font_pixels or 18)*1.09)
                    V.text(V.fit(tostring(snap.title or 'Без названия'),rw))
                    V.apply_font()
                    if it then
                        V.at(x,y+31)
                        V.text(V.fit(tostring(it.name or 'Предмет'),rw))
                        V.at(x,y+60)
                        local qty=tostring(it.qty)..' шт.'
                        if it.unknown_slots>0 then
                            qty=qty..' + ? ('..it.unknown_slots..' сл.)'
                        end
                        V.muted('Количество: '..qty)
                        V.at(x,y+88)
                        if it.total_buy then
                            V.green(V.fit('Скупка: '..DSP.money(it.total_buy)..
                                ' · '..DSP.money(it.unit_buy)..'/шт.',rw))
                        else
                            V.muted('Скупка: нет актуальной цены')
                        end
                    else
                        V.at(x,y+40)
                        V.muted('Совпало название хранилища, не название предмета')
                        V.at(x,y+75)
                        V.muted('Нажми, чтобы посмотреть содержимое')
                    end
                    V.at(x,y)
                    local pressed
                    if imgui.InvisibleButton then
                        pressed=imgui.InvisibleButton('##storage_search_open',
                            imgui.ImVec2(rw,124))
                    else
                        pressed=V.text_button('Открыть','storage_search_fallback',rw,false,124)
                    end
                    if pressed and not V.dragged then
                        V.storage_selected=entry.index
                        V.storage_detail_key=it and it.key or nil
                        V.storage_library_page='detail'
                        V.reset_list('storage_items')
                    end
                end)
            end,{footer=function()
                V.muted('Результатов: '..#matches..' · нажми карточку для просмотра')
            end})
            return
        end
        local filtered={}
        local grand,missing=0,0
        for _,entry in ipairs(library)do
            local snap=entry.snapshot
            local found=query=='' or DSP.lower(tostring(snap.title or '')):find(query,1,true)~=nil
            if not found then
                for _,it in ipairs(snap.rows or {})do
                    if DSP.lower(tostring(it.name or '')):find(query,1,true)then found=true;break end
                end
            end
            if found then filtered[#filtered+1]=entry end
            local value=S.evaluate(snap)
            if value.cross_server then missing=missing+1
            else grand=grand+(value.sell_to_buyers or 0) end
        end
        V.text('Хранилищ: '..#library..' | найдено: '..#filtered)
        V.green('Сумма оценок: '..DSP.money(grand))
        if missing>0 then V.muted('Без оценки: '..missing..' (другой сервер)') end
        V.muted('Это сумма оценок снимков, не реальная прибыль.')
        if #filtered==0 then
            V.muted(query=='' and 'Пока нет сохранённых хранилищ.' or 'Ничего не найдено.')
            return
        end
        V.list_rows('storage_library',filtered,95,function(entry,i)
            local snap=entry.snapshot
            local kind=snap.kind=='trunk'and'Багажник' or snap.kind=='cabinet'and'Шкаф'
                or snap.kind=='warehouse'and'Склад' or'Хранилище'
            V.row('storage_library_'..i,95,function(rw,x,y)
                V.at(x,y)
                V.apply_font((V.font_pixels or 18)*1.12)
                V.text(V.fit(tostring(snap.title or kind),rw))
                V.apply_font()
                V.at(x,y+43)
                local value=S.evaluate(snap)
                V.muted(V.fit(kind..' · '..tostring(snap.count_known or 0)..' шт. · '..
                    DSP.money(value.sell_to_buyers),rw))
                V.at(x,y)
                local hit
                if imgui.InvisibleButton then
                    hit=imgui.InvisibleButton('##open_storage_card',imgui.ImVec2(rw,84))
                else
                    hit=V.text_button(tostring(snap.title or kind),'storage_open_fallback',rw,false,84)
                end
                if hit and not V.dragged then
                    V.storage_selected=entry.index
                    V.storage_detail_key=nil
                    V.storage_library_page='detail'
                    V.reset_list('storage_items')
                end
            end)
        end,{footer=function()V.muted('Сохранено: '..#library..' / '..tostring(S.max_saved or 20))end})
        return
    end

    local current=snapshots[V.storage_selected or 1]
    if not current or current.source=='packet220_trunk' then
        V.storage_library_page='list'
        return
    end
    if b('< МОИ ХРАНИЛИЩА','library_back',math.min(230,width))then
        V.storage_library_page='list'
        return
    end

    V.apply_font((V.font_pixels or 18)*1.34)
    V.text(V.fit(tostring(current.title or 'Без названия'),width))
    V.apply_font()
    local kind=current.kind=='trunk'and'Багажник' or current.kind=='cabinet'and'Шкаф'
        or current.kind=='warehouse'and'Склад' or'Хранилище'
    V.muted(kind..' · '..os.date('%d.%m.%Y %H:%M',current.observed_at or os.time()))

    if current.source=='packet220_trunk_named' then
        if b('ОБНОВИТЬ СКАН','library_update',math.min(240,width),false,true)then
            S.begin_trunk_scan(current.id)
            V.storage_tab='scan'
            V.storage_scan_mode='trunk'
            return
        end
    end
    if b('Переименовать','rename',math.min(180,width))then
        V.storage_label_target=current
        V.storage_label_buf=imgui.new.char[128]()
        ffi.copy(V.storage_label_buf,DSP.utf8(tostring(current.title or '')):sub(1,120))
        V.storage_label_error=nil
        V.open_popup('Название снимка','storage_rename_v283')
    end
    if b('УДАЛИТЬ','delete_one',math.min(150,width))then
        V.storage_delete_target=current
        V.storage_delete_error=nil
        V.open_popup('Удалить хранилище','storage_delete_one')
    end

    local rows,info=S.sorted(current,V.storage_sort)
    if V.storage_detail_key then
        local only={}
        for _,it in ipairs(rows)do
            if it.key==V.storage_detail_key then only[#only+1]=it end
        end
        if #only>0 then
            rows=only
            V.muted('Показан найденный предмет · '..tostring(only[1].name))
            if b('ПОКАЗАТЬ ВСЁ','show_all_contents',math.min(200,width))then
                V.storage_detail_key=nil
                V.reset_list('storage_items')
            end
        else
            V.storage_detail_key=nil
        end
    end
    if V.storage_detail_key then
        V.text('Найдено: '..tostring(rows[1].qty or 0)..' шт.')
        if (rows[1].unknown_slots or 0)>0 then
            V.muted('Есть слоты без подтверждённого количества: '..rows[1].unknown_slots)
        end
    else
        V.text('Предметов: '..info.total_qty..' шт.')
    end
    if current.kind=='trunk' then
        V.muted('Занято слотов: '..tostring(current.occupied_slots or #current.rows)..
            ' / '..tostring(current.slots_count or 180))
    elseif current.source=='packet220_probe' then
        V.red('Предварительный снимок: полный формат этого хранилища ещё проверяется.')
    end
    if V.storage_detail_key and #rows==1 then
        local item=rows[1]
        if not info.cross_server and item.bid then
            V.green('Оценка этого предмета: '..DSP.money((item.qty or 0)*item.bid))
            V.muted('Цена скупки: '..DSP.money(item.bid)..' / шт.')
        else
            V.muted('Нет актуальной цены скупки для найденного предмета.')
        end
    else
        V.green('Оценка скупки всего хранилища: '..DSP.money(info.sell_to_buyers))
        V.muted('По объявлениям: '..DSP.money(info.ask_value)..' · не чистая прибыль')
    end

    V.list_rows('storage_items',rows,82,function(it,i)
        V.row('storage_item_'..i,82,function(rw,x,y)
            V.at(x,y);V.text(V.fit(it.name,rw))
            V.at(x,y+30)
            V.muted(V.fit('Количество: '..(it.qty and tostring(it.qty)..' шт.'or'неизвестно'),rw))
            V.at(x,y+56)
            local total=(it.bid and it.qty)and DSP.money(it.bid*it.qty)or'нет оценки'
            V.muted(V.fit('Скупают: '..(it.bid and DSP.money(it.bid)or'?')..' / шт. · '..total,rw))
        end)
    end,{footer=false})
end

-- Deletion is a real modal confirmation; cancellation never changes snapshots.
local old_popups=V.popups
function V.popups()
    if old_popups then old_popups()end
    V.popup('CRR откат','storage_beta_rollback',function()
        V.text('Вернуть стабильную Palatka AI с обычным интерфейсом?')
        V.muted('Тестовый сканер будет отключён. Настройки, пресеты и снимки не удаляются.')
        if b('ПОДТВЕРДИТЬ ОТКАТ','beta_rollback_confirm',230,false,true)then
            local ok,err=DSP.storage_beta_rollback()
            if ok then
                imgui.CloseCurrentPopup()
            else
                V.storage_rollback_error=tostring(err)
            end
        end
        V.inline()
        if b('Отмена','beta_rollback_cancel',110)then imgui.CloseCurrentPopup()end
        if V.storage_rollback_error then V.red(V.fit(V.storage_rollback_error,imgui.GetContentRegionAvail().x))end
    end,{w=480,h=260})
    V.popup('Похожий багажник','storage_match_confirm',function()
        local review=V.storage_match_review
        local t=S.trunk_state()
        if not review or not t.snapshot or not t.review_needed
            or review.generation~=t.review_generation then
            V.muted('Этот скан уже обработан или заменён новым.')
            if b('Закрыть','match_stale',120)then imgui.CloseCurrentPopup()end
            return
        end
        local matches=review.matches or {}
        if #matches==0 then
            V.muted('Сохранённых похожих багажников нет.')
            if b('Закрыть','match_empty',120)then imgui.CloseCurrentPopup()end
            return
        end
        review.selected=math.max(1,math.min(#matches,review.selected or 1))
        local match=matches[review.selected]
        local saved=S.find_snapshot(match.id)
        if not saved then
            V.red('Эта сохранённая запись удалена.')
            if b('Закрыть','match_deleted',120)then imgui.CloseCurrentPopup()end
            return
        end
        V.apply_font((V.font_pixels or 18)*1.22)
        V.text(V.fit(tostring(saved.title or 'Багажник'),imgui.GetContentRegionAvail().x))
        V.apply_font()
        V.text('Это тот же багажник?')
        V.green('Совпадает типов предметов: '..match.shared)
        V.muted('Похожесть состава: '..match.similarity..'% · это НЕ вероятность и не ID машины.')
        V.muted('Подтвердить, какая машина открыта, можешь только ты.')
        if #matches>1 then
            V.muted('Вариант '..review.selected..' из '..#matches)
            if b('ДРУГОЙ ПОХОЖИЙ','match_next',math.min(230,imgui.GetContentRegionAvail().x))then
                review.selected=review.selected%#matches+1
            end
        end
        imgui.Separator()
        if b('ДА, ЭТО '..tostring(saved.title),'match_yes',math.min(310,imgui.GetContentRegionAvail().x),false,true)then
            local ok,updated=S.apply_latest_to_saved(saved.id)
            if ok then
                local _,idx=S.find_snapshot(updated.id)
                V.storage_selected=idx or 1
                V.storage_library_page='detail'
                V.storage_tab='library'
                V.storage_match_error=nil
                imgui.CloseCurrentPopup()
            else
                V.storage_match_error=tostring(updated)
            end
        end
        if b('НЕТ, ЭТО НОВЫЙ','match_no_new',math.min(280,imgui.GetContentRegionAvail().x))then
            local snap=t.snapshot
            V.storage_name_target=snap
            V.storage_name_buf=imgui.new.char[128]()
            V.storage_name_error=nil
            t.review_needed=false
            imgui.CloseCurrentPopup()
            V.open_popup('Сохранить багажник','storage_trunk_name')
        end
        if b('НЕ УВЕРЕН · ПОЗЖЕ','match_later',math.min(240,imgui.GetContentRegionAvail().x))then
            imgui.CloseCurrentPopup()
        end
        if V.storage_match_error then
            V.red(V.fit(V.storage_match_error,imgui.GetContentRegionAvail().x))
        end
    end,{w=495,h=410})
    V.popup('Сохранить багажник','storage_trunk_name',function()
        local target=V.storage_name_target
        if not target then V.red('Нет полного снимка багажника.');return end
        V.text('Введи своё название сохранённого снимка')
        V.muted('Например: Моя машина с ларцами / Машина с ресурсами.')
        V.muted('Следующее открытие другого багажника НЕ будет иметь это название автоматически.')
        imgui.SetNextItemWidth(-1)
        imgui.InputText('##storage_trunk_named_input',V.storage_name_buf,128)
        if b('Сохранить под названием','save_named_trunk',math.min(240,imgui.GetContentRegionAvail().x),false,true)then
            local name=DSP.to_cp(ffi.string(V.storage_name_buf))
            local ok,snapshot=S.save_named_trunk(target,name)
            if ok then
                V.storage_name_target=nil
                V.storage_name_error=nil
                V.storage_tab='library'
                V.storage_library_page='detail'
                for i,saved in ipairs(S.snapshots or {})do
                    if saved==snapshot then V.storage_selected=i;break end
                end
                imgui.CloseCurrentPopup()
            else
                V.storage_name_error=tostring(snapshot)
            end
        end
        if b('Отмена','cancel_named_trunk',120)then imgui.CloseCurrentPopup()end
        if V.storage_name_error then V.red(V.fit(V.storage_name_error,imgui.GetContentRegionAvail().x))end
    end,{w=460,h=330})
    V.popup('Своя цена','storage_price',function()
        local target,row=V.storage_price_target,V.storage_price_row
        if not target or not row then V.muted('Нет выбранного предмета');return end
        V.text(V.fit(row.name,imgui.GetContentRegionAvail().x))
        V.muted('Цена за одну штуку для расчёта этого снимка. 0 = цена API.')
        M.compact_number(V.storage_price_buf,'value','storage_price_value',math.min(250,imgui.GetContentRegionAvail().x),0)
        if b('Сохранить','price_apply',135,false,true)then
            local ok,err=S.set_manual_price(target,row,V.storage_price_buf.value)
            if ok then V.reset_list('storage_items');V.storage_price_target=nil;imgui.CloseCurrentPopup()
            else V.storage_price_error=err end
        end
        V.inline();if b('Отмена','price_cancel',110)then imgui.CloseCurrentPopup()end
        if V.storage_price_error then V.red(V.storage_price_error)end
    end,{w=460,h=260})
    V.popup('Название снимка','storage_rename_v283',function()
        local target=V.storage_label_target
        if not target then return end
        V.muted('Это имя только для снимка. ID машины автоматически не определяется.')
        imgui.SetNextItemWidth(-1)
        imgui.InputText('##storage_name_input',V.storage_label_buf,128)
        if b('Сохранить','rename_apply',135,false,true)then
            local label=DSP.to_cp(ffi.string(V.storage_label_buf))
            local ok,result=S.set_snapshot_label(target,label)
            if ok then
                V.storage_label_target=nil
                if type(result)=='table' then
                    for i,saved in ipairs(S.snapshots or {})do
                        if saved==result then V.storage_selected=i;break end
                    end
                    V.storage_library_page='detail'
                end
                imgui.CloseCurrentPopup()
            else V.storage_label_error=result end
        end
        V.inline();if b('Отмена','rename_cancel',110)then imgui.CloseCurrentPopup()end
        if V.storage_label_error then V.red(V.storage_label_error)end
    end,{w=640,h=300})
    V.popup('Удалить хранилище','storage_delete_one',function()
        local target=V.storage_delete_target
        if not target then V.muted('Хранилище уже не выбрано.');return end
        V.text('Удалить «'..tostring(target.title or 'Без названия')..'»?')
        V.muted('Удаляется только запись Palatka AI. Предметы в игре не меняются.')
        if b('УДАЛИТЬ','delete_one_confirm',150,false,true)then
            local ok,err=S.delete_snapshot(target)
            if ok then
                V.storage_delete_target=nil
                V.storage_delete_error=nil
                V.storage_selected=1
                V.storage_library_page='list'
                imgui.CloseCurrentPopup()
            else V.storage_delete_error=tostring(err) end
        end
        V.inline()
        if b('Отмена','delete_one_cancel',110)then imgui.CloseCurrentPopup()end
        if V.storage_delete_error then V.red(V.storage_delete_error)end
    end,{w=470,h=250})
    V.popup('Очистить снимки?','storage_clear',function()
        V.text('Удалить сохранённые снимки шкафов и багажников?')
        V.muted('Предметы в игре останутся без изменений.')
        if b('Удалить снимки','confirm_clear',170,false,true)then
            local old=S.snapshots
            S.snapshots={};S.last_signature=nil;S.last_snapshot=nil;V.storage_selected=1;V.storage_library_page='list'
            local old_trunk=S.trunk and S.trunk.snapshot
            if S.trunk then S.trunk.snapshot=nil;S.trunk.pending=nil;S.trunk.status='idle';S.trunk.received=0 end
            if DSP.settings then DSP.settings.storage_snapshots=S.snapshots end
            if DSP.save_settings and not DSP.save_settings() then
                S.snapshots=old
                if S.trunk then S.trunk.snapshot=old_trunk;S.trunk.status='saved' end
                if DSP.settings then DSP.settings.storage_snapshots=old end
                V.storage_error='Не удалось сохранить удаление';return
            end
            imgui.CloseCurrentPopup()
        end
        V.inline()
        if b('Отмена','cancel_clear',120)then imgui.CloseCurrentPopup()end
    end,{w=480,h=230})
end

end
__mod_60b_carbon_storage()

local function __mod_60e_storage_probe_ui()
-- Simplified read-only cabinet / warehouse observer.
-- Personal inventory scan intentionally removed from the UI.
local V = DSP.ui21
local P = DSP.storage_probe
local labels={cabinet='ШКАФ',warehouse='СКЛАД'}
local descriptions={cabinet='шкаф',warehouse='склад'}
local function button(label,id,width,active,primary)
    return V.button(label,'probe_'..id,width,active,primary)
end

function V.storage_probe_panel(width,kind)
    width=math.max(190,tonumber(width) or 300)
    local w=math.min(width,315)
    if not P then V.red('Сканер этого контейнера недоступен.');return end
    if not labels[kind] then V.red('Неизвестный тип хранилища.');return end
    local state=P.state()

    V.apply_font((V.font_pixels or 18)*1.15)
    V.text(labels[kind])
    V.apply_font()

    if state.armed and state.kind~=kind then
        V.red('Сейчас идёт скан другого хранилища.')
        if button('Остановить текущий скан','stop_other',w,false,true)then P.stop()end
        return
    end

    if state.kind~=kind and not state.armed then
        V.muted('Нажми «Начать скан», затем закрой Palatka AI и открой '..descriptions[kind]..' в игре.')
        if button('НАЧАТЬ СКАН','arm_'..kind,w,false,true)then
            P.arm(kind,40)
            V.probe_selected=1
            V.probe_error=nil
        end
        return
    end

    if state.armed then
        V.green('СКАН ЗАПУЩЕН')
        V.muted('Открой '..descriptions[kind]..' в игре. После этого вернись сюда.')
        V.muted('Осталось: '..math.max(0,state.until_ts-os.time())..' сек.')
        if button('ЗАВЕРШИТЬ И ПОКАЗАТЬ','stop',w,false,true)then P.stop()end
        return
    end

    if #state.order==0 then
        V.red('Содержимое не распознано.')
        V.muted('Попробуй запустить скан ещё раз и заново открыть '..descriptions[kind]..'.')
        if button('ПОВТОРИТЬ СКАН','arm_'..kind,w,false,true)then
            P.arm(kind,40);V.probe_selected=1;V.probe_error=nil
        end
        return
    end

    V.probe_selected=math.max(1,math.min(#state.order,V.probe_selected or 1))
    local selected=V.probe_selected
    if #state.order>1 then
        V.muted('Найдено несколько вариантов: '..selected..' / '..#state.order)
        if button('Следующий вариант','next',w)then
            selected=selected%#state.order+1
            V.probe_selected=selected
        end
    end

    local info,err=P.preview(selected)
    if not info then V.red(tostring(err));return end

    V.green('НАЙДЕНО: '..tostring(info.occupied)..' занятых слотов')
    V.text('Подтверждено предметов: '..tostring(info.known))
    if info.unknown_qty>0 then
        V.muted('Без точного количества: '..tostring(info.unknown_qty)..' строк')
    end

    if DSP.storage and DSP.storage.evaluate then
        local estimate=DSP.storage.evaluate({kind=kind,rows=info.rows,
            server=DSP.market and DSP.market.state and DSP.market.state.sid})
        if not estimate.cross_server then
            V.green('Оценка скупки: '..DSP.money(estimate.sell_to_buyers))
            if estimate.missing_prices>0 then
                V.muted('Нет цен для '..estimate.missing_prices..' строк')
            end
        end
    end

    V.red('Пока это предварительный скан: полный формат '..descriptions[kind]..' ещё проверяется.')
    if button('СОХРАНИТЬ РЕЗУЛЬТАТ','save',w,false,true)then
        local ok,saved=P.save(selected)
        if ok then
            V.probe_error=nil
            V.storage_tab='library'
            V.storage_library_page='list'
        else
            V.probe_error=tostring(saved)
        end
    end
    if button('ПОВТОРИТЬ СКАН','arm_'..kind,w)then
        P.arm(kind,40);V.probe_selected=1;V.probe_error=nil
    end
    if V.probe_error then V.red(V.fit(V.probe_error,width))end
end

end
__mod_60e_storage_probe_ui()

local function __mod_60c_carbon_draw()
-- Carbon Trade lightweight skin primitives; existing ImGui handles input and clipping.
-- Geometry only for visible rows, no bitmap allocations or HTTP.
DSP.carbon_draw = DSP.carbon_draw or {}
local D=DSP.carbon_draw
D.frame_shapes=0
D.max_shapes=240
function D.begin_frame()
    D.frame_shapes=0
end
function D.row(x,y,w,h)
    if DSP.settings and DSP.settings.carbon_draw_enabled==false then return false end
    if D.frame_shapes+3>D.max_shapes then return true end
    if not imgui or not imgui.GetWindowDrawList or not imgui.GetColorU32 then return false end
    local draw=imgui.GetWindowDrawList()
    if not draw then return false end
    local p1=imgui.ImVec2(x,y)
    local p2=imgui.ImVec2(x+w,y+h)
    draw:AddRectFilled(p1,p2,imgui.GetColorU32(imgui.Col.FrameBg),5)
    if draw.AddRect then draw:AddRect(p1,p2,imgui.GetColorU32(imgui.Col.Border),5) end
    if draw.AddLine then
        draw:AddLine(imgui.ImVec2(x+5,y+1),imgui.ImVec2(x+w-5,y+1),imgui.GetColorU32(imgui.Col.CheckMark),1)
    end
    D.frame_shapes=D.frame_shapes+3
    return true
end

end
__mod_60c_carbon_draw()

local function __mod_61_ui21_trade()
-- Trade view: two tabs, inline editing, fixed actions; execution stays in auto.
local ffi=require('ffi')
local V,M,T=DSP.ui21,DSP.mobile,DSP.trade_v16
local function busy()return DSP.auto.buy_running or DSP.auto.sell_running end
local function preset()return V.kind=='sell'and DSP.settings.sell_preset or DSP.settings.buy_preset end
local function b(s,id,w,on)return V.button(s,'trade_'..id,w,on)end
local function money(n)
    local text=string.format('%.0f',math.abs(n)):reverse():gsub('(%d%d%d)','%1.'):reverse():gsub('^%.','')
    return (n<0 and '-$'or'$')..text
end
local function report(ok,msg)DSP.notify(ok and tostring(msg or 'Готово')or('Не удалось: '..tostring(msg or '?')))end
function V.trade_add(source,it)
    if source=='inventory'then return T.add_from_inventory(V.kind,it)end
    return T.add_from_catalog(V.kind,it)
end
local function launch()
    local checked,ok,issues=pcall(T.validate,V.kind)
    if not checked then
        DSP.flog('PRESET validate error: '..tostring(ok))
        DSP.notify('Preset check failed; see standalone.log')
        return false
    end
    if not ok then V.tab='preset';report(false,table.concat(issues,'; '));return false end
    local started=DSP.auto.safe_start(V.kind)
    if started~=true then
        DSP.notify('Выставление не запущено: смотрите причину в статусе торговли')
        return false
    end
    return true
end
local function footer_height()return math.ceil((imgui.GetFontSize and imgui.GetFontSize()or 16)*2+62)end
local function footer(key)
    local r=T.totals(V.kind)
    local w=imgui.GetContentRegionAvail().x
    local first,second
    if not r.complete then
        first=(V.kind=='buy'and'Бюджет'or'Выручка')..' — итог не рассчитан'
        second=r.overflow and 'Сумма вне точного диапазона' or r.invalid_tax and 'Проверьте комиссию' or ('Проверьте цену / количество: '..r.invalid..' поз.')
    elseif V.kind=='buy'then
        first='Бюджет скупки '..money(r.required_funds)
        second=r.positions..' поз. · '..r.qty..' шт. · Без комиссии продажи'
    else
        first='Выручка '..money(r.gross)..' · Комиссия ~ '..money(r.commission)
        second='Чистыми ~ '..money(r.net)..' · Прибыль '..(r.profit and '~ '..money(r.profit)or'— нет себестоимости')
    end
    V.text(V.fit(first,w));V.muted(V.fit(second,w))
    local x,y=imgui.GetCursorPosX(),imgui.GetCursorPosY()
    local info=(DSP.settings.dry_run and 'ТЕСТ'or'РЕАЛЬНО')
