        imgui.SameLine(0,5)
        if btn('>','next',47,30)then A.next(1);A.qty_key=nil end
        imgui.SameLine(0,5)
        local e,i=selected(s)
        if e and btn('Пропустить','skip',100,30)then A.skip(i,true);A.next(1);A.qty_key=nil end
        imgui.SameLine(0,5)
        if btn('Меню','main',65,30)then
